// 文法データ
// THM: 文法の「定理」.s: 定理の内容, def: 前提になる定義
// GRAM: 問題.q の ____ が空所, c: 選択肢, a: 正解の添字, t: 使う定理, d: 難易度
window.THM = {
  T1: { name: "名詞の前の空所", s: "「冠詞・所有格 + ___ + 名詞」の空所には形容詞が入る.", def: "形容詞:名詞を修飾する語." },
  T2: { name: "動詞を修飾する位置", s: "動詞・過去分詞を修飾する位置(be + ___ + 過去分詞,動詞 + ___ など)には副詞が入る.", def: "副詞:動詞・形容詞・文など,名詞以外を修飾する語." },
  T3: { name: "名詞が入る位置", s: "冠詞・所有格・前置詞の直後で,後ろに名詞が続かない空所には名詞が入る.他動詞の目的語の位置も名詞.名詞が2つ選べるときは,人か物かを意味で決める.", def: "名詞:主語・目的語になる語." },
  T4: { name: "現在完了の目印", s: "「since + 過去の時点」「for / over the past + 期間」「so far」があれば,動詞は現在完了形(have + 過去分詞).もう終わっていて今につながらない期間なら過去形.", def: "現在完了:過去から現在までつながる継続・経験・完了." },
  T5: { name: "時・条件の副詞節", s: "when, if, before, after, until, once, as soon as, by the time などの時・条件を表す副詞節の中では,未来のことも現在形(完了は現在完了形)で表す.", def: "副詞節:文全体に時・条件などの情報を足す節." },
  T6: { name: "受動態", s: "主語が動作を受ける側なら受動態(be + 過去分詞).完了形と組むと have been + 過去分詞,進行形と組むと be being + 過去分詞.occur, happen, arrive など目的語をとらない自動詞は受動態にしない.", def: "受動態:「〜される」を表す形." },
  T7: { name: "前置詞 to の後ろ", s: "look forward to, be used to, be committed / dedicated to, in addition to, prior to, object to, contribute to の to は前置詞.前置詞の後ろは名詞か動名詞(-ing)が入る.be のない used to + 原形(以前は〜した)は別の表現.", def: "動名詞:動詞に -ing を付けて名詞として使う形." },
  T8: { name: "関係代名詞の選択", s: "先行詞が人なら who(節の中で目的語なら whom),物なら which.カンマの後(非制限用法)では that は使えない.先行詞があるときに what は使えない.", def: "関係代名詞:前の名詞(先行詞)を後ろから説明する節をつくる語." },
  T9: { name: "前置詞と接続詞", s: "前置詞の後ろは名詞句,接続詞の後ろは節(主語 + 動詞).despite, during, because of, due to は前置詞,although, while, because は接続詞.while / when + -ing は主語と be 動詞を省いた形で,接続詞のまま使える.", def: "節:主語と動詞を含むまとまり." },
  T10: { name: "主語と動詞の一致", s: "動詞の数は主語の中心の名詞で決める.of 以下や前置詞句,関係詞節の中の名詞につられない.each of + 複数名詞,everyone,数えられない名詞は単数扱い.along with, as well as が付いても主語は増えない.There is / are は後ろの名詞に合わせる.", def: "一致:主語の数(単数・複数)に動詞の形を合わせること." },
  T11: { name: "比較の形", s: "than があれば比較級(-er / more).as ___ as の間は原級.the + 最上級(-est / most)は「〜の中でいちばん」.比較級を強めるのは much / far(very は不可).the + 比較級, the + 比較級 は「〜すればするほど…」.", def: "原級:比べない元の形.比較級:2つを比べる形.最上級:3つ以上の中で一番を表す形." },
  T12: { name: "分詞の形容詞用法", s: "修飾される名詞(または主語)が「〜させる・〜する」側なら現在分詞(-ing),「〜させられる・〜される」側なら過去分詞(-ed).", def: "分詞:動詞を形容詞のように使う形.現在分詞(-ing)は能動,過去分詞(-ed)は受け身の意味をもつ." },
  T13: { name: "代名詞の格", s: "名詞の前は所有格(his, their),動詞・前置詞の目的語は目的格(him, them).主語と同じ人を指す目的語や by ___(自分で)は再帰代名詞(himself, themselves).「〜のもの」は所有代名詞(mine, ours, theirs)で,後ろに名詞を置かない.", def: "格:文の中での役割(主語・所有・目的語)に応じた代名詞の形." },
  T14: { name: "ペアで使う接続詞", s: "both A and B / either A or B / neither A nor B / not only A but (also) B は組み合わせが決まっている.後ろの語から前の語を決める.either A or B / neither A nor B が主語のとき,動詞は B に合わせる.", def: "相関接続詞:2語1組で A と B をつなぐ接続詞." },
  T15: { name: "to do をとる動詞・-ing をとる動詞", s: "decide, plan, hope, agree, expect, want, afford は目的語に to do をとる.avoid, consider, finish, enjoy, suggest, mind は -ing をとる.remember は to do(これから忘れずにする)と -ing(したことを覚えている)で意味が変わる.", def: "不定詞:to + 動詞の原形.これからのことを表しやすい." },
  T16: { name: "要求・提案の that 節", s: "request, recommend, suggest, propose, require, demand, insist, advise などに続く that 節(It is recommended / essential / important that ... も同じ)では,主語に関係なく動詞は原形.否定は not + 原形.", def: "原形:-s や -ed の付かない,動詞の元の形." },
  T17: { name: "数量を表す語", s: "many / few + 数えられる名詞の複数形,much / little + 数えられない名詞(information, equipment, advice など).every / each + 単数形(単数扱い).all the + 複数名詞.a number of + 複数名詞 は複数扱い,the number of + 複数名詞 は単数扱い.", def: "可算名詞:1つ,2つと数えられる名詞.不可算名詞:time, information など数えられない名詞." },
  T18: { name: "by と until", s: "by は期限(その時までに1回済ませる),until は継続(その時までずっと続く).by the time + 節 は「〜するときまでには」.", def: "期限:それまでに終える時点.継続:ある状態が続くこと." },
  T19: { name: "whose と what", s: "空所の後ろが「冠詞のない名詞 + 動詞」で,先行詞の持ち物・属性を表すなら whose.先行詞がなく「〜すること・もの」を表すなら what.", def: "先行詞:関係詞の節が説明する,前にある名詞." },
  T20: { name: "補語になる形容詞", s: "be, become, remain, seem, stay, look, sound などの後ろ(補語の位置)には形容詞が入る.副詞は補語になれない.keep / make / find + 目的語 + 形容詞 の形でも,目的語の状態を説明するのは形容詞.", def: "補語:主語の状態を説明する語." },
  T21: { name: "if を省いた倒置", s: "if を省くと主語と助動詞の順が入れ替わる.Should + 主語 + 原形(万一〜なら),Had + 主語 + 過去分詞(もし〜だったら),Were + 主語(もし〜なら),Were + 主語 + to do(仮に〜するとしたら).", def: "倒置:主語と(助)動詞の順番が入れ替わること." },
  T22: { name: "仮定法", s: "今の事実と違う仮定は「If + 過去形, would + 原形」.過去の事実と違う仮定は「If + had + 過去分詞, would have + 過去分詞」.I wish + 過去形 は「〜ならいいのに」.主節が will なら仮定法ではなく,ふつうの条件(現在形).", def: "仮定法:事実と違うことを仮定する形.時制を1つ過去にずらす." },
  T23: { name: "分詞構文", s: "カンマの前の分詞のまとまりは,主節の主語が意味上の主語.主語が「〜する」側なら -ing,「〜される」側なら過去分詞.Having + 過去分詞 は主節より前に済んだこと.文の後ろや接続詞(when, while)の後ろにも置ける.", def: "分詞構文:分詞で始まるまとまりが「接続詞 + 主語 + 動詞」の代わりをする形." },
  T24: { name: "so と such", s: "「とても〜なので…」は so + 形容詞・副詞 + that,such + (a) + 形容詞 + 名詞 + that.名詞があれば such.ただし many / much / few / little が付く名詞は so(so many orders).such that は「それほどのものなので」.", def: "結果の that:前の程度の結果を表す節." },
  T25: { name: "接続副詞は節をつながない", s: "however, therefore, nevertheless, moreover, otherwise は副詞.ピリオドやセミコロンの後に置き,カンマだけで2つの節をつなぐことはできない.カンマで節をつなぐのは but, so, and や although などの接続詞.", def: "接続副詞:意味の上で前の文とつなぐが,文法上は副詞の語." },
  T26: { name: "条件の接続詞", s: "unless は「〜しない限り(= if not)」.as long as / provided (that) は「〜という条件で」.in case は「〜する場合に備えて」.", def: "接続詞:節と節をつなぐ語." },
  T27: { name: "決まった前置詞", s: "組み合わせで覚える.be responsible for, be eligible for, comply with, be aware of, in charge of, depend on, be committed to(-ing), be subject to, specialize in, refrain from, be equipped with.", def: "前置詞:名詞の前に置いて関係を示す語." },
  T28: { name: "未来完了と過去完了", s: "「by + 未来の時点」までに完了することは未来完了(will have + 過去分詞).過去のある時点より前に済んだことは過去完了(had + 過去分詞).", def: "完了形:ある時点までに完了・継続していることを表す形." },
  T29: { name: "使役動詞", s: "have / make / let + 人 + 動詞の原形.have + 物 + 過去分詞 は「(物を)〜してもらう」.get + 人 + to do(to が必要),help + 人 + (to) 原形.", def: "使役動詞:人や物に何かをさせることを表す動詞." },
  T30: { name: "関係副詞 where と which", s: "空所の後ろが完全な文(主語も目的語もそろっている)なら関係副詞 where(先行詞が時なら when).主語や目的語が欠けていれば関係代名詞 which.前置詞 + which = where(in which).", def: "関係副詞:先行詞(場所・時など)を説明し,節の中で副詞の働きをする語." },
  T31: { name: "目的を表す形", s: "「〜するために」は to do / in order to do / so that + 主語 + can(will)+ 原形.後ろが動詞の原形なら in order to,節(主語 + 動詞)なら so that.for は後ろに名詞(for the meeting)か -ing の用途(for cutting).", def: "目的:動作をする理由・ねらい." },
  T32: { name: "時を表す前置詞", s: "時刻・時点は at(at 3:00),曜日・日付は on(on Monday, on May 5),月・年・季節・長い期間は in(in June, in 2025).within は「〜以内に」,throughout は「〜の間ずっと」,in + 期間 は「〜後に」.", def: "前置詞:名詞の前に置いて,時・場所・関係を表す語." },
  T33: { name: "自動詞と他動詞", s: "他動詞は前置詞なしで目的語をとる(discuss the plan, attend the meeting, reach the station, contact us, enter the room).自動詞は前置詞が必要(respond to, arrive at, reply to, apologize for).rise / raise,lie / lay は自動詞と他動詞の組.", def: "自動詞:目的語をとらない動詞.他動詞:目的語(〜を)をとる動詞." },
  T34: { name: "時制の目印", s: "ago, yesterday, last 〜, in + 過去の年 → 過去形.tomorrow, next 〜, soon → 未来(will).currently, now, at the moment → 進行形.usually, every 〜, always → 現在形.", def: "時制:動詞の形で,いつのことかを表す仕組み." },
  T35: { name: "名詞節をつくる語", s: "「〜かどうか」は whether(if).「〜ということ」は that.疑問詞(how, when, where, why, what)が名詞節をつくるときは,後ろが「主語 + 動詞」の順(間接疑問).whether の後ろには or not を置ける,前置詞の後ろは whether(if は不可).", def: "名詞節:文の中で主語や目的語になる節." },
  T36: { name: "other と another", s: "another + 単数名詞(もう1つの),other + 複数名詞(ほかの),the other(2つのうちの残りの1つ・残り全部),others(ほかの人・物.単独で使う),each other(お互い).", def: "限定:the が付くと「残りの全部」に決まる." },
  T37: { name: "対比・譲歩の接続詞", s: "whereas / while(一方で〜)は2つを対比する.even though(〜だけれども)は事実,even if(たとえ〜でも)は仮定.whereas, although は接続詞で,後ろに節が来る.", def: "譲歩:相手の言い分を認めつつ,反対のことを言うこと." },
  T38: { name: "決まった前置詞のまとまり", s: "according to(〜によると),in addition to(〜に加えて),instead of(〜の代わりに),on behalf of(〜を代表して),regardless of(〜に関係なく),in spite of(〜にもかかわらず),as of(〜時点で・〜から),because of(〜のため).後ろは名詞か -ing.", def: "群前置詞:2語以上で1つの前置詞の働きをするまとまり." },
  T39: { name: "人を目的語にとる動詞の形", s: "inform / notify / remind / assure + 人 + of 〜 / that 節.explain / suggest / mention + (to 人) + 内容(explain 人 〜 は不可).tell + 人 + 内容,say + 内容(say 人 は不可).", def: "目的語:動詞の動作を受ける語." },
  T40: { name: "to do を続ける形容詞と名詞", s: "be able / likely / willing / eager / reluctant / pleased + to do.ability / plan / effort / decision / opportunity + to do.be worth -ing,be busy -ing は -ing.", def: "不定詞の形容詞用法:to do が前の名詞を説明する使い方." },
  T41: { name: "否定語で始まる倒置", s: "Never, Rarely, Seldom, Hardly, Not only, Only + 副詞句, Not until などの否定・限定の語句が文頭に来ると,後ろは疑問文と同じ語順(助動詞・be 動詞 + 主語)になる.", def: "倒置:強調のために主語と(助)動詞の順番を入れ替えること." },
  T42: { name: "前の名詞を受ける代名詞", s: "同じ種類の別の物は one(複数は ones),同じ物そのものは it(複数は them).the + 名詞 + of の繰り返しを避けるときは that of(複数は those of).those who は「〜する人々」.", def: "代名詞:前に出た名詞の代わりに使う語." },
  T43: { name: "形が似た副詞", s: "hard(熱心に)/ hardly(ほとんど〜ない),late(遅く)/ lately(最近),near(近くに)/ nearly(ほぼ),high(高く)/ highly(非常に),close(近くに)/ closely(注意深く).most(最も)/ almost(ほとんど).", def: "副詞:動詞・形容詞・文などを修飾する語.-ly が付くと意味が変わる語がある." },
  T44: { name: "場所・関係の前置詞", s: "between は2つの間,among は3つ以上の中.across は横切って,through は中を通り抜けて,along は〜に沿って.beside は〜のそばに,besides は〜に加えて.by は手段(by bus)・期限,with は道具(with a pen).", def: "前置詞:名詞の前に置いて,場所・時・関係を表す語." },
  T45: { name: "-ever の付く関係詞", s: "whoever(〜する人はだれでも),whatever(〜するものは何でも),whichever(どちらでも),wherever(どこでも),whenever(いつでも),however + 形容詞・副詞(どんなに〜でも).先行詞を含むので,前に名詞を置かない.", def: "複合関係詞:関係詞に -ever が付き,「どんな〜でも」の意味を加えた語." },
  T46: { name: "形容詞と組む前置詞", s: "組み合わせで覚える.be interested in, be familiar with, be capable of, be dependent on, be satisfied with, be proud of, be similar to, be different from, be suitable for, be accustomed to(-ing).", def: "前置詞:名詞の前に置いて,関係を表す語.形容詞によって組む前置詞が決まっている." },
  T47: { name: "数詞 + 名詞で名詞を修飾する形", s: "「数詞 + 名詞」をハイフンでつないで名詞の前に置くと,単位の名詞は単数形になる(a three-day conference,a 10-minute break).名詞の後ろに置くなら複数形(a conference of three days).", def: "形容詞的用法:名詞以外の語が名詞の前に置かれて,名詞を修飾する使い方." },
  T48: { name: "動詞 + 副詞・前置詞のまとまり", s: "carry out(実行する),put off(延期する),look into(調べる),set up(設置する・準備する),take over(引き継ぐ),turn down(断る),fill out(記入する),call off(中止する),figure out(理解する),run out of(使い果たす).", def: "句動詞:動詞と副詞・前置詞が組んで,1つの動詞の働きをするまとまり." },
  T49: { name: "比較を使った決まった表現", s: "no later than(遅くとも〜までに),as many as / as much as(〜もの),the same as(〜と同じ),twice as 〜 as(〜の2倍),rather than(〜よりむしろ),prefer A to B(B より A を好む),more than(〜より多い).", def: "比較:2つ以上を比べる表現.数量を強調する決まった言い方がある." },
  T50: { name: "受動態と組む前置詞", s: "by 以外の前置詞と組む受動態.be known for(〜で知られる),be made of(材料)/ from(原料),be covered with,be located in,be involved in,be engaged in,be exposed to,be based on,be filled with.", def: "受動態:「〜される」を表す be + 過去分詞." },
  T52: { name: "仮定法の発展", s: "Were it not for 〜 / But for 〜(今〜がなければ),Had it not been for 〜(〜がなかったら),It is (high) time + 過去形,as if + 過去形,I wish + 過去完了(過去への後悔),lest + (should) 原形(〜しないように),otherwise(さもなければ).if 節と主節で時がずれる仮定もある.", def: "仮定法:事実と違うことを仮定する形.時制を1つ過去にずらす." },
  T53: { name: "比較の発展", s: "the + 比較級 〜, the + 比較級 …(〜するほど…).倍数 + as 〜 as.比較級を強めるのは much / far / even(very は不可).superior / inferior / prior は to をとる.not so much A as B(A というよりむしろ B).no less than(〜も).2つのうちでは the + 比較級.", def: "比較級:2つを比べる形.最上級:3つ以上の中で一番を表す形." },
  T54: { name: "主語と動詞の一致の難所", s: "either A or B / neither A nor B は近い B に一致.A along with B / A as well as B は A に一致.the majority of / half of / most of は of の後ろの名詞で決める.every A and every B,news,mathematics は単数扱い.There is / are は後ろの名詞に一致.関係代名詞の動詞は先行詞に一致.", def: "一致:主語の数(単数・複数)に動詞の形を合わせること." },
  T55: { name: "三人称単数の -s", s: "主語が3人称単数(he, she, it, 人の名前, 単数の名詞)で今のことなら,動詞に -s / -es を付ける.主語が I / you / 複数なら付けない.Does / does not の後ろは原形.", def: "3人称:話し手(I)と聞き手(you)以外.単数:1つ・1人." },
  T56: { name: "be 動詞の使い分け", s: "主語と時で決まる.I am,he・she・it・単数の名詞 is,you・複数 are.過去は was(I・単数)/ were(you・複数).形容詞(busy など)の前も be 動詞.everyone は単数扱い.", def: "be 動詞:「〜である・〜にいる」を表す am / is / are / was / were." },
  T57: { name: "a / an / the", s: "数えられる名詞の単数には a / an.母音の音で始まる語の前は an(an hour, an umbrella).つづりではなく音で決める(a university).1つしかないもの・最上級・序数(first など)・話し手と聞き手が分かっているものには the.", def: "冠詞:名詞の前に置く a / an / the." },
  T58: { name: "疑問詞の使い分け", s: "尋ねたい内容に合わせて選ぶ.What(何),Who(誰),Where(どこ),When(いつ),Why(なぜ),How(どうやって),How many(数),How much(量・値段),How long(期間・長さ),How often(頻度),Which(どちら).答えの文に合うものを選ぶ.", def: "疑問詞:何・誰・どこなどを尋ねる語.ふつう文の最初に置く." },
  T59: { name: "助動詞の後ろは原形", s: "can / will / must / should / may / might / could の後ろの動詞は原形.主語が単数でも -s は付けず,to も付けない.be 動詞の原形は be.", def: "助動詞:動詞の前に置いて,できる・〜だろう・〜しなければならない などの意味を足す語." },
  T60: { name: "and / but / or / so", s: "and は似た内容を足す(そして・〜と),but は反対の内容をつなぐ(しかし),or はどちらかを選ぶ(または),so は前が理由で後ろが結果(だから).命令文 + or は「さもないと」.", def: "接続詞:語と語,文と文をつなぐ語." },
  T61: { name: "不定詞・動名詞の完了形と受け身", s: "to have + 過去分詞 / having + 過去分詞 は,文の動詞より前のこと.to be + 過去分詞 / being + 過去分詞 は「〜される」こと.seem / appear / be said / be expected / be believed の後ろでよく使う.need + -ing は「〜される必要がある」.", def: "不定詞:to + 原形.動名詞:動詞に -ing を付けて名詞として使う形." },
  T62: { name: "強調構文", s: "It is(was)+ 強調したい語句 + that 〜 で「〜なのは…だ」.強調するのが人なら who も使える.It was not until 〜 that … は「〜して初めて…」.It と that を取り除くと元の文が成り立つ.", def: "強調構文:文の一部を It is と that ではさんで目立たせる形." },
  T63: { name: "助動詞 + have + 過去分詞", s: "must have + 過去分詞(〜したに違いない),can't have + 過去分詞(〜したはずがない),may / might have + 過去分詞(〜したかもしれない),should have + 過去分詞(〜すべきだったのに・〜したはずなのに),need not have + 過去分詞(〜する必要はなかったのに).", def: "助動詞 + have + 過去分詞:今から過去のことを推し量ったり,振り返ったりする形." }
};

window.GRAM = [
  { id: "g1", q: "The company offers a ____ training program for new employees.", c: ["comprehensive", "comprehend", "comprehensively", "comprehension"], a: 0, t: "T1", d: 300, why: "空所は冠詞 a と名詞 training program の間.名詞を修飾できるのは形容詞なので comprehensive.", ja: "その会社は新入社員向けに包括的な研修プログラムを提供している." },
  { id: "g2", q: "The report was ____ reviewed by the manager.", c: ["careful", "caring", "care", "carefully"], a: 3, t: "T2", d: 400, why: "was reviewed(受動態)の間にあり,過去分詞 reviewed を修飾するので副詞 carefully.", ja: "報告書は部長によって注意深く確認された." },
  { id: "g3", q: "We need your ____ before we place the order.", c: ["approval", "approve", "approved", "approving"], a: 0, t: "T3", d: 500, why: "所有格 your の後ろで,さらに後ろに名詞がない.名詞 approval が入る.", ja: "発注する前にあなたの承認が必要だ." },
  { id: "g4", q: "Ms. Kato ____ at the firm since 2019.", c: ["works", "worked", "has worked", "will work"], a: 2, t: "T4", d: 500, why: "since 2019 は「2019年から今まで」.継続を表す現在完了 has worked.", ja: "加藤さんは2019年からその会社で働いている." },
  { id: "g5", q: "Please call me when the package ____.", c: ["arrives", "will arrive", "arrived", "arriving"], a: 0, t: "T5", d: 600, why: "when 〜 は時を表す副詞節.未来のことでも現在形 arrives を使う.", ja: "荷物が届いたら電話してください." },
  { id: "g6", q: "The meeting ____ until next Monday.", c: ["postponed", "has postponed", "has been postponed", "is postponing"], a: 2, t: "T6", d: 600, why: "会議は「延期される」側なので受動態.完了形と組んで has been postponed.", ja: "会議は来週月曜日まで延期された." },
  { id: "g7", q: "We look forward to ____ you at the conference.", c: ["see", "be seen", "seen", "seeing"], a: 3, t: "T7", d: 700, why: "look forward to の to は前置詞.後ろは動名詞 seeing.", ja: "会議でお会いできるのを楽しみにしています." },
  { id: "g8", q: "The employee ____ won the sales award will give a speech.", c: ["who", "which", "whose", "whom"], a: 0, t: "T8", d: 600, why: "先行詞 employee は人で,空所の後ろに動詞 won があるので主格.who.", ja: "営業賞を受賞した社員がスピーチをする." },
  { id: "g9", q: "____ the heavy rain, the outdoor event was held as planned.", c: ["Although", "Despite", "Because", "Even"], a: 1, t: "T9", d: 700, why: "後ろは the heavy rain という名詞句で,動詞がない.前置詞 Despite.", ja: "大雨にもかかわらず,屋外イベントは予定通り開催された." },
  { id: "g10", q: "Each of the applicants ____ required to submit a résumé.", c: ["are", "were", "have", "is"], a: 3, t: "T10", d: 800, why: "主語は Each(単数扱い).applicants につられず is.", ja: "応募者はそれぞれ履歴書を提出する必要がある." },
  { id: "g11", q: "If the shipment ____ late, we will contact you.", c: ["is", "will be", "was", "being"], a: 0, t: "T5", d: 500, why: "if 〜 は条件の副詞節.未来のことでも現在形 is.", ja: "出荷が遅れる場合はご連絡します." },
  { id: "g12", q: "The new policy, ____ was announced last week, takes effect in April.", c: ["which", "who", "what", "that"], a: 0, t: "T8", d: 800, why: "先行詞 policy は物.カンマの後なので that は使えず which.", ja: "先週発表された新方針は4月に施行される." },
  { id: "g13", q: "All visitors must wear a badge ____ they are in the building.", c: ["during", "despite", "since", "while"], a: 3, t: "T9", d: 600, why: "後ろは they are という節(主語 + 動詞).接続詞 while が入る.during は前置詞なので節を取れない.", ja: "来訪者は建物内にいる間,バッジを着用しなければならない." },
  { id: "g14", q: "The ____ of the new software took longer than expected.", c: ["install", "installation", "installed", "installs"], a: 1, t: "T3", d: 400, why: "冠詞 The の後ろで,直後は前置詞 of.名詞 installation が入る.", ja: "新しいソフトウェアの導入は予想より時間がかかった." },

  // 比較
  { id: "g15", q: "The new laptop is much ____ than the previous model.", c: ["light", "lighter", "lightest", "lightly"], a: 1, t: "T11", d: 400, why: "後ろに than があるので比較級 lighter.much は比較級を強める語.", ja: "新しいノートパソコンは前のモデルよりずっと軽い." },
  { id: "g16", q: "This year's profits were not as ____ as we had hoped.", c: ["higher", "highest", "high", "highly"], a: 2, t: "T11", d: 600, why: "as ___ as の間は原級.さらに were の補語なので副詞 highly ではなく形容詞 high.", ja: "今年の利益は期待したほど高くなかった." },
  { id: "g17", q: "Ms. Lopez is the ____ experienced designer on our team.", c: ["more", "much", "very", "most"], a: 3, t: "T11", d: 700, why: "the があり,on our team(チームの中で)という範囲もある.最上級 the most experienced.", ja: "ロペスさんは私たちのチームで最も経験豊富なデザイナーだ." },

  // 分詞
  { id: "g18", q: "The results of the customer survey were ____.", c: ["disappointing", "disappointed", "disappoint", "disappointment"], a: 0, t: "T12", d: 700, why: "主語 results は人を「がっかりさせる」側.現在分詞 disappointing.人が主語なら disappointed になる.", ja: "顧客調査の結果は残念なものだった." },
  { id: "g19", q: "Please review the ____ document before the meeting.", c: ["attach", "attached", "attaching", "attachment"], a: 1, t: "T12", d: 600, why: "document は「添付される」側なので過去分詞 attached.「冠詞 + ___ + 名詞」なので形容詞の働きをする語が入る(T1).", ja: "会議の前に添付の資料を確認してください." },
  { id: "g20", q: "The client was very ____ with the quality of our work.", c: ["satisfying", "satisfied", "satisfaction", "satisfy"], a: 1, t: "T12", d: 600, why: "client(人)は「満足させられる」側なので過去分詞 satisfied.be satisfied with 〜 で「〜に満足している」.", ja: "顧客は私たちの仕事の質にとても満足していた." },

  // 代名詞
  { id: "g21", q: "Mr. Park sent the revised contract to ____ client yesterday.", c: ["he", "his", "him", "himself"], a: 1, t: "T13", d: 400, why: "後ろに名詞 client があるので所有格 his.", ja: "パークさんは昨日,修正した契約書を自分の顧客に送った." },
  { id: "g22", q: "The volunteers prepared all the food for the festival by ____.", c: ["they", "their", "them", "themselves"], a: 3, t: "T13", d: 700, why: "by ___ で「自分たちだけで」.主語 volunteers と同じ人を指すので再帰代名詞 themselves.", ja: "ボランティアたちは祭りの料理をすべて自分たちで用意した." },
  { id: "g23", q: "If you have any questions about the schedule, please contact ____ directly.", c: ["I", "my", "me", "mine"], a: 2, t: "T13", d: 400, why: "動詞 contact の目的語なので目的格 me.", ja: "日程について質問があれば,直接私に連絡してください." },

  // 相関接続詞
  { id: "g24", q: "Applicants must have ____ a degree in marketing and three years of experience.", c: ["either", "not only", "neither", "both"], a: 3, t: "T14", d: 600, why: "後ろの and と組むのは both.both A and B で「A と B の両方」.", ja: "応募者はマーケティングの学位と3年の経験の両方が必要だ." },
  { id: "g25", q: "You can pay ____ by credit card or by bank transfer.", c: ["both", "neither", "either", "whether"], a: 2, t: "T14", d: 600, why: "後ろの or と組むのは either.either A or B で「A か B のどちらか」.", ja: "クレジットカードか銀行振込のどちらかで支払える." },
  { id: "g26", q: "The workshop was ____ informative but also enjoyable.", c: ["not only", "both", "either", "as well"], a: 0, t: "T14", d: 800, why: "後ろの but also と組むのは not only.not only A but also B で「A だけでなく B も」.", ja: "その研修会はためになるだけでなく楽しくもあった." },

  // to do / -ing
  { id: "g27", q: "The company has decided ____ a new branch in Osaka.", c: ["open", "to open", "opening", "opened"], a: 1, t: "T15", d: 500, why: "decide は目的語に to do をとる.decided to open.", ja: "その会社は大阪に新しい支店を開くことに決めた." },
  { id: "g28", q: "Please avoid ____ personal calls during working hours.", c: ["make", "to make", "made", "making"], a: 3, t: "T15", d: 700, why: "avoid は目的語に -ing をとる.avoid making.", ja: "勤務時間中は私用の電話を避けてください." },
  { id: "g29", q: "We are considering ____ our office to a larger building.", c: ["moving", "to move", "move", "moved"], a: 0, t: "T15", d: 800, why: "consider は目的語に -ing をとる.considering moving.", ja: "私たちは事務所をもっと大きな建物に移すことを検討している." },

  // 要求・提案の that 節
  { id: "g30", q: "The manager requested that every employee ____ the safety training.", c: ["attend", "attends", "attended", "attending"], a: 0, t: "T16", d: 1000, why: "request に続く that 節なので,主語 every employee が単数でも動詞は原形 attend.", ja: "部長は全社員が安全研修に出席するよう求めた." },
  { id: "g31", q: "It is recommended that guests ____ their tickets in advance.", c: ["purchased", "purchasing", "purchases", "purchase"], a: 3, t: "T16", d: 1100, why: "It is recommended that ... も提案の that 節.動詞は原形 purchase.", ja: "お客様は前もってチケットを購入することをおすすめします." },

  // 数量
  { id: "g32", q: "There is not ____ time left before the deadline.", c: ["many", "much", "few", "a number of"], a: 1, t: "T17", d: 500, why: "time は数えられない名詞なので much.many / few / a number of は数えられる名詞の複数形と使う.", ja: "締め切りまであまり時間が残っていない." },
  { id: "g33", q: "Every ____ on the site must wear a safety helmet.", c: ["workers", "worked", "working", "worker"], a: 3, t: "T17", d: 500, why: "every の後ろは単数形.Every worker.", ja: "現場の作業員は全員安全ヘルメットを着用しなければならない." },
  { id: "g34", q: "A number of customers ____ complained about the late delivery.", c: ["has", "is", "have", "was"], a: 2, t: "T17", d: 900, why: "a number of 〜 は「多くの〜」で複数扱い.have complained.the number of なら単数扱いになる.", ja: "多くの客が配達の遅れについて苦情を言っている." },

  // by / until
  { id: "g35", q: "Please submit your expense report ____ Friday.", c: ["until", "by", "since", "during"], a: 1, t: "T18", d: 600, why: "提出は1回済ませる行為で,金曜日が期限.by Friday.until は「ずっと続く」ことに使う.", ja: "金曜日までに経費報告書を提出してください." },
  { id: "g36", q: "The store will be closed for renovations ____ the end of the month.", c: ["by", "until", "within", "since"], a: 1, t: "T18", d: 700, why: "閉店している状態が月末までずっと続く.継続なので until.", ja: "その店は改装のため月末まで休業する." },

  // whose / what
  { id: "g37", q: "We hired a designer ____ work has won several international awards.", c: ["who", "whose", "which", "what"], a: 1, t: "T19", d: 800, why: "後ろは冠詞のない名詞 work + 動詞 has won.「デザイナーの作品」と持ち物を表すので whose.", ja: "私たちは,作品が国際的な賞をいくつも受賞しているデザイナーを雇った." },
  { id: "g38", q: "____ our customers want most is faster delivery.", c: ["That", "Which", "It", "What"], a: 3, t: "T19", d: 900, why: "空所の前に先行詞がなく,「客が最も望んでいること」という名詞のまとまりをつくる.What.", ja: "顧客が最も望んでいるのは,より速い配送だ." },

  // 補語
  { id: "g39", q: "The current prices will remain ____ until the end of June.", c: ["effect", "effectively", "effective", "effectiveness"], a: 2, t: "T20", d: 800, why: "remain の後ろは補語の位置なので形容詞 effective(有効な).", ja: "現在の価格は6月末まで有効だ." },
  { id: "g40", q: "Customer feedback on the new menu has been very ____.", c: ["positively", "positive", "positivity", "positiveness"], a: 1, t: "T20", d: 600, why: "has been の後ろは補語の位置.very に修飾されて補語になるのは形容詞 positive.", ja: "新しいメニューへの客の反応はとても好意的だ." },

  // 既存の定理の追加問題
  { id: "g41", q: "Sales have increased ____ since the advertising campaign started.", c: ["significant", "significance", "significantly", "signify"], a: 2, t: "T2", d: 500, why: "have increased という動詞を修飾する位置なので副詞 significantly.", ja: "広告キャンペーンが始まってから,売上は大幅に増えた." },
  { id: "g42", q: "Mr. Ito gave a ____ presentation on the new strategy.", c: ["persuade", "persuasion", "persuasively", "persuasive"], a: 3, t: "T1", d: 500, why: "冠詞 a と名詞 presentation の間なので形容詞 persuasive.", ja: "伊藤さんは新戦略について説得力のあるプレゼンをした." },
  { id: "g43", q: "Prices of raw materials ____ steadily over the past three years.", c: ["rose", "have risen", "rise", "will rise"], a: 1, t: "T4", d: 700, why: "over the past three years(この3年間)は過去から今までの期間.現在完了 have risen.主語の中心は Prices で複数.", ja: "原材料の価格はこの3年間着実に上がってきた." },
  { id: "g44", q: "We will begin the meeting as soon as Mr. Lee ____.", c: ["arrives", "will arrive", "arrived", "arrive"], a: 0, t: "T5", d: 600, why: "as soon as 〜 は時を表す副詞節.未来のことでも現在形.主語 Mr. Lee は単数なので arrives.", ja: "リーさんが着いたらすぐに会議を始めます." },
  { id: "g45", q: "The list of new participants ____ been sent to all department heads.", c: ["have", "are", "has", "were"], a: 2, t: "T10", d: 900, why: "主語の中心は The list(単数).of new participants につられず has.", ja: "新しい参加者の名簿は全部門長に送られた." },

  // 倒置・仮定法
  { id: "g46", q: "____ you have any questions, please do not hesitate to contact us.", c: ["Should", "Would", "Could", "Had"], a: 0, t: "T21", d: 1200, why: "If you should have ... の if を省いた倒置.Should + 主語 + 原形で「万一〜なら」.ビジネスメールの決まり文句.", ja: "ご質問がありましたら,お気軽にお問い合わせください." },
  { id: "g47", q: "____ we known about the traffic, we would have left earlier.", c: ["If", "Have", "Had", "Were"], a: 2, t: "T21", d: 1400, why: "後半が would have left なので過去の事実と違う仮定.If we had known の if を省いた倒置で Had we known.If なら If we had known となり known だけでは足りない.", ja: "渋滞のことを知っていたら,もっと早く出発していただろう." },
  { id: "g48", q: "If the store had opened on time, we ____ the sale.", c: ["will not miss", "have not missed", "did not miss", "would not have missed"], a: 3, t: "T22", d: 1200, why: "if 節が had opened(過去完了)なので,過去の事実と違う仮定.主節は would have + 過去分詞.", ja: "店が時間どおりに開いていたら,セールを逃さなかっただろう." },
  { id: "g49", q: "If I ____ more time, I would join the workshop.", c: ["have", "will have", "had", "having"], a: 2, t: "T22", d: 900, why: "主節が would join なので,今の事実と違う仮定.if 節は過去形 had.", ja: "もっと時間があれば,研修会に参加するのだが." },
  // 分詞構文
  { id: "g50", q: "____ in 1990, the company now has offices in ten countries.", c: ["Founding", "Founds", "To found", "Founded"], a: 3, t: "T23", d: 1100, why: "意味上の主語は the company.会社は「設立される」側なので過去分詞 Founded.", ja: "1990年に設立されたその会社は,今では10か国に事務所がある." },
  { id: "g51", q: "____ the report, Ms. Gomez found several errors.", c: ["Reviewed", "Reviews", "Review", "Reviewing"], a: 3, t: "T23", d: 1000, why: "意味上の主語は Ms. Gomez.ゴメスさんが報告書を「確認する」側なので -ing.後ろに目的語 the report があることも手がかり.", ja: "報告書を確認していて,ゴメスさんはいくつか誤りを見つけた." },
  { id: "g52", q: "____ carefully, the instructions are easy to follow.", c: ["Reading", "Read", "Reads", "To reading"], a: 1, t: "T23", d: 1200, why: "意味上の主語は the instructions.説明書は「読まれる」側なので過去分詞 Read.(If they are read carefully の短縮)", ja: "注意して読めば,その説明書は分かりやすい." },
  // so / such
  { id: "g53", q: "Demand was ____ high that the store ran out of stock.", c: ["such", "very", "too", "so"], a: 3, t: "T24", d: 700, why: "後ろが形容詞 high だけで名詞がない.so + 形容詞 + that.too や very は that と組まない.", ja: "需要がとても高かったので,店は在庫切れになった." },
  { id: "g54", q: "It was ____ a popular event that tickets sold out in an hour.", c: ["so", "too", "such", "very"], a: 2, t: "T24", d: 900, why: "後ろが a popular event(冠詞 + 形容詞 + 名詞).such + a + 形容詞 + 名詞 + that.", ja: "とても人気のある催しだったので,チケットは1時間で売り切れた." },
  // 接続副詞
  { id: "g55", q: "The product is expensive. ____, many customers buy it for its quality.", c: ["Although", "Because", "Despite", "However"], a: 3, t: "T25", d: 800, why: "ピリオドの後で,カンマが続く.前の文と逆の内容をつなぐ副詞 However.Although は節を2つ必要とし,Despite は名詞が必要.", ja: "その製品は高価だ.しかし,多くの客が品質を理由に買っている." },
  { id: "g56", q: "Sales fell last quarter; ____, the company plans to hire more staff.", c: ["nevertheless", "although", "despite", "even though"], a: 0, t: "T25", d: 1100, why: "セミコロンの後,カンマの前に置けるのは接続副詞.nevertheless(それにもかかわらず).although / even though は接続詞,despite は前置詞.", ja: "前四半期は売上が落ちた.それでも会社は人員を増やす予定だ." },
  { id: "g57", q: "The shipment was delayed, ____ we offered the customer a discount.", c: ["therefore", "so", "however", "consequently"], a: 1, t: "T25", d: 1000, why: "カンマだけで2つの節をつないでいる.節をつなげるのは接続詞 so.therefore と consequently は意味は合うが副詞なので,カンマだけではつなげない.", ja: "出荷が遅れたので,客に割引を提供した." },
  // 条件
  { id: "g58", q: "You will not receive a refund ____ you return the item within 30 days.", c: ["if", "because", "so that", "unless"], a: 3, t: "T26", d: 800, why: "「30日以内に返品しない限り返金されない」.unless = if not.if では「返品すると返金されない」と意味が逆になる.", ja: "30日以内に返品しない限り,返金は受けられません." },
  { id: "g59", q: "You may use the meeting room ____ you clean it afterward.", c: ["as long as", "as well as", "as soon as", "as far as"], a: 0, t: "T26", d: 900, why: "「後で掃除するという条件で使ってよい」.条件を表す as long as.as well as は「〜と同様に」で節をつながない.", ja: "後で掃除するなら,会議室を使ってかまいません." },
  { id: "g60", q: "Please bring an umbrella ____ it rains during the tour.", c: ["in case", "unless", "although", "so that"], a: 0, t: "T26", d: 900, why: "「雨が降る場合に備えて傘を持ってくる」.in case.", ja: "ツアー中に雨が降った場合に備えて,傘をお持ちください." },
  // 前置詞
  { id: "g61", q: "Mr. Kim is responsible ____ training new staff.", c: ["to", "with", "of", "for"], a: 3, t: "T27", d: 600, why: "be responsible for 〜 で「〜を担当している・〜に責任がある」.", ja: "キムさんは新人の研修を担当している." },
  { id: "g62", q: "All employees must comply ____ the new security policy.", c: ["to", "for", "with", "on"], a: 2, t: "T27", d: 800, why: "comply with 〜 で「〜に従う」.", ja: "全社員が新しいセキュリティ方針に従わなければならない." },
  { id: "g63", q: "Ms. Rossi is in charge ____ the marketing department.", c: ["for", "to", "of", "at"], a: 2, t: "T27", d: 700, why: "in charge of 〜 で「〜を担当・統括している」.", ja: "ロッシさんがマーケティング部を統括している." },
  { id: "g64", q: "Guests should be aware ____ the change in check-out time.", c: ["of", "for", "to", "with"], a: 0, t: "T27", d: 700, why: "be aware of 〜 で「〜に気づいている・〜を承知している」.", ja: "宿泊客はチェックアウト時刻の変更を承知しておく必要がある." },
  // 完了形
  { id: "g65", q: "By the end of next year, we ____ over 50 stores nationwide.", c: ["open", "opened", "will have opened", "have opened"], a: 2, t: "T28", d: 1100, why: "By the end of next year(未来の時点)までに完了していること.未来完了 will have opened.", ja: "来年末までに,全国で50店以上を開店しているだろう." },
  { id: "g66", q: "When I arrived at the station, the train ____ already left.", c: ["has", "was", "have", "had"], a: 3, t: "T28", d: 900, why: "駅に着いた(過去)時点より前に電車は出ていた.過去完了 had left.", ja: "駅に着いたとき,電車はもう出てしまっていた." },
  { id: "g67", q: "The client ____ the contract before the price was changed.", c: ["signs", "had signed", "has signed", "will sign"], a: 1, t: "T28", d: 1000, why: "価格が変わった(過去)より前に署名していた.過去完了 had signed.現在完了は過去の時点を表す語と一緒に使えない.", ja: "価格が変わる前に,顧客は契約に署名していた." },
  // 使役
  { id: "g68", q: "The manager had her assistant ____ the documents.", c: ["copy", "copied", "copying", "to copy"], a: 0, t: "T29", d: 1000, why: "have + 人 + 動詞の原形で「人に〜させる」.助手が「コピーする」側なので原形 copy.", ja: "部長は助手に書類をコピーさせた." },
  { id: "g69", q: "I need to have my car ____ before the trip.", c: ["repair", "repairing", "repaired", "to repair"], a: 2, t: "T29", d: 1000, why: "have + 物 + 過去分詞で「(物を)〜してもらう」.車は「修理される」側なので repaired.", ja: "旅行の前に車を修理してもらう必要がある." },
  { id: "g70", q: "Please let us ____ if you need any help.", c: ["know", "to know", "knowing", "known"], a: 0, t: "T29", d: 600, why: "let + 人 + 動詞の原形.let us know で「知らせてください」.", ja: "お手伝いが必要ならお知らせください." },
  // 関係副詞
  { id: "g71", q: "This is the hotel ____ the conference will be held.", c: ["which", "where", "what", "who"], a: 1, t: "T30", d: 900, why: "後ろの the conference will be held は欠けのない文.場所の先行詞 hotel を説明する関係副詞 where.which なら in which が必要.", ja: "ここが会議の開かれるホテルだ." },
  { id: "g72", q: "We visited the factory ____ produces our main components.", c: ["where", "what", "when", "which"], a: 3, t: "T30", d: 1000, why: "後ろの produces ... には主語がない(欠けがある).主語になれる関係代名詞 which.先行詞が場所でも where にはならない.", ja: "当社の主要部品を作っている工場を訪問した." },

  // 既存の定理の追加問題
  { id: "g73", q: "Please send me a ____ summary of the meeting.", c: ["brief", "briefly", "briefness", "briefed"], a: 0, t: "T1", d: 400, why: "冠詞 a と名詞 summary の間なので形容詞 brief(短い・簡潔な).", ja: "会議の簡単な要約を送ってください." },
  { id: "g74", q: "The store is ____ located near the station.", c: ["convenient", "conveniently", "convenience", "more convenient"], a: 1, t: "T2", d: 500, why: "is located(受動態)の間で過去分詞 located を修飾するので副詞 conveniently.", ja: "その店は駅の近くの便利な場所にある." },
  { id: "g75", q: "The company received many ____ for the position.", c: ["apply", "applied", "applications", "applicable"], a: 2, t: "T3", d: 400, why: "many の後ろで,後ろに名詞がない.名詞の複数形 applications(応募).", ja: "その会社はその職に多くの応募を受けた." },
  { id: "g76", q: "Thank you for your ____ to this matter.", c: ["attend", "attention", "attentive", "attentively"], a: 1, t: "T3", d: 500, why: "所有格 your の後ろで,後ろは前置詞 to.名詞 attention.", ja: "本件にご配慮いただきありがとうございます." },
  { id: "g77", q: "The new software ____ by most employees last month.", c: ["installed", "was installed", "has installed", "installing"], a: 1, t: "T6", d: 500, why: "ソフトは「インストールされる」側で,by 〜 もある.last month なので過去の受動態 was installed.", ja: "新しいソフトは先月ほとんどの社員がインストールした." },
  { id: "g78", q: "Your order ____ as soon as payment is confirmed.", c: ["will process", "will be processed", "processes", "processing"], a: 1, t: "T6", d: 700, why: "注文は「処理される」側なので受動態.主節は未来のことなので will be processed(as soon as 節の中だけ現在形).", ja: "お支払いが確認されしだい,ご注文を処理します." },
  { id: "g79", q: "Ms. Tanaka is committed to ____ the best service to customers.", c: ["provide", "provides", "provided", "providing"], a: 3, t: "T7", d: 900, why: "be committed to の to は前置詞.後ろは動名詞 providing.", ja: "田中さんは顧客に最高のサービスを提供することに力を尽くしている." },
  { id: "g80", q: "Applicants ____ have experience in sales are preferred.", c: ["who", "which", "whose", "whom"], a: 0, t: "T8", d: 600, why: "先行詞 Applicants は人で,後ろに動詞 have があるので主格 who.", ja: "営業経験のある応募者を優遇します." },
  { id: "g81", q: "The flight was canceled ____ the bad weather.", c: ["because", "although", "because of", "since"], a: 2, t: "T9", d: 500, why: "後ろは the bad weather(名詞句).前置詞 because of.because と although は接続詞,since は名詞の前では「〜以来」.", ja: "悪天候のため,その便は欠航になった." },
  { id: "g82", q: "____ she was new to the job, she handled the problem well.", c: ["Despite", "Although", "In spite of", "Due to"], a: 1, t: "T9", d: 700, why: "後ろは she was new という節.接続詞 Although.Despite / In spite of / Due to は前置詞.", ja: "仕事に就いたばかりだったが,彼女はその問題をうまく処理した." },
  { id: "g83", q: "The number of visitors to the museum ____ increased this year.", c: ["have", "has", "are", "were"], a: 1, t: "T17", d: 900, why: "the number of 〜(〜の数)は単数扱い.has increased.a number of(多くの)なら複数扱い.", ja: "今年,美術館の来館者数が増えた." },
  { id: "g84", q: "This is the ____ hotel in the city.", c: ["larger", "largest", "more large", "most large"], a: 1, t: "T11", d: 500, why: "the があり,in the city(市内で)という範囲がある.最上級 largest.large の最上級は most large ではなく largest.", ja: "ここは市内で最も大きなホテルだ." },
  { id: "g85", q: "There are several ____ positions in our sales department.", c: ["remain", "remaining", "remained", "remainder"], a: 1, t: "T12", d: 800, why: "positions は「残っている」側(自分で残る)なので現在分詞 remaining.remain は自動詞で「残される」という受け身にならない.", ja: "当社の営業部にはまだいくつか空きのある職がある." },
  { id: "g86", q: "Ms. Diaz and ____ will attend the meeting.", c: ["I", "me", "my", "mine"], a: 0, t: "T13", d: 600, why: "Ms. Diaz and ___ が主語なので主格 I.", ja: "ディアスさんと私が会議に出席します." },
  { id: "g87", q: "____ the manager nor her assistant was available.", c: ["Either", "Neither", "Both", "Not only"], a: 1, t: "T14", d: 700, why: "後ろの nor と組むのは neither.neither A nor B で「A も B も〜ない」.", ja: "部長も助手も手が空いていなかった." },
  { id: "g88", q: "The team finished ____ the report on time.", c: ["write", "to write", "writing", "wrote"], a: 2, t: "T15", d: 700, why: "finish は目的語に -ing をとる.finished writing.", ja: "チームは期限どおりに報告書を書き終えた." },
  { id: "g89", q: "The client insisted that the meeting ____ held in person.", c: ["is", "be", "was", "being"], a: 1, t: "T16", d: 1300, why: "insist に続く that 節(要求)では動詞は原形.受動態なので be held.", ja: "顧客は,会議を対面で開くよう強く求めた." },
  { id: "g90", q: "This special offer is valid ____ March 31.", c: ["by", "until", "within", "since"], a: 1, t: "T18", d: 800, why: "有効な状態が3月31日までずっと続く.継続なので until.", ja: "この特別価格は3月31日まで有効だ." },

  // ---- 各定理が10問になるように追加した問題(g91〜) ----
  // T1
  { id: "g91", q: "The hotel is known for its ____ service.", c: ["exceptional", "exception", "exceptionally", "except"], a: 0, t: "T1", d: 500, why: "所有格 its と名詞 service の間なので形容詞 exceptional(並外れた).", ja: "そのホテルは並外れたサービスで知られている." },
  { id: "g92", q: "We are looking for a ____ candidate to fill the position.", c: ["qualify", "qualification", "qualified", "qualifies"], a: 2, t: "T1", d: 600, why: "冠詞 a と名詞 candidate の間なので形容詞.qualified は「資格のある」という形容詞として使う.", ja: "その職を埋める,資格のある候補者を探している." },
  { id: "g93", q: "The new manager made several ____ changes to the schedule.", c: ["signify", "significantly", "significance", "significant"], a: 3, t: "T1", d: 600, why: "several と名詞 changes の間で,名詞を修飾する形容詞 significant(大きな・重要な).", ja: "新しい部長は予定にいくつか大きな変更を加えた." },
  { id: "g94", q: "Customers appreciate our ____ prices.", c: ["affordable", "afford", "affordably", "affordability"], a: 0, t: "T1", d: 500, why: "所有格 our と名詞 prices の間なので形容詞.-able で終わる語は形容詞.", ja: "客は当店の手ごろな価格を評価している." },
  { id: "g95", q: "The report contains ____ information about our competitors.", c: ["value", "valuably", "valuing", "valuable"], a: 3, t: "T1", d: 400, why: "名詞 information を修飾する形容詞 valuable(価値のある).冠詞がなくても,名詞の直前は形容詞の位置.", ja: "その報告書には競合他社についての貴重な情報が含まれている." },
  { id: "g96", q: "Ms. Hall is a highly ____ lawyer with twenty years of experience.", c: ["succeed", "success", "successfully", "successful"], a: 3, t: "T1", d: 800, why: "a + 副詞 highly + ___ + 名詞 lawyer.副詞 highly が修飾し,名詞 lawyer を修飾するのは形容詞 successful.副詞が間に入っても「冠詞 + ___ + 名詞」の形は同じ.", ja: "ホールさんは20年の経験をもつ,大きな成功を収めた弁護士だ." },
  { id: "g97", q: "The committee reached a ____ decision after two hours of discussion.", c: ["unanimity", "unanimous", "unanimously", "unanimities"], a: 1, t: "T1", d: 1300, why: "冠詞 a と名詞 decision の間なので形容詞.-ous は形容詞の語尾(unanimous:全員一致の).知らない単語でも語尾から品詞を判定できる.", ja: "委員会は2時間の議論の末,全員一致の決定に達した." },

  // T2
  { id: "g98", q: "Please read the instructions ____ before using the machine.", c: ["carefully", "careful", "care", "caring"], a: 0, t: "T2", d: 400, why: "動詞 read を修飾するので副詞 carefully.「動詞 + 目的語 + ___」の位置.", ja: "機械を使う前に説明書を注意深く読んでください." },
  { id: "g99", q: "The two companies have ____ agreed to work together.", c: ["final", "finally", "finals", "finalize"], a: 1, t: "T2", d: 500, why: "have と過去分詞 agreed の間は副詞の位置.finally(ついに).", ja: "両社はついに協力することで合意した." },
  { id: "g100", q: "Our staff will respond ____ to all customer inquiries.", c: ["prompt", "promptness", "prompted", "promptly"], a: 3, t: "T2", d: 700, why: "動詞 respond を修飾する副詞 promptly(迅速に).respond は自動詞なので,後ろに名詞は置けない.", ja: "当社のスタッフはすべての問い合わせに迅速に対応する." },
  { id: "g101", q: "The price of fuel has risen ____ over the last six months.", c: ["sharply", "sharp", "sharpen", "sharpness"], a: 0, t: "T2", d: 700, why: "動詞 has risen を修飾する副詞 sharply(急激に).rise は自動詞なので目的語(名詞)はとらない.", ja: "燃料の価格はこの6か月で急激に上がった." },
  { id: "g102", q: "The software is ____ updated to protect users' data.", c: ["regular", "regulate", "regularity", "regularly"], a: 3, t: "T2", d: 600, why: "be 動詞と過去分詞 updated の間は副詞の位置.regularly(定期的に).", ja: "そのソフトは利用者のデータを守るため,定期的に更新される." },
  { id: "g103", q: "Ms. Abe speaks English ____ enough to negotiate with overseas clients.", c: ["fluent", "fluency", "fluently", "more fluent"], a: 2, t: "T2", d: 900, why: "動詞 speaks を修飾する副詞 fluently.「副詞 + enough to do」で「〜できるほど…に」.English は目的語なので,その後ろは名詞ではなく副詞.", ja: "阿部さんは海外の顧客と交渉できるほど流ちょうに英語を話す." },
  { id: "g104", q: "The figures in the report were ____ accurate, with only one minor error.", c: ["largely", "large", "larger", "enlarge"], a: 0, t: "T2", d: 1000, why: "形容詞 accurate を修飾するのは副詞.largely(大部分は).副詞は動詞だけでなく形容詞も修飾する.", ja: "報告書の数字はおおむね正確で,小さな誤りが1つあるだけだった." },

  // T3
  { id: "g105", q: "The manager praised the team for its ____.", c: ["perform", "performed", "performance", "performing"], a: 2, t: "T3", d: 500, why: "所有格 its の後ろで,文が終わっているので名詞 performance(成績・働きぶり).", ja: "部長はチームの働きぶりをほめた." },
  { id: "g106", q: "Please confirm your ____ at the meeting by Friday.", c: ["attend", "attentive", "attended", "attendance"], a: 3, t: "T3", d: 600, why: "所有格 your の直後で,後ろに名詞が続かないので名詞 attendance(出席).", ja: "金曜日までに会議への出席を確認してください." },
  { id: "g107", q: "The company is seeking an experienced ____ to manage its finances.", c: ["account", "accounting", "accountant", "accountable"], a: 2, t: "T3", d: 1000, why: "an + 形容詞 experienced + ___ なので名詞.財務を管理するのは「人」なので accountant(会計士).名詞が複数ある選択肢では,人か物かを意味で選ぶ.", ja: "その会社は財務を管理する,経験豊富な会計士を探している." },
  { id: "g108", q: "There has been a sharp ____ in the number of tourists.", c: ["decline", "declined", "declining", "declines"], a: 0, t: "T3", d: 700, why: "a + 形容詞 sharp + ___ で名詞が入る.冠詞 a があるので単数形 decline(減少).", ja: "観光客の数が急激に減少している." },
  { id: "g109", q: "All employees must follow the safety ____ at all times.", c: ["regulations", "regulate", "regulatory", "regulated"], a: 0, t: "T3", d: 700, why: "the safety ___ で1つの名詞句(安全規則)を作る.動詞 follow の目的語の中心になる名詞 regulations.", ja: "全従業員は常に安全規則に従わなければならない." },
  { id: "g110", q: "Mr. Sato is seeking ____ on how to reduce costs.", c: ["advise", "advisable", "advisory", "advice"], a: 3, t: "T3", d: 900, why: "他動詞 seek の目的語なので名詞 advice(助言).advise(つづりが s)は動詞.", ja: "佐藤さんは経費を減らす方法について助言を求めている." },

  // T4
  { id: "g111", q: "The company ____ its products online since last April.", c: ["sells", "sold", "has sold", "is selling"], a: 2, t: "T4", d: 500, why: "since last April(昨年4月から)があるので現在完了 has sold.", ja: "その会社は昨年の4月から製品をオンラインで販売している." },
  { id: "g112", q: "Mr. Brown ____ as our accountant for the past ten years.", c: ["serves", "will serve", "is serving", "has served"], a: 3, t: "T4", d: 600, why: "for the past ten years(過去10年間)は現在まで続く期間.現在完了 has served.", ja: "ブラウンさんは過去10年間,当社の会計士を務めてきた." },
  { id: "g113", q: "We ____ any complaints since we changed the packaging.", c: ["did not receive", "do not receive", "have not received", "had not received"], a: 2, t: "T4", d: 800, why: "since + 過去の節(包装を変えて以来)があるので現在完了.否定は have not received.", ja: "包装を変えて以来,苦情は1件も受けていない." },
  { id: "g114", q: "Over the last decade, the city ____ three new subway lines.", c: ["has built", "builds", "is building", "will build"], a: 0, t: "T4", d: 700, why: "Over the last decade(この10年間で)は現在までの期間.現在完了 has built.", ja: "この10年で,市は地下鉄の新路線を3本建設した." },
  { id: "g115", q: "Ms. Ono ____ in Paris for five years, but she now works in Tokyo.", c: ["works", "has worked", "worked", "is working"], a: 2, t: "T4", d: 1200, why: "but she now works in Tokyo から,パリで働いたのはもう終わったことだと分かる.今につながらない期間は過去形 worked.for + 期間だけでは現在完了と決まらない(the past が付くか,今も続いているかを確かめる).", ja: "小野さんは5年間パリで働いたが,今は東京で働いている." },
  { id: "g116", q: "The number of online orders ____ steadily since the Web site was redesigned.", c: ["has grown", "grows", "grew", "will grow"], a: 0, t: "T4", d: 700, why: "since + 過去の節(サイトが作り直されて以来)があるので現在完了 has grown.", ja: "サイトが作り直されて以来,オンライン注文の数は着実に増えている." },
  { id: "g117", q: "Since joining the company in 2015, Mr. Diaz ____ three sales awards.", c: ["wins", "will win", "was winning", "has won"], a: 3, t: "T4", d: 900, why: "Since joining ... in 2015(2015年に入社して以来)も「since + 過去の時点」と同じ.現在完了 has won.", ja: "2015年の入社以来,ディアスさんは営業賞を3回受賞している." },
  { id: "g118", q: "So far this year, we ____ more than 200 new clients.", c: ["gain", "are gaining", "had gained", "have gained"], a: 3, t: "T4", d: 1000, why: "so far(これまでのところ)は「今まで」の期間を表すので現在完了 have gained.since / for the past と同じ働きをする目印.", ja: "今年はこれまでに200社を超える新しい顧客を獲得した." },

  // T5
  { id: "g119", q: "We will send you the invoice after the work ____ complete.", c: ["will be", "is", "was", "be"], a: 1, t: "T5", d: 500, why: "after 以下は時の副詞節.未来のことでも現在形 is.", ja: "作業が完了したら請求書をお送りします." },
  { id: "g120", q: "Before you ____ the building, please turn off all the lights.", c: ["leave", "will leave", "left", "are left"], a: 0, t: "T5", d: 400, why: "before 以下は時の副詞節なので,これからのことでも現在形 leave.", ja: "建物を出る前に,すべての照明を消してください." },
  { id: "g121", q: "The manager will make a decision once she ____ all the proposals.", c: ["has reviewed", "reviewed", "will review", "will have reviewed"], a: 0, t: "T5", d: 1000, why: "once(いったん〜したら)も時の副詞節をつくる.節の中では will を使わない.「検討し終えたら」という完了は現在完了 has reviewed で表す(未来完了の代わり).", ja: "部長はすべての提案を検討し終えたら決定を下す." },
  { id: "g122", q: "The discount will apply only if payment ____ within ten days.", c: ["will be made", "is made", "was made", "made"], a: 1, t: "T5", d: 900, why: "if 以下は条件の副詞節なので現在形.payment は「支払われる」側なので受動態 is made.", ja: "割引は,10日以内に支払いが行われた場合にだけ適用される." },
  { id: "g123", q: "Please do not start the machine until the supervisor ____ you permission.", c: ["gives", "will give", "gave", "giving"], a: 0, t: "T5", d: 600, why: "until 以下は時の副詞節.未来のことでも現在形 gives.", ja: "監督者が許可を出すまで,機械を動かさないでください." },
  { id: "g124", q: "By the time the guests ____, the room will be ready.", c: ["will arrive", "arrived", "arriving", "arrive"], a: 3, t: "T5", d: 800, why: "by the time(〜するときまでに)も時の副詞節.主節が未来(will be)なので,節の中は現在形 arrive.", ja: "客が到着するまでには,部屋の準備ができているだろう." },
  { id: "g125", q: "I will let you know as soon as I ____ from the supplier.", c: ["will hear", "heard", "am heard", "hear"], a: 3, t: "T5", d: 700, why: "as soon as 以下は時の副詞節なので現在形 hear.", ja: "仕入先から連絡があり次第,お知らせします." },

  // T6
  { id: "g126", q: "All visitors ____ to sign in at the front desk.", c: ["require", "are required", "requiring", "have required"], a: 1, t: "T6", d: 500, why: "visitors は「求められる」側なので受動態 are required.be required to do で「〜するよう求められる」.", ja: "来訪者は全員,受付で署名するよう求められる." },
  { id: "g127", q: "The annual report ____ to shareholders next week.", c: ["will be sent", "will send", "has sent", "is sending"], a: 0, t: "T6", d: 600, why: "report は「送られる」側.空所の後ろに目的語がないことも受動態の目印.未来なので will be sent.", ja: "年次報告書は来週,株主に送られる." },
  { id: "g128", q: "The conference room is currently ____.", c: ["being cleaned", "cleaned", "cleaning", "been cleaned"], a: 0, t: "T6", d: 900, why: "部屋は「掃除される」側で,currently(今ちょうど)なので進行形の受動態 be + being + 過去分詞.", ja: "会議室は今,清掃中だ." },
  { id: "g129", q: "The winner of the design contest ____ yesterday.", c: ["announced", "was announced", "has announced", "was announcing"], a: 1, t: "T6", d: 600, why: "winner は「発表される」側.後ろに目的語がなく,yesterday があるので過去の受動態 was announced.", ja: "デザインコンテストの優勝者は昨日発表された." },
  { id: "g130", q: "Employees ____ a bonus at the end of each year.", c: ["give", "are giving", "have given", "are given"], a: 3, t: "T6", d: 800, why: "従業員は賞与を「与えられる」側.give 人 物 の受動態は「人 + be given + 物」で,後ろに名詞 a bonus が残る.後ろに名詞があっても能動態とは限らない.", ja: "従業員は毎年末に賞与を支給される." },
  { id: "g131", q: "The package should ____ by a manager before it is shipped.", c: ["check", "be checking", "have checked", "be checked"], a: 3, t: "T6", d: 700, why: "package は「確認される」側.by a manager(部長によって)も受動態の目印.助動詞 should の後ろは be + 過去分詞.", ja: "荷物は発送前に部長の確認を受けなければならない." },
  { id: "g132", q: "The accident ____ at the intersection last night.", c: ["was occurred", "has been occurred", "occurred", "occurring"], a: 2, t: "T6", d: 1300, why: "occur(起こる)は目的語をとらない自動詞なので,受動態にできない.「〜される」と訳せそうでも,happen, occur, arrive, rise などは能動態のまま使う.", ja: "その事故は昨夜,交差点で起きた." },

  // T7
  { id: "g133", q: "We are looking forward to ____ with you again.", c: ["working", "work", "worked", "be working"], a: 0, t: "T7", d: 600, why: "look forward to の to は前置詞.後ろは動名詞 working.", ja: "またご一緒に仕事ができることを楽しみにしています." },
  { id: "g134", q: "In addition to ____ the store, Mr. Yamada trains new staff.", c: ["manage", "manages", "managing", "managed"], a: 2, t: "T7", d: 900, why: "in addition to(〜に加えて)の to は前置詞.後ろは動名詞 managing.", ja: "山田さんは店の運営に加えて,新人の研修も行う." },
  { id: "g135", q: "Ms. Green is used to ____ long hours.", c: ["work", "worked", "works", "working"], a: 3, t: "T7", d: 1000, why: "be used to 〜(〜に慣れている)の to は前置詞.後ろは動名詞 working.", ja: "グリーンさんは長時間働くことに慣れている." },
  { id: "g136", q: "The team is dedicated to ____ customer satisfaction.", c: ["improve", "improves", "improved", "improving"], a: 3, t: "T7", d: 900, why: "be dedicated to(〜に打ち込んでいる)の to は前置詞.後ろは動名詞 improving.", ja: "そのチームは顧客満足度の向上に力を注いでいる." },
  { id: "g137", q: "Many residents objected to ____ a factory near the school.", c: ["build", "built", "building", "be built"], a: 2, t: "T7", d: 1100, why: "object to(〜に反対する)の to は前置詞.後ろは動名詞 building.", ja: "多くの住民が学校の近くに工場を建てることに反対した." },
  { id: "g138", q: "Prior to ____ the company, Ms. Lee worked for a bank.", c: ["join", "joined", "joins", "joining"], a: 3, t: "T7", d: 1000, why: "prior to(〜より前に)の to は前置詞.before と同じ意味で,後ろは動名詞 joining.", ja: "入社する前,リーさんは銀行に勤めていた." },
  { id: "g139", q: "The new system will contribute to ____ waste.", c: ["reducing", "reduce", "reduced", "reduces"], a: 0, t: "T7", d: 1000, why: "contribute to(〜に貢献する)の to は前置詞.後ろは動名詞 reducing.", ja: "新しい仕組みはごみの削減に役立つだろう." },
  { id: "g140", q: "Mr. Ito used to ____ in the Osaka branch.", c: ["work", "working", "worked", "works"], a: 0, t: "T7", d: 1200, why: "be 動詞がない used to は「以前は〜していた」という助動詞のような表現で,後ろは原形 work.be used to + -ing(〜に慣れている)と区別する.be があるかどうかで決まる.", ja: "伊藤さんは以前,大阪支店で働いていた." },

  // T8
  { id: "g141", q: "The woman ____ called this morning left a message for you.", c: ["who", "which", "whose", "whom"], a: 0, t: "T8", d: 400, why: "先行詞 woman は人で,空所は called の主語なので who.", ja: "今朝電話をかけてきた女性が,あなたに伝言を残した." },
  { id: "g142", q: "The printer ____ we bought last month is already broken.", c: ["which", "whom", "who", "what"], a: 0, t: "T8", d: 500, why: "先行詞 printer は物なので which.what は先行詞があるときには使えない.", ja: "先月買ったプリンターがもう壊れている." },
  { id: "g143", q: "Mr. Tanaka, ____ joined us in May, has been promoted.", c: ["that", "which", "who", "whose"], a: 2, t: "T8", d: 800, why: "先行詞は人(Mr. Tanaka)で,カンマの後なので that は使えない.who が入る.", ja: "5月に入社した田中さんが昇進した." },
  { id: "g144", q: "The software, ____ costs $200, is easy to use.", c: ["that", "what", "who", "which"], a: 3, t: "T8", d: 700, why: "先行詞 software は物.カンマの後(非制限用法)では that は使えないので which.", ja: "そのソフトは200ドルで,使いやすい." },
  { id: "g145", q: "The clients ____ we met in Seoul have placed a large order.", c: ["which", "what", "whose", "whom"], a: 3, t: "T8", d: 900, why: "先行詞 clients は人.空所は met の目的語(we met them)なので目的格 whom.", ja: "ソウルで会った顧客が大口の注文をしてくれた." },
  { id: "g146", q: "Anyone ____ wishes to attend should register by Friday.", c: ["who", "which", "whom", "whose"], a: 0, t: "T8", d: 700, why: "先行詞 anyone は人.空所は wishes の主語なので who(whom は目的語のとき).", ja: "出席を希望する人は金曜日までに登録してください." },
  { id: "g147", q: "This is the only model ____ is still in stock.", c: ["who", "what", "that", "whom"], a: 2, t: "T8", d: 1000, why: "先行詞 model は物なので who / whom は不可.what は先行詞があるので不可.the only や最上級が付く先行詞には that がよく使われる.", ja: "在庫が残っているのはこの機種だけだ." },

  // T9
  { id: "g148", q: "____ the meeting, please turn off your mobile phones.", c: ["During", "While", "When", "As"], a: 0, t: "T9", d: 500, why: "後ろは名詞句 the meeting だけなので前置詞 during.while / when / as は後ろに節が必要.", ja: "会議中は携帯電話の電源を切ってください." },
  { id: "g149", q: "The game was postponed ____ it was raining heavily.", c: ["because of", "due to", "because", "despite"], a: 2, t: "T9", d: 500, why: "後ろは節(it was raining)なので接続詞 because.because of / due to / despite は前置詞.", ja: "大雨が降っていたので試合は延期された." },
  { id: "g150", q: "____ his lack of experience, Mr. Hill was offered the job.", c: ["Despite", "Although", "Even though", "However"], a: 0, t: "T9", d: 800, why: "後ろは名詞句 his lack of experience なので前置詞 despite(〜にもかかわらず).although / even though は接続詞.", ja: "経験不足にもかかわらず,ヒルさんはその仕事を提示された." },
  { id: "g151", q: "The office will be closed ____ the national holiday.", c: ["because", "although", "while", "due to"], a: 3, t: "T9", d: 700, why: "後ろは名詞句 the national holiday なので前置詞 due to(〜のため).", ja: "祝日のため事務所は休みになる." },
  { id: "g152", q: "____ sales were lower than expected, the company still made a profit.", c: ["Despite", "In spite of", "Because of", "Even though"], a: 3, t: "T9", d: 900, why: "後ろは節(sales were lower)なので接続詞 even though(〜だけれども).despite / in spite of は意味は同じでも前置詞.", ja: "売上は予想より低かったが,それでも会社は利益を出した." },
  { id: "g153", q: "Employees may not use their phones ____ working on the factory floor.", c: ["during", "while", "for", "among"], a: 1, t: "T9", d: 1200, why: "working は「they are working」の主語と be 動詞を省いた形で,節の扱い.while + -ing で「〜している間」.during の後ろには名詞(their work など)が必要で,-ing は置けない.", ja: "従業員は工場の現場で作業している間,電話を使ってはならない." },

  // T10
  { id: "g154", q: "The documents on the desk ____ to Ms. Park.", c: ["belong", "belonging", "belongs", "is belonging"], a: 0, t: "T10", d: 600, why: "主語の中心は複数の documents(on the desk は修飾語).動詞は複数に合わせて belong.", ja: "机の上の書類はパークさんのものだ." },
  { id: "g155", q: "One of our best customers ____ moved overseas.", c: ["have", "has", "are", "were"], a: 1, t: "T10", d: 700, why: "主語の中心は One(1人).of 以下の customers につられない.単数なので has.", ja: "当社の最良の顧客の1人が海外に引っ越した." },
  { id: "g156", q: "Everyone in the sales and marketing departments ____ invited to the party.", c: ["are", "were", "have been", "is"], a: 3, t: "T10", d: 900, why: "主語 Everyone は単数扱い.直前の departments(複数)につられない.", ja: "営業部とマーケティング部の全員がパーティーに招待されている." },
  { id: "g157", q: "The results of the survey ____ that customers prefer online payment.", c: ["shows", "show", "showing", "is shown"], a: 1, t: "T10", d: 800, why: "主語の中心は複数の results.直前の survey(単数)につられない.", ja: "調査の結果は,客がオンライン決済を好むことを示している." },
  { id: "g158", q: "The information in these reports ____ confidential.", c: ["is", "are", "were", "have been"], a: 0, t: "T10", d: 800, why: "主語の中心 information は数えられない名詞で単数扱い.直前の reports につられない.", ja: "これらの報告書の情報は機密だ." },
  { id: "g159", q: "Mr. Cho, along with his two assistants, ____ arriving tomorrow.", c: ["are", "were", "is", "have been"], a: 2, t: "T10", d: 1300, why: "along with 〜(〜と一緒に)は前置詞のまとまりで,主語を複数にしない(and とは違う).主語は Mr. Cho 1人なので is.as well as, together with も同じ.", ja: "チョさんは2人の助手と一緒に明日到着する." },
  { id: "g160", q: "There ____ several reasons for the delay.", c: ["is", "was", "are", "has been"], a: 2, t: "T10", d: 600, why: "There is / are の文では,動詞は後ろの名詞に合わせる.reasons は複数なので are.", ja: "遅れにはいくつかの理由がある." },
  { id: "g161", q: "The staff members who work at the front desk ____ very helpful.", c: ["is", "was", "has been", "are"], a: 3, t: "T10", d: 900, why: "主語の中心は複数の members.who ... desk は members を説明する節で,直前の desk(単数)は主語ではない.", ja: "受付で働くスタッフはとても親切だ." },

  // T11
  { id: "g162", q: "This quarter's sales were ____ than we expected.", c: ["high", "higher", "highest", "more high"], a: 1, t: "T11", d: 400, why: "than があるので比較級 higher.短い語は -er を付ける(more high とは言わない).", ja: "今四半期の売上は予想より高かった." },
  { id: "g163", q: "Of the three plans, the second is the ____ expensive.", c: ["less", "lesser", "little", "least"], a: 3, t: "T11", d: 800, why: "Of the three(3つの中で)とあり,前に the があるので最上級.the least + 形容詞 で「最も〜でない」.", ja: "3つの案の中で,2番目が最も安い." },
  { id: "g164", q: "Please reply as ____ as possible.", c: ["soon", "sooner", "soonest", "more soon"], a: 0, t: "T11", d: 400, why: "as ___ as の間は原級 soon.as soon as possible で「できるだけ早く」.", ja: "できるだけ早く返信してください." },
  { id: "g165", q: "The new model is ____ more efficient than the old one.", c: ["very", "much", "many", "more"], a: 1, t: "T11", d: 900, why: "比較級 more efficient を強めるのは much(はるかに).very は原級しか強められない.", ja: "新しい機種は古い機種よりはるかに効率的だ." },
  { id: "g166", q: "Mr. Ono works ____ than anyone else in the department.", c: ["hardly", "hard", "hardest", "harder"], a: 3, t: "T11", d: 600, why: "than があるので比較級 harder.hardly は「ほとんど〜ない」という別の語.", ja: "小野さんは部署のだれよりも熱心に働く." },
  { id: "g167", q: "The ____ you order, the lower the price per unit.", c: ["many", "most", "more", "much"], a: 2, t: "T11", d: 1300, why: "「the + 比較級, the + 比較級」で「〜すればするほど…」.後半が the lower なので,前半も比較級 more.", ja: "注文が多ければ多いほど,1個あたりの価格は下がる." },

  // T12
  { id: "g168", q: "The ____ schedule will be posted on the Web site.", c: ["update", "updating", "updated", "updates"], a: 2, t: "T12", d: 600, why: "schedule は「更新される」側なので過去分詞 updated.", ja: "更新された予定表は Web サイトに掲載される." },
  { id: "g169", q: "The seminar was so ____ that several people left early.", c: ["boring", "bored", "bore", "boredom"], a: 0, t: "T12", d: 600, why: "主語 seminar は人を「退屈させる」側なので現在分詞 boring.人が主語なら bored.", ja: "そのセミナーはとても退屈で,数人が早く帰った." },
  { id: "g170", q: "Customers ____ in the survey will receive a coupon.", c: ["participating", "participated", "participate", "participation"], a: 0, t: "T12", d: 1000, why: "文の動詞は will receive.空所は customers を後ろから修飾する分詞.customers は「参加する」側で,participate は自動詞(受け身にならない)なので現在分詞 participating.", ja: "調査に参加する客はクーポンを受け取れる." },
  { id: "g171", q: "The items ____ in this catalog are available online.", c: ["list", "listing", "to list", "listed"], a: 3, t: "T12", d: 900, why: "文の動詞は are.items は「掲載される」側なので過去分詞 listed が後ろから修飾する(which are listed の省略).", ja: "このカタログに載っている商品はオンラインで買える." },
  { id: "g172", q: "We were ____ to hear that the event had been canceled.", c: ["surprised", "surprise", "surprising", "surprisingly"], a: 0, t: "T12", d: 500, why: "主語 We(人)は「驚かされる」側なので過去分詞 surprised.", ja: "催しが中止になったと聞いて私たちは驚いた." },
  { id: "g173", q: "Please return the ____ contract by mail.", c: ["sign", "signing", "signed", "signs"], a: 2, t: "T12", d: 700, why: "contract は「署名される」側なので過去分詞 signed.the と名詞の間で形容詞の働きをする(T1).", ja: "署名済みの契約書を郵送で返送してください." },

  // T13
  { id: "g174", q: "Ms. Chen asked ____ to send the files by noon.", c: ["we", "our", "us", "ourselves"], a: 2, t: "T13", d: 400, why: "動詞 asked の目的語なので目的格 us.ask 人 to do で「人に〜するよう頼む」.", ja: "チェンさんは私たちに,正午までにファイルを送るよう頼んだ." },
  { id: "g175", q: "The directors will announce ____ decision tomorrow.", c: ["their", "they", "them", "theirs"], a: 0, t: "T13", d: 400, why: "後ろに名詞 decision があるので所有格 their.theirs は「彼らのもの」で,後ろに名詞を置けない.", ja: "取締役たちは明日,決定を発表する." },
  { id: "g176", q: "The new employees introduced ____ at the morning meeting.", c: ["they", "their", "them", "themselves"], a: 3, t: "T13", d: 800, why: "introduce の目的語が主語(the new employees)と同じ人なので再帰代名詞 themselves.introduce oneself で「自己紹介する」.", ja: "新入社員たちは朝礼で自己紹介をした." },
  { id: "g177", q: "This desk is Ms. Wada's, and the one by the window is ____.", c: ["my", "me", "mine", "myself"], a: 2, t: "T13", d: 700, why: "「私のもの(= my desk)」を1語で表す所有代名詞 mine.my は後ろに名詞が必要.", ja: "この机は和田さんので,窓際のが私のだ." },
  { id: "g178", q: "Please keep this copy and return the other one to ____.", c: ["we", "us", "our", "ours"], a: 1, t: "T13", d: 500, why: "前置詞 to の目的語なので目的格 us.", ja: "この控えは保管し,もう1枚は私たちに返送してください." },
  { id: "g179", q: "A friend of ____ recommended this restaurant.", c: ["mine", "me", "my", "myself"], a: 0, t: "T13", d: 1100, why: "a friend of mine で「私の友人の1人」.a と my は並べられない(a my friend は不可)ので,of + 所有代名詞 の形にする.", ja: "友人の1人がこのレストランを薦めてくれた." },

  // T14
  { id: "g180", q: "The seminar is open to ____ members and non-members.", c: ["either", "not only", "neither", "both"], a: 3, t: "T14", d: 500, why: "後ろの and と組むのは both.", ja: "そのセミナーは会員と非会員の両方が参加できる." },
  { id: "g181", q: "Neither the red model ____ the blue one is in stock.", c: ["or", "and", "nor", "but"], a: 2, t: "T14", d: 600, why: "neither と組むのは nor.", ja: "赤い機種も青い機種も在庫がない." },
  { id: "g182", q: "You may contact us either by phone ____ by e-mail.", c: ["and", "nor", "but", "or"], a: 3, t: "T14", d: 500, why: "either と組むのは or.", ja: "電話かメールのどちらかでご連絡ください." },
  { id: "g183", q: "The new system is not only faster ____ also easier to use.", c: ["and", "but", "or", "so"], a: 1, t: "T14", d: 600, why: "not only と組むのは but (also).", ja: "新しいシステムは速いだけでなく,使いやすくもある." },
  { id: "g184", q: "____ the manager and the staff were pleased with the results.", c: ["Both", "Either", "Neither", "Whether"], a: 0, t: "T14", d: 700, why: "後ろの and と組むのは both.both A and B が主語のときは複数扱い(were).", ja: "部長もスタッフも結果に満足していた." },
  { id: "g185", q: "Either the manager or her assistants ____ going to attend the ceremony.", c: ["is", "are", "was", "has"], a: 1, t: "T14", d: 1300, why: "either A or B / neither A nor B が主語のとき,動詞は近い方(B)に合わせる.B は assistants(複数)なので are.", ja: "部長か,その助手たちのどちらかが式典に出席する予定だ." },

  // T15
  { id: "g186", q: "We hope ____ you at the opening ceremony.", c: ["see", "to see", "seeing", "seen"], a: 1, t: "T15", d: 400, why: "hope は目的語に to do をとる.", ja: "開会式でお会いできることを願っています." },
  { id: "g187", q: "Would you mind ____ the window?", c: ["open", "to open", "opening", "opened"], a: 2, t: "T15", d: 600, why: "mind は目的語に -ing をとる.Would you mind -ing? で「〜していただけますか」.", ja: "窓を開けていただけますか." },
  { id: "g188", q: "The supplier agreed ____ the price by 5 percent.", c: ["lower", "lowering", "lowered", "to lower"], a: 3, t: "T15", d: 600, why: "agree は目的語に to do をとる.", ja: "仕入先は価格を5%下げることに同意した." },
  { id: "g189", q: "Ms. Mori suggested ____ the meeting until next week.", c: ["postponing", "postpone", "to postpone", "postponed"], a: 0, t: "T15", d: 900, why: "suggest は目的語に -ing をとる(to do は不可).", ja: "森さんは会議を来週まで延期することを提案した." },
  { id: "g190", q: "The company cannot afford ____ another mistake.", c: ["make", "to make", "making", "made"], a: 1, t: "T15", d: 900, why: "afford(〜する余裕がある)は目的語に to do をとる.", ja: "その会社には,これ以上ミスをする余裕はない." },
  { id: "g191", q: "Please remember ____ the door when you leave tonight.", c: ["lock", "locking", "to lock", "locked"], a: 2, t: "T15", d: 1200, why: "remember to do は「(これから)忘れずに〜する」,remember -ing は「(過去に)〜したことを覚えている」.今夜これからのことなので to lock.to do はこれからのこと,-ing はすでにしたこと.", ja: "今夜帰るとき,忘れずにドアに鍵をかけてください." },

  // T16
  { id: "g192", q: "The doctor recommended that Mr. Ito ____ more rest.", c: ["gets", "get", "got", "getting"], a: 1, t: "T16", d: 1000, why: "recommend に続く that 節では,主語が3人称単数でも動詞は原形 get.", ja: "医師は伊藤さんに,もっと休養をとるよう勧めた." },
  { id: "g193", q: "It is essential that every visitor ____ a helmet.", c: ["wears", "wore", "wear", "wearing"], a: 2, t: "T16", d: 1100, why: "It is essential / important / necessary that ...(〜することが必要だ)も要求を表すので,動詞は原形 wear.", ja: "すべての来訪者がヘルメットを着用することが不可欠だ." },
  { id: "g194", q: "The board proposed that the budget ____ increased.", c: ["be", "is", "was", "being"], a: 0, t: "T16", d: 1200, why: "propose に続く that 節では動詞は原形.受動態なので be increased.", ja: "取締役会は予算を増やすことを提案した." },
  { id: "g195", q: "The manager suggested that Ms. Ota ____ the launch date.", c: ["changed", "changes", "will change", "change"], a: 3, t: "T16", d: 1000, why: "suggest に続く that 節では,主語や時制に関係なく動詞は原形 change.", ja: "部長は太田さんに,発売日を変更するよう提案した." },
  { id: "g196", q: "The lawyer advised that the company not ____ the contract yet.", c: ["signs", "sign", "signed", "signing"], a: 1, t: "T16", d: 1300, why: "要求・提案の that 節の否定は「not + 原形」(does not は使わない).", ja: "弁護士は,会社がまだ契約に署名しないよう助言した." },
  { id: "g197", q: "The city requires that all restaurants ____ inspected once a year.", c: ["been", "are", "were", "be"], a: 3, t: "T16", d: 1200, why: "require に続く that 節では動詞は原形.受動態なので be inspected.", ja: "市は,すべての飲食店が年に1回検査を受けることを義務づけている." },
  { id: "g198", q: "The client demanded that the error ____ immediately.", c: ["corrects", "be corrected", "is correcting", "corrected"], a: 1, t: "T16", d: 1300, why: "demand に続く that 節では動詞は原形.error は「直される」側なので受動態 be corrected.", ja: "顧客は誤りをただちに直すよう要求した." },

  // T17
  { id: "g199", q: "We have received ____ applications for the position so far.", c: ["much", "a little", "many", "every"], a: 2, t: "T17", d: 400, why: "applications は数えられる名詞の複数形なので many.every の後ろは単数形.", ja: "その職にはこれまでに多くの応募があった." },
  { id: "g200", q: "There is very ____ information available about the new product.", c: ["few", "little", "many", "several"], a: 1, t: "T17", d: 600, why: "information は数えられない名詞なので little(ほとんどない).", ja: "新製品について手に入る情報はほとんどない." },
  { id: "g201", q: "____ employee is given a locker.", c: ["All", "Each", "Many", "Several"], a: 1, t: "T17", d: 500, why: "後ろが単数形 employee で動詞も is なので each.all / many / several の後ろは複数形.", ja: "各従業員にロッカーが与えられる." },
  { id: "g202", q: "Only a ____ seats are still available for tonight's show.", c: ["few", "little", "much", "less"], a: 0, t: "T17", d: 600, why: "seats は数えられる名詞の複数形なので a few(少しの).", ja: "今夜の公演の席は,あとわずかしか残っていない." },
  { id: "g203", q: "____ of the equipment in the lab needs to be replaced.", c: ["Many", "Few", "Several", "Much"], a: 3, t: "T17", d: 1000, why: "equipment は数えられない名詞なので much.動詞が needs(単数)であることも手がかり.equipment, furniture, luggage, advice は数えられない.", ja: "研究室の機器の多くは交換する必要がある." },
  { id: "g204", q: "____ the rooms on this floor have been reserved.", c: ["Every", "Each", "Almost", "All"], a: 3, t: "T17", d: 1100, why: "the + 複数名詞の前に直接置けるのは all(all the rooms).every / each の後ろは冠詞なしの単数形.almost は副詞なので almost all the rooms とする.", ja: "この階の部屋はすべて予約済みだ." },

  // T18
  { id: "g205", q: "The library is open ____ 8:00 P.M. on weekdays.", c: ["by", "until", "within", "among"], a: 1, t: "T18", d: 500, why: "開いている状態が午後8時までずっと続く.継続なので until.", ja: "図書館は平日,午後8時まで開いている." },
  { id: "g206", q: "Please return the signed form ____ the end of the week.", c: ["by", "until", "since", "while"], a: 0, t: "T18", d: 500, why: "返送は期限までに1回済ませる動作なので by.", ja: "署名した用紙を週末までに返送してください." },
  { id: "g207", q: "The repairs must be finished ____ noon tomorrow.", c: ["until", "during", "by", "since"], a: 2, t: "T18", d: 600, why: "finish(終える)は期限までに1回済ませる動作なので by.", ja: "修理は明日の正午までに終えなければならない." },
  { id: "g208", q: "Mr. Sato will be away on business ____ next Thursday.", c: ["within", "by", "at", "until"], a: 3, t: "T18", d: 700, why: "不在の状態が来週の木曜日まで続く.継続なので until.", ja: "佐藤さんは来週の木曜日まで出張で不在だ." },
  { id: "g209", q: "You can keep the rental car ____ Sunday evening.", c: ["by", "until", "since", "among"], a: 1, t: "T18", d: 700, why: "keep(持ち続ける)は続く状態.日曜の夕方までずっと,なので until.", ja: "レンタカーは日曜の夕方まで借りていられる." },
  { id: "g210", q: "____ the time we arrived, the presentation had already begun.", c: ["Until", "By", "Since", "During"], a: 1, t: "T18", d: 1000, why: "by the time + 節 で「〜するときまでには(すでに)」.期限の by.主節の完了形(had begun)と組むことが多い.", ja: "私たちが着いたときには,発表はすでに始まっていた." },
  { id: "g211", q: "Please stay in your seats ____ the plane has come to a complete stop.", c: ["by", "during", "until", "within"], a: 2, t: "T18", d: 800, why: "stay(とどまる)は続く状態.後ろに節が来る接続詞としても使える until.during は前置詞で,節は続かない.", ja: "飛行機が完全に止まるまで,席に着いたままでいてください." },

  // T19
  { id: "g212", q: "The author ____ book became a bestseller will speak tonight.", c: ["who", "whose", "which", "what"], a: 1, t: "T19", d: 700, why: "空所の後ろが「冠詞のない名詞 book + 動詞 became」.author の(持ち物の)本なので whose.", ja: "著書がベストセラーになった作家が今夜講演する." },
  { id: "g213", q: "____ we need now is more time.", c: ["That", "Which", "What", "Whose"], a: 2, t: "T19", d: 800, why: "先行詞がなく,「私たちが今必要としているもの」を表すので what.", ja: "今私たちに必要なのは,もっと多くの時間だ." },
  { id: "g214", q: "Please tell me ____ you would like for lunch.", c: ["what", "that", "whose", "it"], a: 0, t: "T19", d: 500, why: "先行詞がなく,would like の目的語が欠けている.「昼食に欲しいもの」なので what.", ja: "昼食に何がよいか教えてください." },
  { id: "g215", q: "Companies ____ employees are satisfied tend to be more productive.", c: ["who", "which", "whose", "what"], a: 2, t: "T19", d: 1000, why: "空所の後ろが「冠詞のない名詞 employees + 動詞 are」.companies の従業員なので whose(物が先行詞でも使える).", ja: "従業員が満足している会社は,生産性が高い傾向がある." },
  { id: "g216", q: "The manager explained ____ had caused the delay.", c: ["that", "what", "whose", "where"], a: 1, t: "T19", d: 1000, why: "explained の後ろに先行詞がなく,had caused の主語が欠けている.「遅れを引き起こしたもの」なので what.that は後ろが完全な文のときに使う.", ja: "部長は何が遅れを引き起こしたのかを説明した." },
  { id: "g217", q: "We stayed at a hotel ____ rooms overlook the ocean.", c: ["which", "that", "what", "whose"], a: 3, t: "T19", d: 900, why: "空所の後ろが「冠詞のない名詞 rooms + 動詞 overlook」.hotel の部屋なので whose.", ja: "私たちは,部屋から海が見渡せるホテルに泊まった." },
  { id: "g218", q: "____ impressed the clients most was the quality of the presentation.", c: ["What", "That", "Whose", "Which"], a: 0, t: "T19", d: 1100, why: "先行詞がなく,「顧客を最も感心させたもの」という主語のまとまりをつくるので what.", ja: "顧客を最も感心させたのは,発表の質だった." },
  { id: "g219", q: "The results were quite different from ____ we had expected.", c: ["which", "that", "what", "whose"], a: 2, t: "T19", d: 1200, why: "前置詞 from の後ろで先行詞がなく,expected の目的語が欠けている.「私たちが予想していたもの」なので what.", ja: "結果は私たちが予想していたものとかなり違っていた." },

  // T20
  { id: "g220", q: "The new procedure seems ____.", c: ["complicate", "complication", "complicated", "complicatedly"], a: 2, t: "T20", d: 700, why: "seem の後ろ(補語の位置)なので形容詞 complicated(複雑な).", ja: "新しい手続きは複雑そうだ." },
  { id: "g221", q: "Please remain ____ until the bus has stopped.", c: ["seat", "seated", "seating", "seats"], a: 1, t: "T20", d: 800, why: "remain の後ろは補語で形容詞.人は「座らされている」側なので seated(座った状態の).", ja: "バスが止まるまで座ったままでいてください." },
  { id: "g222", q: "The instructions were not ____ to the new staff.", c: ["clearly", "clear", "clarity", "clears"], a: 1, t: "T20", d: 500, why: "be 動詞の後ろの補語なので形容詞 clear.副詞 clearly は補語になれない.", ja: "その指示は新しいスタッフには分かりにくかった." },
  { id: "g223", q: "It is ____ to arrive at the airport two hours early.", c: ["advise", "advice", "advisably", "advisable"], a: 3, t: "T20", d: 900, why: "It is ___ to do の空所は補語で形容詞 advisable(望ましい).-able は形容詞の語尾.", ja: "空港には2時間前に着くのが望ましい." },
  { id: "g224", q: "The manager became ____ when the shipment did not arrive.", c: ["anxious", "anxiously", "anxiety", "anxiousness"], a: 0, t: "T20", d: 700, why: "become の後ろは補語で形容詞 anxious(心配な).", ja: "荷物が届かず,部長は心配になった." },
  { id: "g225", q: "The plan sounds ____ to me.", c: ["reasonably", "reason", "reasoning", "reasonable"], a: 3, t: "T20", d: 800, why: "sound(〜に聞こえる)の後ろは補語で形容詞 reasonable(妥当な).look, sound, feel, taste の後ろも形容詞.", ja: "その計画は私には妥当に思える." },
  { id: "g226", q: "Please keep the storage area ____ at all times.", c: ["neat", "neatly", "neatness", "neaten"], a: 0, t: "T20", d: 1200, why: "keep + 目的語 + 形容詞 で「〜を…の状態に保つ」.空所は目的語 the storage area の状態を説明する補語なので形容詞 neat.副詞 neatly にしないこと.", ja: "保管場所は常に整頓しておいてください." },
  { id: "g227", q: "The CEO remained ____ about the company's future.", c: ["optimism", "optimist", "optimistically", "optimistic"], a: 3, t: "T20", d: 1000, why: "remain の後ろは補語で形容詞 optimistic(楽観的な).-ic は形容詞の語尾.", ja: "CEO は会社の将来について楽観的なままだった." },

  // T21
  { id: "g228", q: "____ the item arrive damaged, we will replace it free of charge.", c: ["Had", "Should", "Were", "Did"], a: 1, t: "T21", d: 1300, why: "主語 the item の後ろが原形 arrive.「Should + 主語 + 原形」で「万一〜なら」(If the item should arrive の if を省いた形).", ja: "万一商品が破損して届いた場合は,無料で交換します." },
  { id: "g229", q: "____ I known about the meeting, I would have attended.", c: ["Have", "Did", "Had", "Were"], a: 2, t: "T21", d: 1200, why: "主語 I の後ろが過去分詞 known で,主節が would have + 過去分詞.「Had + 主語 + 過去分詞」(If I had known の if を省いた形).", ja: "会議のことを知っていたら,出席したのに." },
  { id: "g230", q: "____ I in your position, I would accept the offer.", c: ["Were", "Had", "Should", "If"], a: 0, t: "T21", d: 1300, why: "主節が would + 原形で,今の事実と違う仮定.「Were + 主語」(If I were in your position の if を省いた形).If を入れると動詞がなくなる.", ja: "私があなたの立場なら,その申し出を受ける." },
  { id: "g231", q: "Had the team ____ more time, the report would have been more detailed.", c: ["has", "have", "had", "having"], a: 2, t: "T21", d: 1400, why: "文頭の Had は「Had + 主語 + 過去分詞」の助動詞.空所には have(持つ)の過去分詞 had が入る(If the team had had more time).", ja: "チームにもっと時間があったら,報告書はもっと詳しくなっていただろう." },
  { id: "g232", q: "Should you ____ to cancel your order, please let us know within 24 hours.", c: ["wish", "wished", "wishing", "to wish"], a: 0, t: "T21", d: 1200, why: "「Should + 主語 + 原形」なので原形 wish.", ja: "万一ご注文の取り消しをご希望の場合は,24時間以内にお知らせください." },
  { id: "g233", q: "____ it not been for your help, we could not have finished on time.", c: ["Should", "Were", "Has", "Had"], a: 3, t: "T21", d: 1500, why: "後ろが過去分詞 been で,主節が could not have + 過去分詞(過去の事実と違う仮定).Had it not been for 〜 で「〜がなかったら」(If it had not been for の倒置).", ja: "あなたの助けがなかったら,期限どおりに終えられなかっただろう." },
  { id: "g234", q: "____ the weather be bad, the event will be moved indoors.", c: ["Would", "If", "Should", "Had"], a: 2, t: "T21", d: 1300, why: "主語 the weather の後ろが原形 be.「Should + 主語 + 原形」で「万一〜なら」.If なら the weather is bad になるはず.", ja: "万一天気が悪ければ,催しは屋内に移される." },
  { id: "g235", q: "Were the company ____ its prices, it would lose many customers.", c: ["raise", "raised", "raising", "to raise"], a: 3, t: "T21", d: 1600, why: "「Were + 主語 + to do」で「仮に〜するとしたら」(If the company were to raise の if を省いた形).実現しそうにない未来の仮定を表す.", ja: "仮にその会社が値上げをしたら,多くの客を失うだろう." },

  // T22
  { id: "g236", q: "If we had a larger budget, we ____ more staff.", c: ["hire", "will hire", "would hire", "had hired"], a: 2, t: "T22", d: 900, why: "If + 過去形(had)は今の事実と違う仮定.主節は would + 原形.", ja: "予算がもっと多ければ,もっとスタッフを雇うのに." },
  { id: "g237", q: "If I ____ you, I would talk to the manager first.", c: ["am", "were", "be", "have been"], a: 1, t: "T22", d: 800, why: "今の事実と違う仮定は過去形.仮定法では be 動詞は主語に関係なく were.If I were you で「私があなたなら」.", ja: "私があなたなら,まず部長に相談する." },
  { id: "g238", q: "If the train had not been delayed, we ____ on time.", c: ["arrived", "would arrive", "will arrive", "would have arrived"], a: 3, t: "T22", d: 1100, why: "If + had + 過去分詞 は過去の事実と違う仮定.主節は would have + 過去分詞.", ja: "電車が遅れなかったら,時間どおりに着いていたのに." },
  { id: "g239", q: "If Mr. Abe ____ the e-mail earlier, he could have replied before the deadline.", c: ["had read", "reads", "has read", "would read"], a: 0, t: "T22", d: 1200, why: "主節が could have + 過去分詞(過去の事実と違う仮定)なので,if 節は had + 過去分詞.would の代わりに could, might も使える.", ja: "阿部さんがもっと早くメールを読んでいたら,期限前に返信できたのに." },
  { id: "g240", q: "We ____ the order if the price were lower.", c: ["will place", "place", "would place", "placed"], a: 2, t: "T22", d: 1000, why: "if 節が過去形 were(今の事実と違う仮定)なので,主節は would + 原形.if 節が後ろにあっても同じ.", ja: "価格がもっと低ければ,注文するのだが." },
  { id: "g241", q: "I wish I ____ more time to prepare for the presentation.", c: ["have", "had", "will have", "having"], a: 1, t: "T22", d: 1100, why: "I wish(〜ならいいのに)の後ろも今の事実と違う仮定なので,過去形 had.", ja: "発表の準備にもっと時間があればいいのに." },
  { id: "g242", q: "If it ____ sunny tomorrow, we will hold the event outside.", c: ["is", "were", "will be", "had been"], a: 0, t: "T22", d: 900, why: "主節が will + 原形なので,実際に起こりうる条件.仮定法ではなく,条件の副詞節の現在形(T5).主節が will か would かで見分ける.", ja: "明日晴れたら,催しは屋外で行う." },
  { id: "g243", q: "If the company had invested in new equipment last year, it ____ more competitive now.", c: ["is", "will be", "would be", "would have been"], a: 2, t: "T22", d: 1500, why: "if 節は過去の事実と違う仮定(had invested)だが,主節には now がある.「今〜だろうに」は would + 原形.時を表す語(last year / now)でそれぞれの形を決める.", ja: "昨年,新しい設備に投資していたら,その会社は今もっと競争力があるだろうに." },

  // T23
  { id: "g244", q: "____ in the center of the city, the hotel is popular with tourists.", c: ["Locate", "Locating", "Located", "Location"], a: 2, t: "T23", d: 1000, why: "主節の主語 the hotel は「位置づけられる」側(be located)なので過去分詞 Located.", ja: "市の中心にあるので,そのホテルは観光客に人気がある." },
  { id: "g245", q: "____ the instructions carefully, Mr. Hill assembled the shelf in an hour.", c: ["Follow", "Following", "Followed", "Follows"], a: 1, t: "T23", d: 1000, why: "主節の主語 Mr. Hill は説明書に「従う」側.後ろに目的語 the instructions もあるので現在分詞 Following.", ja: "説明書に注意深く従って,ヒルさんは1時間で棚を組み立てた." },
  { id: "g246", q: "____ from above, the lake looks like a heart.", c: ["Seeing", "See", "Seen", "To see"], a: 2, t: "T23", d: 1200, why: "主節の主語 the lake は「見られる」側なので過去分詞 Seen.訳は「見ると」でも,主語が何かで決める.", ja: "上から見ると,その湖はハートの形に見える." },
  { id: "g247", q: "____ finished the report, Ms. Ito went home.", c: ["Having", "Have", "Had", "Has"], a: 0, t: "T23", d: 1200, why: "Having + 過去分詞 は,主節より前に済んだことを表す分詞構文(報告書を終えてから帰った).主語 Ms. Ito は「終える」側なので -ing.", ja: "報告書を仕上げてから,伊藤さんは帰宅した." },
  { id: "g248", q: "The president entered the room, ____ by two assistants.", c: ["follow", "follows", "following", "followed"], a: 3, t: "T23", d: 1300, why: "分詞構文は文の後ろにも置ける.主語 the president は2人の助手に「続かれる」側で,by もあるので過去分詞 followed.", ja: "社長は2人の助手を従えて部屋に入った." },
  { id: "g249", q: "When ____ for a refund, please include the original receipt.", c: ["ask", "asked", "asking", "to ask"], a: 2, t: "T23", d: 1200, why: "接続詞 when の後ろで主語と be 動詞を省いた形(When you are asking).命令文の主語 you は「求める」側なので現在分詞 asking.", ja: "返金を求めるときは,領収書の原本を同封してください." },
  { id: "g250", q: "____ with last year, sales have increased by 10 percent.", c: ["Comparing", "Compare", "Compares", "Compared"], a: 3, t: "T23", d: 1300, why: "主節の主語 sales は昨年と「比べられる」側なので過去分詞 Compared.Compared with 〜 で「〜と比べると」.", ja: "昨年と比べると,売上は10%増えた." },

  // T24
  { id: "g251", q: "The room was ____ small that we could not hold the meeting there.", c: ["such", "so", "very", "too"], a: 1, t: "T24", d: 600, why: "後ろが形容詞 small だけで,that 節が続くので so.very は that 節と組めない.", ja: "部屋がとても狭くて,そこでは会議を開けなかった." },
  { id: "g252", q: "It was ____ a difficult question that nobody could answer it.", c: ["so", "very", "such", "too"], a: 2, t: "T24", d: 700, why: "後ろが「a + 形容詞 + 名詞」なので such.", ja: "とても難しい質問だったので,だれも答えられなかった." },
  { id: "g253", q: "The speaker talked ____ quickly that few people understood him.", c: ["so", "such", "much", "too"], a: 0, t: "T24", d: 700, why: "後ろが副詞 quickly だけなので so.", ja: "講演者はとても早口で,理解できた人はほとんどいなかった." },
  { id: "g254", q: "We received ____ many orders that we had to hire temporary staff.", c: ["such", "too", "very", "so"], a: 3, t: "T24", d: 1000, why: "名詞 orders があるが,many / much / few / little が付くときは so を使う(so many orders).数量の語は so と組む.", ja: "とても多くの注文を受けたので,臨時のスタッフを雇わなければならなかった." },
  { id: "g255", q: "They are ____ reliable suppliers that we have never looked for others.", c: ["so", "such", "too", "very"], a: 1, t: "T24", d: 900, why: "後ろが「形容詞 + 複数名詞」.名詞があるので such(複数形なので a は付かない).", ja: "とても信頼できる仕入先なので,ほかを探したことがない." },
  { id: "g256", q: "Ms. Ono gave ____ useful advice that we finished early.", c: ["so", "very", "such", "much"], a: 2, t: "T24", d: 1000, why: "後ろが「形容詞 + 名詞 advice」.名詞があるので such(advice は数えられないので a は付かない).", ja: "小野さんがとても役立つ助言をくれたので,早く終わった." },
  { id: "g257", q: "There was ____ little time left that we had to cancel the tour.", c: ["such", "so", "too", "very"], a: 1, t: "T24", d: 1200, why: "名詞 time があるが,量を表す little が付いているので so(so little time).many / much / few / little は so と組む.", ja: "時間がほとんど残っていなかったので,見学を中止しなければならなかった." },
  { id: "g258", q: "The delay was ____ that many passengers missed their connections.", c: ["such", "so", "too", "very"], a: 0, t: "T24", d: 1400, why: "空所の後ろに形容詞も副詞もなく,すぐ that 節が続く.such that で「(程度が)それほどのものだったので」.so は後ろに形容詞・副詞が必要.", ja: "遅れはひどく,多くの乗客が乗り継ぎに間に合わなかった." },

  // T25
  { id: "g259", q: "The hotel was fully booked; ____, we had to stay at another one.", c: ["because", "therefore", "although", "so that"], a: 1, t: "T25", d: 900, why: "セミコロンの後ろでカンマが続くので,接続副詞 therefore(したがって).because / although は接続詞で,後ろにカンマを置かない.", ja: "ホテルは満室だった.そのため,別のホテルに泊まらなければならなかった." },
  { id: "g260", q: "Mr. Lee has little experience. ____, he is a fast learner.", c: ["Although", "Despite", "Because", "However"], a: 3, t: "T25", d: 800, why: "ピリオドの後ろでカンマが続くので,接続副詞 however(しかし).although は節を2つつなぐ接続詞で,1つの文だけでは使えない.", ja: "リーさんは経験がほとんどない.しかし,飲み込みが早い." },
  { id: "g261", q: "The restaurant is small, ____ it is always crowded.", c: ["however", "therefore", "but", "nevertheless"], a: 2, t: "T25", d: 900, why: "カンマだけで2つの節をつなげるのは接続詞 but.however / nevertheless は副詞なので,カンマで節をつなげない.", ja: "そのレストランは小さいが,いつも混んでいる." },
  { id: "g262", q: "Our costs have risen. ____, we must raise our prices.", c: ["Therefore", "Although", "Because", "Despite"], a: 0, t: "T25", d: 700, why: "ピリオドの後ろでカンマが続く接続副詞.前の文が原因,後ろが結果なので therefore.", ja: "経費が上がった.したがって,値上げをしなければならない." },
  { id: "g263", q: "The new printer is faster. ____, it uses less ink.", c: ["Although", "Moreover", "Because", "Whereas"], a: 1, t: "T25", d: 1000, why: "ピリオドの後ろでカンマが続く接続副詞.良い点を付け足しているので moreover(そのうえ).", ja: "新しいプリンターは速い.そのうえ,インクの消費も少ない." },
  { id: "g264", q: "Please arrive early; ____, you may not find a seat.", c: ["otherwise", "although", "unless", "because"], a: 0, t: "T25", d: 1200, why: "セミコロンの後ろでカンマが続くので接続副詞.otherwise(そうしないと)が入る.unless は意味が近いが接続詞で,この位置には置けない.", ja: "早めに来てください.そうしないと,席が見つからないかもしれません." },
  { id: "g265", q: "____ the product is expensive, many customers buy it.", c: ["However", "Nevertheless", "Although", "Despite"], a: 2, t: "T25", d: 1000, why: "カンマで2つの節をつないでいるので接続詞が必要.although(〜だけれども).however / nevertheless は副詞,despite は前置詞.", ja: "その製品は高価だが,多くの客が買っている." },

  // T26
  { id: "g266", q: "The picnic will be held on Saturday ____ it rains.", c: ["if", "unless", "because", "so"], a: 1, t: "T26", d: 700, why: "「雨が降らない限り,行われる」.unless = if not.", ja: "雨が降らない限り,ピクニックは土曜日に行われる." },
  { id: "g267", q: "____ you have a membership card, you cannot enter the gym.", c: ["Unless", "If", "As long as", "In case"], a: 0, t: "T26", d: 800, why: "「会員証を持っていない限り,入れない」.unless = if not.If や As long as では意味が逆になる.", ja: "会員証を持っていない限り,ジムには入れない." },
  { id: "g268", q: "You can borrow my laptop ____ you return it by five.", c: ["unless", "as long as", "in case", "whether"], a: 1, t: "T26", d: 800, why: "「5時までに返すという条件で」なので as long as.", ja: "5時までに返してくれるなら,私のノートパソコンを借りてよい." },
  { id: "g269", q: "Take a spare battery ____ the first one runs out.", c: ["unless", "as long as", "in case", "so that"], a: 2, t: "T26", d: 900, why: "「1つ目が切れる場合に備えて」なので in case.", ja: "1つ目が切れる場合に備えて,予備の電池を持っていきなさい." },
  { id: "g270", q: "Employees may work from home ____ their manager approves.", c: ["unless", "in case", "although", "provided that"], a: 3, t: "T26", d: 1100, why: "「上司が承認するという条件で」なので provided that(= if / as long as).", ja: "従業員は,上司が承認すれば在宅で働ける." },
  { id: "g271", q: "____ we receive your payment by Friday, your order will be shipped on Monday.", c: ["Provided", "Unless", "In case", "Whereas"], a: 0, t: "T26", d: 1300, why: "「金曜日までに支払いを受け取るという条件で」.provided (that) の that は省略できる.文頭の Provided を過去分詞と見まちがえないこと.", ja: "金曜日までにお支払いを受け取れば,ご注文は月曜日に発送します." },
  { id: "g272", q: "We will not process your application ____ all the documents are submitted.", c: ["in case", "provided that", "unless", "as if"], a: 2, t: "T26", d: 1000, why: "「すべての書類が提出されない限り,処理しない」.主節が否定で「〜しない限り」なので unless.", ja: "すべての書類が提出されない限り,申請は処理しない." },

  // T27
  { id: "g273", q: "The fee is subject ____ change without notice.", c: ["for", "with", "to", "of"], a: 2, t: "T27", d: 1000, why: "be subject to 〜 で「〜されることがある・〜の対象となる」.この to は前置詞で,後ろは名詞(change).", ja: "料金は予告なく変更されることがある." },
  { id: "g274", q: "Ms. Hara specializes ____ tax law.", c: ["on", "in", "at", "for"], a: 1, t: "T27", d: 800, why: "specialize in 〜 で「〜を専門にする」.", ja: "原さんは税法を専門にしている." },
  { id: "g275", q: "Full-time employees are eligible ____ paid vacation.", c: ["to", "of", "with", "for"], a: 3, t: "T27", d: 900, why: "be eligible for 〜 で「〜を受ける資格がある」.", ja: "正社員は有給休暇を取る資格がある." },
  { id: "g276", q: "The success of the event depends ____ the weather.", c: ["on", "to", "for", "with"], a: 0, t: "T27", d: 500, why: "depend on 〜 で「〜次第である・〜に頼る」.", ja: "催しの成功は天気次第だ." },
  { id: "g277", q: "Please refrain ____ using mobile phones in the theater.", c: ["of", "from", "to", "at"], a: 1, t: "T27", d: 1100, why: "refrain from -ing で「〜するのを控える」.掲示や案内でよく使われる.", ja: "劇場内では携帯電話の使用をお控えください." },
  { id: "g278", q: "Our new office is equipped ____ the latest technology.", c: ["by", "in", "with", "to"], a: 2, t: "T27", d: 900, why: "be equipped with 〜 で「〜を備えている」.", ja: "新しい事務所は最新の技術を備えている." },

  // T28
  { id: "g279", q: "By next March, Ms. Ito ____ here for twenty years.", c: ["works", "worked", "will have worked", "has worked"], a: 2, t: "T28", d: 1100, why: "By next March(来年3月には)は未来の時点.その時点までの継続なので未来完了 will have worked.", ja: "来年3月で,伊藤さんはここで20年働いたことになる." },
  { id: "g280", q: "The meeting ____ by the time I got to the office.", c: ["had already started", "starts", "has already started", "will have started"], a: 0, t: "T28", d: 900, why: "事務所に着いた(過去)時点より前に始まっていたので過去完了 had started.", ja: "事務所に着いたときには,会議はもう始まっていた." },
  { id: "g281", q: "By the time you receive this letter, I ____ the country.", c: ["left", "had left", "leaving", "will have left"], a: 3, t: "T28", d: 1200, why: "by the time 節が現在形 receive(時の副詞節で未来を表す)なので,基準は未来の時点.その時までに完了していることは未来完了 will have left.", ja: "あなたがこの手紙を受け取るころには,私は国を出ているだろう." },
  { id: "g282", q: "Mr. Cho realized that he ____ his passport at home.", c: ["leaves", "has left", "had left", "will leave"], a: 2, t: "T28", d: 900, why: "気づいた(過去)時点より前に置き忘れていたので過去完了 had left.", ja: "チョさんはパスポートを家に置き忘れたことに気づいた." },
  { id: "g283", q: "The store ____ out of the item before the sale even began.", c: ["sells", "has sold", "will have sold", "had sold"], a: 3, t: "T28", d: 1100, why: "セールが始まった(過去)時点より前に売り切れていたので過去完了 had sold.", ja: "その店では,セールが始まる前にその商品が売り切れていた." },
  { id: "g284", q: "By the end of this month, the team ____ the first phase of the project.", c: ["completed", "will have completed", "had completed", "completing"], a: 1, t: "T28", d: 1100, why: "By the end of this month(今月末までに)は未来の期限.それまでに完了することは未来完了 will have completed.", ja: "今月末までに,チームは計画の第1段階を終えているだろう." },
  { id: "g285", q: "Before joining our firm, Mr. Park ____ for a bank for ten years.", c: ["works", "has worked", "had worked", "will have worked"], a: 2, t: "T28", d: 1000, why: "当社に入った(過去)時点より前の10年間のことなので過去完了 had worked.今につながっていないので現在完了は使えない.", ja: "当社に入る前,パークさんは10年間銀行に勤めていた." },

  // T29
  { id: "g286", q: "The manager made the staff ____ the report again.", c: ["to write", "write", "writing", "written"], a: 1, t: "T29", d: 900, why: "make + 人 + 動詞の原形 で「人に(強制的に)〜させる」.to は付けない.", ja: "部長はスタッフに報告書をもう一度書かせた." },
  { id: "g287", q: "We had the office ____ last weekend.", c: ["paint", "painting", "to paint", "painted"], a: 3, t: "T29", d: 1000, why: "have + 物 + 過去分詞 で「物を〜してもらう」.office は「塗られる」側なので painted.", ja: "先週末,事務所を塗装してもらった." },
  { id: "g288", q: "Please have the technician ____ the printer.", c: ["check", "to check", "checked", "checking"], a: 0, t: "T29", d: 1000, why: "have + 人 + 動詞の原形 で「人に〜してもらう」.technician は「点検する」側なので原形 check.", ja: "技術者にプリンターを点検してもらってください." },
  { id: "g289", q: "Ms. Lee let her assistant ____ early on Friday.", c: ["leaves", "to leave", "leave", "leaving"], a: 2, t: "T29", d: 700, why: "let + 人 + 動詞の原形 で「人が〜するのを許す」.", ja: "リーさんは金曜日,助手を早く帰らせてあげた." },
  { id: "g290", q: "I will get my assistant ____ you the file.", c: ["send", "to send", "sent", "sending"], a: 1, t: "T29", d: 1300, why: "get は have と同じ「〜してもらう」の意味だが,get + 人 + to do と to が必要.have / make / let は原形,get は to do.", ja: "助手にそのファイルをあなたへ送らせます." },
  { id: "g291", q: "Mr. Ono had his passport ____ before the trip.", c: ["renew", "to renew", "renewing", "renewed"], a: 3, t: "T29", d: 1100, why: "have + 物 + 過去分詞.passport は「更新される」側なので renewed.", ja: "小野さんは出張の前にパスポートを更新してもらった." },
  { id: "g292", q: "The new software helps employees ____ their time more effectively.", c: ["managing", "managed", "manage", "management"], a: 2, t: "T29", d: 900, why: "help + 人 + (to) 動詞の原形 で「人が〜するのを助ける」.to はあってもなくてもよい.", ja: "新しいソフトは,従業員が時間をより効果的に管理するのに役立つ." },

  // T30
  { id: "g293", q: "The city ____ I was born has changed a lot.", c: ["which", "where", "what", "who"], a: 1, t: "T30", d: 800, why: "空所の後ろ I was born は完全な文(欠けている要素がない).場所を表す関係副詞 where.", ja: "私が生まれた街は大きく変わった." },
  { id: "g294", q: "The restaurant ____ we visited last night was excellent.", c: ["where", "which", "what", "when"], a: 1, t: "T30", d: 1000, why: "visit は他動詞で,後ろの目的語が欠けている.先行詞が場所でも,欠けた目的語を補うのは関係代名詞 which.先行詞ではなく,後ろの文が完全かどうかで決める.", ja: "昨夜訪れたレストランはすばらしかった." },
  { id: "g295", q: "This is the room ____ we keep the old files.", c: ["which", "what", "where", "whose"], a: 2, t: "T30", d: 900, why: "空所の後ろ we keep the old files は主語も目的語もそろった完全な文.場所を表す関係副詞 where.", ja: "ここが古いファイルを保管している部屋だ." },
  { id: "g296", q: "The building ____ was built in 1920 is now a museum.", c: ["which", "where", "what", "when"], a: 0, t: "T30", d: 800, why: "空所の後ろ was built は主語が欠けている.欠けた主語を補う関係代名詞 which.", ja: "1920年に建てられたその建物は,今は博物館になっている." },
  { id: "g297", q: "We toured the factory in ____ the engines are assembled.", c: ["where", "that", "which", "what"], a: 2, t: "T30", d: 1300, why: "前置詞 in の直後に置けるのは which だけ.in which = where.where には前置詞の意味が含まれているので,in where とは言わない.", ja: "私たちは,エンジンが組み立てられている工場を見学した." },
  { id: "g298", q: "The day ____ we signed the contract was a Friday.", c: ["which", "where", "what", "when"], a: 3, t: "T30", d: 1000, why: "空所の後ろ we signed the contract は完全な文.先行詞が時(the day)なので関係副詞 when.場所なら where,時なら when.", ja: "契約に署名した日は金曜日だった." },
  { id: "g299", q: "The office ____ Mr. Kim works in is on the third floor.", c: ["where", "which", "when", "what"], a: 1, t: "T30", d: 1400, why: "後ろの文は works in で終わり,前置詞 in の目的語が欠けている.欠けた名詞を補うのは関係代名詞 which.where を入れると in が余る.", ja: "キムさんが働いている事務所は3階にある." },
  { id: "g300", q: "There are several situations ____ this rule does not apply.", c: ["which", "what", "where", "who"], a: 2, t: "T30", d: 1400, why: "空所の後ろ this rule does not apply は完全な文.situation, case, point など,実際の場所でない「場面・状況」にも where を使う.", ja: "この規則が当てはまらない状況がいくつかある." },

  // ---- 新しい定理 T31〜T40(g301〜) ----
  // T31
  { id: "g301", q: "Ms. Hill arrived early ____ prepare the meeting room.", c: ["to", "for", "so that", "because"], a: 0, t: "T31", d: 600, why: "後ろが動詞の原形 prepare なので,目的を表す to.so that の後ろは節(主語 + 動詞),for の後ろは名詞.", ja: "ヒルさんは会議室の準備をするために早く着いた." },
  { id: "g302", q: "Please speak clearly so that everyone ____ hear you.", c: ["in order", "to", "for", "can"], a: 3, t: "T31", d: 700, why: "so that + 主語 + can + 原形 で「〜できるように」.", ja: "全員に聞こえるように,はっきり話してください." },
  { id: "g303", q: "The store extended its hours ____ attract more customers.", c: ["so that", "in order to", "for", "because of"], a: 1, t: "T31", d: 800, why: "後ろが動詞の原形 attract なので in order to.so that の後ろには主語が必要.", ja: "その店はより多くの客を呼ぶために営業時間を延ばした." },
  { id: "g304", q: "We use this knife ____ cutting bread.", c: ["to", "in order to", "for", "so that"], a: 2, t: "T31", d: 900, why: "後ろが -ing(cutting)で,物の用途を表すので for.to / in order to の後ろは原形.", ja: "このナイフはパンを切るのに使う." },
  { id: "g305", q: "The manager sent a reminder ____ no one would forget the deadline.", c: ["so that", "to", "in order to", "for"], a: 0, t: "T31", d: 1000, why: "後ろが節(no one would forget)なので so that.過去の文では so that + 主語 + would / could.", ja: "部長は,だれも締め切りを忘れないよう催促を送った." },
  { id: "g306", q: "Mr. Kim went to the bank ____ open an account.", c: ["with", "for", "by", "to"], a: 3, t: "T31", d: 500, why: "「口座を開くために」.後ろが原形 open なので目的の to.", ja: "キムさんは口座を開くために銀行へ行った." },
  { id: "g307", q: "____ to reduce costs, the company moved to a smaller office.", c: ["So that", "In order", "For", "Because"], a: 1, t: "T31", d: 1100, why: "文頭の In order to do で「〜するために」.to の前に置けるのは in order.", ja: "費用を減らすため,その会社はより狭い事務所に移った." },
  { id: "g308", q: "Please arrive ten minutes early so as ____ the start of the tour.", c: ["not miss", "to not missing", "not to miss", "not missing"], a: 2, t: "T31", d: 1200, why: "so as to do も「〜するために」.否定は so as not to do(not の位置は to の前).in order not to も同じ.", ja: "ツアーの開始に遅れないよう,10分前に来てください." },
  { id: "g309", q: "The city built a new road ____ traffic would move more smoothly.", c: ["so that", "in order to", "for", "to"], a: 0, t: "T31", d: 900, why: "後ろが節(traffic would move)なので so that.", ja: "交通がもっと円滑に流れるよう,市は新しい道路を造った." },
  { id: "g310", q: "She saved money ____ a new car.", c: ["to", "so that", "in order to", "for"], a: 3, t: "T31", d: 700, why: "後ろが名詞 a new car なので for(〜のために).to buy a new car なら to を使う.", ja: "彼女は新しい車のためにお金をためた." },

  // T32
  { id: "g311", q: "The meeting will start ____ 3:00 P.M.", c: ["in", "at", "on", "by"], a: 1, t: "T32", d: 300, why: "時刻には at.", ja: "会議は午後3時に始まる." },
  { id: "g312", q: "The store is closed ____ Sundays.", c: ["in", "at", "on", "for"], a: 2, t: "T32", d: 400, why: "曜日には on.", ja: "その店は日曜日は休みだ." },
  { id: "g313", q: "Our company was founded ____ 1998.", c: ["in", "on", "at", "for"], a: 0, t: "T32", d: 400, why: "年には in.", ja: "当社は1998年に創業した." },
  { id: "g314", q: "The new product will be released ____ May 10.", c: ["in", "at", "for", "on"], a: 3, t: "T32", d: 600, why: "日付には on(月だけなら in May,日付まであれば on).", ja: "新製品は5月10日に発売される." },
  { id: "g315", q: "Please return the form ____ seven days of receiving it.", c: ["during", "within", "since", "until"], a: 1, t: "T32", d: 700, why: "「受け取ってから7日以内に」なので within.", ja: "受け取ってから7日以内に用紙を返送してください." },
  { id: "g316", q: "The museum is open to visitors ____ the year.", c: ["within", "since", "throughout", "by"], a: 2, t: "T32", d: 800, why: "「1年を通してずっと」なので throughout.", ja: "その博物館は1年中来館者を受け入れている." },
  { id: "g317", q: "The repair technician will arrive ____ an hour.", c: ["in", "on", "at", "since"], a: 0, t: "T32", d: 900, why: "in + 期間 で「(今から)〜後に」.「1時間以内に」なら within.", ja: "修理の技術者は1時間後に到着する." },
  { id: "g318", q: "The sale ends ____ midnight on Friday.", c: ["in", "on", "during", "at"], a: 3, t: "T32", d: 1000, why: "midnight, noon, night などの時点には at.", ja: "セールは金曜日の夜12時に終わる." },
  { id: "g319", q: "Sales usually increase ____ the holiday season.", c: ["at", "during", "while", "since"], a: 1, t: "T32", d: 1100, why: "後ろが名詞 the holiday season で,「その期間中に」なので during.while は接続詞なので後ろに節が必要.", ja: "売上はふつう休暇の時期に増える." },
  { id: "g320", q: "The workshop will be held ____ the morning of June 5.", c: ["in", "at", "on", "by"], a: 2, t: "T32", d: 1200, why: "in the morning は「午前中に」だが,特定の日の午前(the morning of June 5)には on を使う.", ja: "講習会は6月5日の午前に開かれる." },

  // T33
  { id: "g321", q: "We need to discuss ____ before Friday.", c: ["the budget", "about the budget", "on the budget", "for the budget"], a: 0, t: "T33", d: 600, why: "discuss は他動詞なので,前置詞なしで目的語をとる.discuss about とは言わない.", ja: "金曜日までに予算について話し合う必要がある." },
  { id: "g322", q: "Please reply ____ this e-mail by tomorrow.", c: ["for", "at", "on", "to"], a: 3, t: "T33", d: 500, why: "reply は自動詞.「〜に返信する」は reply to.", ja: "明日までにこのメールに返信してください." },
  { id: "g323", q: "All employees are required to attend ____ the safety meeting.", c: ["to", "(何も入らない)", "in", "at"], a: 1, t: "T33", d: 700, why: "attend(出席する)は他動詞なので,前置詞を置かずに attend the meeting.", ja: "全従業員は安全会議に出席しなければならない." },
  { id: "g324", q: "The company will ____ its prices next month.", c: ["rise", "arise", "raise", "rising"], a: 2, t: "T33", d: 800, why: "its prices(目的語)があるので他動詞 raise(〜を上げる).rise は自動詞(上がる).", ja: "その会社は来月値上げをする." },
  { id: "g325", q: "The number of visitors has ____ steadily.", c: ["risen", "raised", "raising", "raise"], a: 0, t: "T33", d: 800, why: "後ろに目的語がないので自動詞 rise(上がる)の過去分詞 risen.", ja: "来場者の数は着実に増えている." },
  { id: "g326", q: "Our train will arrive ____ the station at noon.", c: ["to", "(何も入らない)", "on", "at"], a: 3, t: "T33", d: 600, why: "arrive は自動詞.地点には arrive at,都市・国には arrive in.", ja: "電車は正午に駅に着く." },
  { id: "g327", q: "You can contact ____ by phone or e-mail.", c: ["to us", "us", "with us", "for us"], a: 1, t: "T33", d: 900, why: "contact(連絡する)は他動詞なので contact us.", ja: "電話かメールで私たちに連絡できる." },
  { id: "g328", q: "The shipment is expected to reach ____ on Monday.", c: ["to Tokyo", "at Tokyo", "Tokyo", "in Tokyo"], a: 2, t: "T33", d: 1000, why: "reach(到着する)は他動詞なので前置詞なし.arrive in Tokyo と同じ意味.", ja: "荷物は月曜日に東京に着く予定だ." },
  { id: "g329", q: "Please ____ the documents on my desk when you are finished.", c: ["lay", "lie", "lying", "lain"], a: 0, t: "T33", d: 1300, why: "the documents(目的語)があるので他動詞 lay(〜を置く).lie は自動詞(横たわる・ある)で,過去形は lay なので紛らわしい.", ja: "終わったら書類を私の机に置いてください." },
  { id: "g330", q: "Please enter ____ the building through the side door.", c: ["into", "to", "in", "(何も入らない)"], a: 3, t: "T33", d: 1200, why: "enter(入る)は他動詞なので,前置詞を置かずに enter the building.enter into は「(契約などを)結ぶ」という別の意味.", ja: "建物には横の扉から入ってください." },

  // T34
  { id: "g331", q: "Mr. Ito ____ the company three years ago.", c: ["joins", "joined", "has joined", "will join"], a: 1, t: "T34", d: 400, why: "ago は過去の時点を表すので過去形 joined.現在完了は ago と使えない.", ja: "伊藤さんは3年前に入社した." },
  { id: "g332", q: "The new store ____ next month.", c: ["opened", "opens", "will open", "has opened"], a: 2, t: "T34", d: 500, why: "next month は未来なので will open.", ja: "新しい店は来月開店する." },
  { id: "g333", q: "Ms. Lee is ____ working on a new project.", c: ["currently", "current", "currency", "currents"], a: 0, t: "T34", d: 500, why: "be と -ing の間なので副詞 currently(現在).進行形と組む語.", ja: "リーさんは今,新しい事業に取り組んでいる." },
  { id: "g334", q: "The bus usually ____ at 8:15.", c: ["leave", "leaving", "is left", "leaves"], a: 3, t: "T34", d: 600, why: "usually(ふつうは)は習慣を表すので現在形.主語が単数なので leaves.", ja: "バスはふつう8時15分に出る." },
  { id: "g335", q: "We ____ the contract yesterday.", c: ["sign", "signed", "have signed", "will sign"], a: 1, t: "T34", d: 700, why: "yesterday は過去なので過去形 signed.", ja: "私たちは昨日,契約に署名した." },
  { id: "g336", q: "At the moment, the manager ____ with a client.", c: ["meets", "met", "is meeting", "has met"], a: 2, t: "T34", d: 800, why: "at the moment(今ちょうど)は進行形の目印.", ja: "部長は今,顧客と会っている." },
  { id: "g337", q: "The results of the survey ____ announced soon.", c: ["will be", "have been", "were", "are being"], a: 0, t: "T34", d: 900, why: "soon(まもなく)は未来なので will be announced.", ja: "調査結果はまもなく発表される." },
  { id: "g338", q: "In 2020, the firm ____ its first overseas office.", c: ["opens", "had been opening", "has opened", "opened"], a: 3, t: "T34", d: 1000, why: "In 2020 は過去の年なので過去形 opened.", ja: "2020年,その会社は初の海外事務所を開いた." },
  { id: "g339", q: "Every Friday, the team ____ a short meeting to review the week.", c: ["held", "holds", "is holding", "will have held"], a: 1, t: "T34", d: 1100, why: "Every Friday(毎週金曜日)は習慣なので現在形 holds.", ja: "毎週金曜日,チームは1週間を振り返る短い会議を開く." },
  { id: "g340", q: "The CEO ____ to Paris tomorrow morning for the trade show.", c: ["flew", "has flown", "is flying", "had been flying"], a: 2, t: "T34", d: 1300, why: "tomorrow があり,すでに決まっている予定は現在進行形でも表せる(is flying).過去形・完了形は tomorrow と合わない.", ja: "CEO は明朝,見本市のためにパリへ飛ぶ." },

  // T35
  { id: "g341", q: "Please let me know ____ you can attend the meeting.", c: ["whether", "what", "that", "which"], a: 0, t: "T35", d: 600, why: "「出席できるかどうか」なので whether.", ja: "会議に出席できるかどうか知らせてください." },
  { id: "g342", q: "I am not sure ____ the train leaves.", c: ["time what", "what time does", "what does time", "what time"], a: 3, t: "T35", d: 700, why: "間接疑問では,疑問詞の後ろは「主語 + 動詞」の順.what time the train leaves(does は使わない).", ja: "電車が何時に出るのか分からない." },
  { id: "g343", q: "The manager explained ____ the system works.", c: ["what", "how", "that", "whether"], a: 1, t: "T35", d: 800, why: "後ろの the system works は完全な文.「どのように動くか」なので how.what は後ろに欠けた要素が必要.", ja: "部長はそのシステムがどう動くかを説明した." },
  { id: "g344", q: "We were told ____ the office would be closed on Monday.", c: ["what", "whether", "that", "which"], a: 2, t: "T35", d: 800, why: "後ろが完全な文で,「〜ということ」を伝えているので that.", ja: "月曜日は事務所が休みだと言われた." },
  { id: "g345", q: "Do you know where ____?", c: ["the station is", "is the station", "does the station", "the station"], a: 0, t: "T35", d: 900, why: "間接疑問(Do you know の目的語)では,疑問詞の後ろは「主語 + 動詞」の順.where the station is.", ja: "駅がどこにあるか知っていますか." },
  { id: "g346", q: "____ the event will be held outdoors depends on the weather.", c: ["If", "That", "What", "Whether"], a: 3, t: "T35", d: 1000, why: "文頭で主語になる「〜かどうか」は whether.if は主語の位置では使えない.", ja: "催しを屋外で行うかどうかは天気次第だ." },
  { id: "g347", q: "The decision depends on ____ the client approves the budget.", c: ["if", "whether", "that", "what"], a: 1, t: "T35", d: 1100, why: "前置詞 on の後ろなので whether(if は前置詞の後ろに置けない).", ja: "決定は顧客が予算を承認するかどうかにかかっている." },
  { id: "g348", q: "Please tell us ____ or not you will need a hotel room.", c: ["if", "that", "whether", "what"], a: 2, t: "T35", d: 1100, why: "直後に or not を置けるのは whether.", ja: "ホテルの部屋が必要かどうか教えてください." },
  { id: "g349", q: "No one knows ____ caused the system failure.", c: ["what", "that", "whether", "how"], a: 0, t: "T35", d: 1200, why: "caused の主語が欠けているので what(何が〜したか).how / whether / that の後ろは完全な文.", ja: "何がシステムの障害を引き起こしたのか,だれも分からない." },
  { id: "g350", q: "The fact ____ sales have declined is worrying.", c: ["which", "what", "whether", "that"], a: 3, t: "T35", d: 1400, why: "the fact that + 完全な文 で「〜という事実」(同格の that).後ろは完全な文なので,関係代名詞の which / what は入らない.", ja: "売上が減っているという事実は心配だ." },

  // T36
  { id: "g351", q: "Would you like ____ cup of coffee?", c: ["other", "another", "others", "the others"], a: 1, t: "T36", d: 500, why: "後ろが単数名詞 cup で「もう1杯」なので another.", ja: "コーヒーをもう1杯いかがですか." },
  { id: "g352", q: "Some employees walk to work, while ____ take the bus.", c: ["another", "the other", "others", "other"], a: 2, t: "T36", d: 600, why: "後ろに名詞がなく「ほかの人たち」なので others.other は後ろに名詞が必要.", ja: "歩いて通勤する社員もいれば,バスに乗る社員もいる." },
  { id: "g353", q: "We have two offices; one is in Osaka, and ____ is in Tokyo.", c: ["the other", "other", "others", "another"], a: 0, t: "T36", d: 700, why: "2つのうちの残りの1つは the other.", ja: "事務所は2つあり,1つは大阪,もう1つは東京にある." },
  { id: "g354", q: "Please contact us if you have any ____ questions.", c: ["another", "the other", "others", "other"], a: 3, t: "T36", d: 700, why: "後ろが複数名詞 questions なので other.another は単数名詞と使う.", ja: "ほかにご質問があればご連絡ください." },
  { id: "g355", q: "The team members help each ____ when they are busy.", c: ["another", "other", "others", "one"], a: 1, t: "T36", d: 800, why: "each other で「お互い」.", ja: "チームの仲間は忙しいときにお互いに助け合う." },
  { id: "g356", q: "Only three people came; ____ were on vacation.", c: ["another", "others", "the others", "other"], a: 2, t: "T36", d: 900, why: "決まった人数の中の「残りの全員」なので the others.", ja: "3人しか来なかった.残りは全員休暇中だった." },
  { id: "g357", q: "The flight was canceled, so we had to book ____ one.", c: ["another", "others", "other", "the others"], a: 0, t: "T36", d: 1000, why: "one(= flight)は単数.「別の1便」なので another.", ja: "便が欠航したので,別の便を予約しなければならなかった." },
  { id: "g358", q: "Mr. Sato visits the factory every ____ week.", c: ["another", "the other", "others", "other"], a: 3, t: "T36", d: 1000, why: "every other + 単数名詞 で「1つおきに」.every other week は「隔週で」.", ja: "佐藤さんは隔週で工場を訪れる." },
  { id: "g359", q: "One of the printers works, but ____ two are broken.", c: ["another", "the other", "others", "other"], a: 1, t: "T36", d: 1100, why: "3台のうち1台を除いた残りの2台なので the other two.the があるので残りが決まる.", ja: "プリンターの1台は動くが,残りの2台は壊れている." },
  { id: "g360", q: "In ____ words, the project will be delayed by a month.", c: ["the other", "another", "other", "others"], a: 2, t: "T36", d: 1300, why: "in other words で「言い換えれば」.決まった言い方.", ja: "言い換えれば,事業は1か月遅れるということだ." },

  // T37
  { id: "g361", q: "Sales rose in Asia, ____ they fell in Europe.", c: ["whereas", "despite", "because", "so"], a: 0, t: "T37", d: 700, why: "アジアでは増え,ヨーロッパでは減ったという対比なので whereas(一方で).", ja: "アジアでは売上が伸びたが,一方でヨーロッパでは減った." },
  { id: "g362", q: "____ the restaurant is small, it is very popular.", c: ["Even if", "Despite", "However", "Even though"], a: 3, t: "T37", d: 800, why: "「小さい」は事実なので even though(〜だけれども).even if は「たとえ〜でも」という仮定.", ja: "そのレストランは小さいが,とても人気がある." },
  { id: "g363", q: "The event will take place ____ it rains.", c: ["even though", "even if", "whereas", "despite"], a: 1, t: "T37", d: 800, why: "雨が降るかどうかは分からないので,仮定の even if(たとえ〜でも).", ja: "たとえ雨が降っても,催しは行われる." },
  { id: "g364", q: "Some staff prefer working at home, ____ others prefer the office.", c: ["despite", "during", "while", "so"], a: 2, t: "T37", d: 900, why: "2つのグループの対比なので while(一方で).during は前置詞なので後ろに節は置けない.", ja: "在宅勤務を好むスタッフもいれば,一方で事務所を好むスタッフもいる." },
  { id: "g365", q: "____ you are late, please call the office.", c: ["In case", "Even though", "Whereas", "Despite"], a: 0, t: "T37", d: 1000, why: "「遅れる場合には」なので in case.対比や譲歩の意味ではない.", ja: "遅れる場合は事務所に電話してください." },
  { id: "g366", q: "The first model is cheap, ____ the second one is more reliable.", c: ["despite", "although of", "in spite", "whereas"], a: 3, t: "T37", d: 1000, why: "2つの機種の対比なので whereas.in spite と despite は前置詞で,後ろに節を置けない.", ja: "1つ目の機種は安く,一方で2つ目の機種はより信頼性が高い." },
  { id: "g367", q: "____ he had little experience, Mr. Ono was hired.", c: ["Despite", "Even though", "Even", "Nevertheless"], a: 1, t: "T37", d: 1100, why: "後ろが節(he had little experience)で,事実を認めているので even though.despite は前置詞,nevertheless は副詞.", ja: "経験が少なかったにもかかわらず,小野さんは採用された." },
  { id: "g368", q: "____ the price increases, we will continue to buy from this supplier.", c: ["Even though", "Whereas", "Even if", "Despite"], a: 2, t: "T37", d: 1200, why: "値上がりするかどうかはまだ分からないので,仮定の even if.", ja: "たとえ値上がりしても,この仕入先から買い続ける." },
  { id: "g369", q: "____ the first half of the year was difficult, the second half was very successful.", c: ["Whereas", "Because", "Despite", "Unless"], a: 0, t: "T37", d: 1300, why: "前半と後半の対比なので whereas.despite は前置詞で,後ろに節は置けない.", ja: "上半期は苦しかったが,一方で下半期はとても好調だった." },
  { id: "g370", q: "The proposal was rejected, ____ it had strong support from the staff.", c: ["even if", "whereas", "so that", "even though"], a: 3, t: "T37", d: 1400, why: "スタッフの強い支持は「あった」事実なので even though(〜だったのに).even if は仮定.", ja: "スタッフから強い支持があったのに,その提案は却下された." },

  // T38
  { id: "g371", q: "____ the weather report, it will rain tomorrow.", c: ["Instead of", "According to", "Because", "In addition"], a: 1, t: "T38", d: 600, why: "「天気予報によると」なので according to.", ja: "天気予報によると,明日は雨が降る." },
  { id: "g372", q: "____ the usual menu, the café offers seasonal dishes.", c: ["Instead", "According", "In addition to", "Because"], a: 2, t: "T38", d: 700, why: "「通常のメニューに加えて」なので in addition to.後ろは名詞.", ja: "通常のメニューに加えて,そのカフェは季節の料理を出している." },
  { id: "g373", q: "Ms. Ito took the train ____ driving.", c: ["instead of", "in spite", "according to", "on behalf"], a: 0, t: "T38", d: 700, why: "「車で行く代わりに」なので instead of.後ろは -ing.", ja: "伊藤さんは車ではなく電車で行った." },
  { id: "g374", q: "Mr. Park accepted the award ____ the entire team.", c: ["instead", "because", "in addition", "on behalf of"], a: 3, t: "T38", d: 900, why: "「チーム全体を代表して」なので on behalf of.", ja: "パークさんはチーム全体を代表して賞を受け取った." },
  { id: "g375", q: "All employees must attend the training, ____ their position.", c: ["according to", "regardless of", "instead of", "because"], a: 1, t: "T38", d: 1000, why: "「役職に関係なく」なので regardless of.", ja: "全従業員は,役職に関係なく研修に出席しなければならない." },
  { id: "g376", q: "____ April 1, the new prices will apply.", c: ["Because of", "Instead of", "As of", "Regardless of"], a: 2, t: "T38", d: 1100, why: "as of + 日付 で「〜から・〜時点で」.", ja: "4月1日から,新しい価格が適用される." },
  { id: "g377", q: "The game was canceled ____ the heavy snow.", c: ["because of", "because", "according", "instead"], a: 0, t: "T38", d: 1000, why: "後ろが名詞 the heavy snow なので because of.because は接続詞で後ろに節が必要.", ja: "大雪のため試合は中止された." },
  { id: "g378", q: "The team finished on time ____ the shortage of staff.", c: ["instead", "because", "even though", "in spite of"], a: 3, t: "T38", d: 1200, why: "「人手不足にもかかわらず」.後ろが名詞なので in spite of(= despite).even though は接続詞.", ja: "人手不足にもかかわらず,チームは期限どおりに終えた." },
  { id: "g379", q: "The report was rewritten ____ the client's feedback.", c: ["in terms", "in response to", "responding", "respond to"], a: 1, t: "T38", d: 1300, why: "in response to 〜 で「〜に応えて」.後ろは名詞.", ja: "報告書は顧客の意見に応えて書き直された." },
  { id: "g380", q: "____ cost, the second option is better than the first.", c: ["On behalf of", "Instead of", "In terms of", "As of"], a: 2, t: "T38", d: 1400, why: "in terms of 〜 で「〜の点では」.", ja: "費用の点では,2つ目の案の方が1つ目より良い." },

  // T39
  { id: "g381", q: "Please inform ____ of any changes to the schedule.", c: ["us", "to us", "for us", "with us"], a: 0, t: "T39", d: 800, why: "inform + 人 + of 〜 で「人に〜を知らせる」.人の前に前置詞は付けない.", ja: "予定の変更があればお知らせください." },
  { id: "g382", q: "The manager explained ____ the new rules.", c: ["us", "us to", "for us", "to us"], a: 3, t: "T39", d: 900, why: "explain は「explain + 内容 + to 人」か「explain to 人 + 内容」.explain us とは言わない.", ja: "部長は私たちに新しい規則を説明した." },
  { id: "g383", q: "This e-mail is to remind you ____ tomorrow's meeting.", c: ["to", "about", "for", "with"], a: 1, t: "T39", d: 900, why: "remind + 人 + of / about 〜 で「人に〜を思い出させる」.", ja: "このメールは明日の会議をお知らせするためのものです." },
  { id: "g384", q: "Mr. Kim ____ that the delivery would arrive on time.", c: ["told", "said us", "assured us", "explained us"], a: 2, t: "T39", d: 1000, why: "assure + 人 + that 節 で「人に〜と保証する」.say us,explain us とは言わない.told なら told us that が必要.", ja: "キムさんは,配達は時間どおりに届くと私たちに請け合った." },
  { id: "g385", q: "Ms. Hara ____ me that the meeting had been canceled.", c: ["told", "said", "explained", "mentioned"], a: 0, t: "T39", d: 1000, why: "tell + 人 + that 節.say / explain / mention は人を直接目的語にとらない(say to me that).", ja: "原さんは会議が中止になったと私に言った." },
  { id: "g386", q: "Please notify the front desk ____ you plan to check out late.", c: ["to", "for", "of", "if"], a: 3, t: "T39", d: 1100, why: "notify + 人 + of 名詞 / that 節.ここでは「遅いチェックアウトの予定なら知らせて」という条件なので if.", ja: "遅くチェックアウトする予定なら,フロントに知らせてください." },
  { id: "g387", q: "The guide reminded the tourists ____ their bags on the bus.", c: ["not leaving", "not to leave", "to not leaving", "not leave"], a: 1, t: "T39", d: 1200, why: "remind + 人 + to do で「人に〜するよう念を押す」.否定は not to do.", ja: "ガイドは観光客に,バスにかばんを置き忘れないよう念を押した." },
  { id: "g388", q: "Mr. Lee suggested ____ that we postpone the launch.", c: ["us", "for us", "to us", "with us"], a: 2, t: "T39", d: 1200, why: "suggest は人を直接目的語にとらない.「人に提案する」は suggest to 人 that ….", ja: "リーさんは私たちに発売の延期を提案した." },
  { id: "g389", q: "The bank notified customers ____ the new fees would take effect in May.", c: ["that", "about", "of", "to"], a: 0, t: "T39", d: 1300, why: "後ろが節(the new fees would take effect)なので that.of / about の後ろは名詞.", ja: "銀行は顧客に,新しい手数料が5月から適用されると通知した." },
  { id: "g390", q: "Could you explain ____ how to use the copier?", c: ["me", "me to", "for me", "to me"], a: 3, t: "T39", d: 1400, why: "explain は人を直接目的語にとらない.explain to me how to … の形にする.", ja: "コピー機の使い方を私に説明していただけますか." },

  // T40
  { id: "g391", q: "We are pleased ____ you to our new store.", c: ["welcoming", "to welcome", "welcome", "welcomed"], a: 1, t: "T40", d: 500, why: "be pleased to do で「喜んで〜する」.", ja: "新しい店にお迎えできることをうれしく思います." },
  { id: "g392", q: "Mr. Ono is not able ____ the meeting today.", c: ["attend", "attending", "to attend", "attended"], a: 2, t: "T40", d: 600, why: "be able to do で「〜できる」.", ja: "小野さんは今日の会議に出席できない." },
  { id: "g393", q: "The museum is worth ____.", c: ["visiting", "to visit", "visit", "visited"], a: 0, t: "T40", d: 700, why: "be worth -ing で「〜する価値がある」.", ja: "その博物館は訪れる価値がある." },
  { id: "g394", q: "Sales are likely ____ next year.", c: ["increase", "increased", "increasing", "to increase"], a: 3, t: "T40", d: 700, why: "be likely to do で「〜しそうだ」.", ja: "来年は売上が伸びそうだ." },
  { id: "g395", q: "Thank you for the opportunity ____ with your team.", c: ["work", "to work", "working", "worked"], a: 1, t: "T40", d: 800, why: "opportunity to do で「〜する機会」.名詞の後ろの to do が名詞を説明する.", ja: "御社のチームと働く機会をいただき,ありがとうございます." },
  { id: "g396", q: "The staff were busy ____ for the event.", c: ["prepare", "to prepare", "preparing", "prepared"], a: 2, t: "T40", d: 900, why: "be busy -ing で「〜するのに忙しい」.", ja: "スタッフは催しの準備で忙しかった." },
  { id: "g397", q: "Many customers are reluctant ____ personal information online.", c: ["to share", "sharing", "share", "shared"], a: 0, t: "T40", d: 1000, why: "be reluctant to do で「〜したがらない」.", ja: "多くの客はネットで個人情報を出したがらない." },
  { id: "g398", q: "The company made an effort ____ its waste.", c: ["reducing", "reduce", "reduced", "to reduce"], a: 3, t: "T40", d: 1100, why: "effort to do で「〜しようとする努力」.", ja: "その会社はごみを減らす努力をした." },
  { id: "g399", q: "Employees are eligible ____ for the bonus after one year.", c: ["applying", "to apply", "apply", "applied"], a: 1, t: "T40", d: 1200, why: "be eligible to do で「〜する資格がある」.be eligible for + 名詞 とも言う.", ja: "従業員は1年たつと賞与を申請する資格がある." },
  { id: "g400", q: "The board is eager ____ the project as soon as possible.", c: ["begin", "beginning", "to begin", "for beginning"], a: 2, t: "T40", d: 1300, why: "be eager to do で「しきりに〜したがっている」.", ja: "取締役会はできるだけ早く事業を始めたがっている." },

  // ---- 新しい定理 T41〜T45(g401〜).x は誤答の選択肢ごとの説明 ----
  // T41
  { id: "g401", q: "Never ____ such a successful product launch.", c: ["we have seen", "we saw", "have we seen", "seen we have"], a: 2, t: "T41", d: 1300, why: "文頭に否定語 Never があるので,後ろは疑問文の語順 have we seen.", ja: "これほど成功した製品発表は見たことがない.", x: ["否定語が文頭にあるのに,主語 + 動詞の普通の語順になっている.", "過去形でも,否定語の後は did we see の語順が必要.", "", "語順として成り立たない."] },
  { id: "g402", q: "Rarely ____ the manager leave the office before seven.", c: ["does", "do", "is", "has"], a: 0, t: "T41", d: 1300, why: "Rarely が文頭なので倒置.主語 the manager は3人称単数で,後ろが原形 leave なので does.", ja: "部長が7時前に事務所を出ることはめったにない.", x: ["", "主語が3人称単数なので do ではなく does.", "is の後ろに原形 leave は置けない.", "has の後ろなら過去分詞 left が必要."] },
  { id: "g403", q: "Not only ____ the deadline, but they also reduced costs.", c: ["they met", "met they", "they did meet", "did they meet"], a: 3, t: "T41", d: 1400, why: "文頭の Not only の後ろは倒置.過去の一般動詞なので did + 主語 + 原形.", ja: "彼らは期限を守っただけでなく,費用も減らした.", x: ["Not only が文頭なので普通の語順は使えない.", "一般動詞は主語の前に出せない(did を使う).", "did が主語の後ろにあり,倒置になっていない.", ""] },
  { id: "g404", q: "Only after the contract was signed ____ the work begin.", c: ["was", "did", "has", "does"], a: 1, t: "T41", d: 1400, why: "Only + 副詞句(after 節)が文頭なので倒置.過去の話で後ろが原形 begin なので did.", ja: "契約が結ばれて初めて作業が始まった.", x: ["was の後ろに原形 begin は置けない.", "", "has の後ろなら過去分詞 begun が必要.", "過去の話(was signed)なので現在形 does は合わない."] },
  { id: "g405", q: "Hardly ____ the meeting started when the fire alarm rang.", c: ["the meeting had", "has", "had", "did"], a: 2, t: "T41", d: 1500, why: "Hardly ... when 〜 で「…するとすぐに〜」.Hardly が文頭なので倒置 had + 主語 + 過去分詞.", ja: "会議が始まるとすぐに火災報知器が鳴った.", x: ["空所の後ろにすでに主語 the meeting があるので,もう1つ主語は置けない.", "鳴ったのは過去なので,現在完了 has は合わない.", "", "did の後ろは原形が必要で,started(過去分詞)とつながらない."] },
  { id: "g406", q: "Not until the end of the meeting ____ the true cost of the project.", c: ["did they reveal", "they revealed", "they did reveal", "revealed they"], a: 0, t: "T41", d: 1500, why: "Not until 〜 が文頭なので倒置.「会議の最後になって初めて明らかにした」.", ja: "会議の最後になって初めて,彼らは事業の本当の費用を明らかにした.", x: ["", "倒置が必要なのに,普通の語順になっている.", "did が主語の後ろにあり,倒置になっていない.", "一般動詞は主語の前に出せない."] },
  { id: "g407", q: "Seldom ____ customers complain about our service.", c: ["is", "does", "are", "do"], a: 3, t: "T41", d: 1200, why: "Seldom が文頭なので倒置.主語 customers は複数で,後ろが原形 complain なので do.", ja: "客が当店のサービスに不満を言うことはめったにない.", x: ["主語が複数で,後ろが原形なので is は合わない.", "主語 customers は複数なので does ではない.", "are の後ろに原形 complain は置けない.", ""] },
  { id: "g408", q: "Only by working together ____ we finish this project on time.", c: ["we can", "can", "could we have", "we could"], a: 1, t: "T41", d: 1300, why: "Only by 〜 が文頭なので倒置.助動詞 can が主語の前に出る.", ja: "協力することで初めて,この事業を期限どおりに終えられる.", x: ["倒置が必要なのに,普通の語順になっている.", "", "could we have の後ろなら過去分詞 finished が必要.", "倒置が必要なのに,普通の語順になっている."] },
  { id: "g409", q: "Under no circumstances ____ employees share their passwords.", c: ["they", "employees should", "should", "do employees should"], a: 2, t: "T41", d: 1600, why: "Under no circumstances(どんな場合でも〜ない)が文頭なので倒置.助動詞 should が主語の前に出る.", ja: "どんな場合でも,従業員はパスワードを他人に教えてはならない.", x: ["they を入れると主語が2つ並ぶ.", "空所の後ろにすでに employees があるので,主語が重なる.", "", "do と should を並べることはできない."] },
  { id: "g410", q: "So popular ____ the new model that it sold out in a day.", c: ["was", "is", "it was", "had"], a: 0, t: "T41", d: 1600, why: "So + 形容詞 が文頭に来ると倒置.So popular was the new model that ... (= The new model was so popular that ...).売り切れたのは過去なので was.", ja: "新しい機種はとても人気があったので,1日で売り切れた.", x: ["", "sold out(過去)と時制が合わない.", "主語 the new model が後ろにあるので,it を入れると主語が重なる.", "had の後ろに形容詞 popular を受ける過去分詞がない."] },

  // T42
  { id: "g411", q: "I lost my umbrella, so I need to buy a new ____.", c: ["it", "that", "them", "one"], a: 3, t: "T42", d: 900, why: "なくした傘そのものではなく,同じ種類の別の傘なので one.a new one で「新しいの」.", ja: "傘をなくしたので,新しいのを買う必要がある.", x: ["it はなくしたその傘そのものを指してしまう.", "that は形容詞 new の後ろには置けない.", "them は複数を指す.", ""] },
  { id: "g412", q: "The price of this model is higher than ____ of the old one.", c: ["it", "that", "one", "those"], a: 1, t: "T42", d: 1100, why: "the price の繰り返しを避ける that of.単数の名詞(price)を受けるので that.", ja: "この機種の価格は古い機種の価格より高い.", x: ["it of とは言わない.", "", "one of は「〜のうちの1つ」になり,価格の比較にならない.", "those は複数の名詞を受ける."] },
  { id: "g413", q: "Sales this year are better than ____ of last year.", c: ["that", "it", "those", "them"], a: 2, t: "T42", d: 1100, why: "Sales(複数)の繰り返しを避けるので those of.", ja: "今年の売上は昨年の売上より良い.", x: ["that は単数の名詞を受ける.Sales は複数.", "it of とは言わない.", "", "them of とは言わない."] },
  { id: "g414", q: "____ who wish to attend should register by Friday.", c: ["Those", "They", "These", "Them"], a: 0, t: "T42", d: 1000, why: "those who 〜 で「〜する人々」.", ja: "出席を希望する人は金曜日までに登録してください.", x: ["", "They who とはふつう言わない.", "these who とは言わない.", "目的格 them は主語になれない."] },
  { id: "g415", q: "I bought a printer last week, but ____ is already broken.", c: ["one", "ones", "that one of", "it"], a: 3, t: "T42", d: 900, why: "先週買ったそのプリンター自体を指すので it.", ja: "先週プリンターを買ったが,それがもう壊れている.", x: ["one は同じ種類の別の物で,買ったそのプリンターを指せない.", "ones は複数.", "that one of は後ろに名詞が必要で,文にならない.", ""] },
  { id: "g416", q: "These shoes are too small. Do you have bigger ____?", c: ["one", "ones", "it", "them"], a: 1, t: "T42", d: 1000, why: "靴(複数)と同じ種類の別の物なので ones.", ja: "この靴は小さすぎます.もっと大きいのはありますか.", x: ["one は単数.shoes は複数.", "", "it はこの靴そのものを指してしまう.", "them はこの靴そのものを指してしまう."] },
  { id: "g417", q: "The climate here is milder than ____ of Tokyo.", c: ["it", "this", "that", "one"], a: 2, t: "T42", d: 1200, why: "the climate の繰り返しを避ける that of.", ja: "ここの気候は東京の気候より穏やかだ.", x: ["it of とは言わない.", "this of とは言わない.", "", "one of は「〜のうちの1つ」になり意味が合わない."] },
  { id: "g418", q: "The new office is larger than the old ____.", c: ["one", "it", "that", "those"], a: 0, t: "T42", d: 1300, why: "office の繰り返しを避け,別のオフィスを指すので one.the old one で「古い方」.", ja: "新しい事務所は古い方より広い.", x: ["", "the old it とは言わない.", "the old that とは言わない(that は of と組む).", "those は複数."] },
  { id: "g419", q: "Employees ____ performance is outstanding will receive a bonus.", c: ["who", "which", "those", "whose"], a: 3, t: "T42", d: 1200, why: "空所の後ろが「冠詞のない名詞 performance + 動詞」.従業員の業績なので whose.", ja: "業績の優れた従業員は賞与を受け取る.", x: ["who の後ろは動詞が来る(who perform ...).", "先行詞が人なので which は使えない.", "those を入れると文に動詞が2つになる.", ""] },
  { id: "g420", q: "The products in this catalog are cheaper than ____ sold in stores.", c: ["that", "those", "them", "it"], a: 1, t: "T42", d: 1400, why: "products(複数)の繰り返しを避ける those.後ろの sold in stores が those を修飾する.", ja: "このカタログの製品は,店で売っている製品より安い.", x: ["that は単数の名詞を受ける.", "", "them は後ろから修飾されない.", "it は単数で,後ろから修飾されない."] },

  // T43
  { id: "g421", q: "Mr. Ito works very ____ to meet his sales goals.", c: ["hardly", "harder than", "hard", "hardness"], a: 2, t: "T43", d: 700, why: "「熱心に」は hard.hardly は「ほとんど〜ない」という別の意味.", ja: "伊藤さんは販売目標を達成するため,とても熱心に働く.", x: ["hardly では「ほとんど働かない」になり,意味が逆.", "than の後ろがなく,比較の相手がいない.", "", "名詞は動詞を修飾できない."] },
  { id: "g422", q: "I have ____ any free time this week.", c: ["hardly", "hard", "hardest", "harder"], a: 0, t: "T43", d: 800, why: "「ほとんど〜ない」は hardly.", ja: "今週は自由な時間がほとんどない.", x: ["", "hard では「熱心に持っている」になり意味が通らない.", "最上級は意味が通らない.", "比較級は than がなく意味が通らない."] },
  { id: "g423", q: "Have you seen Ms. Park ____?", c: ["late", "latest", "later", "lately"], a: 3, t: "T43", d: 900, why: "「最近」は lately.現在完了と一緒に使う.", ja: "最近,パークさんに会いましたか.", x: ["late は「遅く」.「遅くに会いましたか」になり不自然.", "latest は形容詞の最上級で,動詞を修飾できない.", "later(後で)は現在完了と使えない.", ""] },
  { id: "g424", q: "The project is ____ finished.", c: ["near", "nearly", "nearby", "nearest"], a: 1, t: "T43", d: 900, why: "「ほぼ」は nearly.be と過去分詞の間の副詞.", ja: "その事業はほぼ完了している.", x: ["near は「近くに」で,程度を表せない.", "", "nearby は「近くの・近くに」で,程度を表せない.", "最上級は意味が通らない."] },
  { id: "g425", q: "Ms. Lee is a ____ respected doctor.", c: ["high", "higher", "highly", "height"], a: 2, t: "T43", d: 1000, why: "「非常に」は highly.形容詞 respected を修飾する.", ja: "リーさんは非常に尊敬されている医師だ.", x: ["high は「高く」で,物理的な高さを表す.", "比較級は than がない.", "", "名詞は形容詞を修飾できない."] },
  { id: "g426", q: "Please watch the children ____.", c: ["closely", "close", "closed", "closing"], a: 0, t: "T43", d: 1100, why: "「注意深く」は closely.動詞 watch を修飾する.", ja: "子どもたちから目を離さないでください.", x: ["", "close は「近くに」で,「注意深く見る」の意味にならない.", "過去分詞は動詞を修飾できない.", "-ing は動詞を修飾できない."] },
  { id: "g427", q: "____ all of the staff attended the party.", c: ["Most", "The most", "Mostly", "Almost"], a: 3, t: "T43", d: 900, why: "「ほとんどすべての」は almost all.almost は副詞で all を修飾する.", ja: "スタッフのほとんど全員がパーティーに出席した.", x: ["most all とは言わない(most of the staff なら可).", "the most all とは言わない.", "mostly は「主に」で,all を修飾しない.", ""] },
  { id: "g428", q: "The train arrived ____ because of the snow.", c: ["lately", "late", "latter", "lateness"], a: 1, t: "T43", d: 1000, why: "「遅れて」は late(副詞).lately は「最近」.", ja: "雪のため電車は遅れて着いた.", x: ["lately では「最近着いた」になり,because of the snow とつながらない.", "", "latter は「後者」の意味の形容詞.", "名詞は動詞を修飾できない."] },
  { id: "g429", q: "The plane flew ____ above the clouds.", c: ["highly", "height", "high", "higher than"], a: 2, t: "T43", d: 1200, why: "物理的に「高く」は high(副詞).highly は「非常に」.", ja: "飛行機は雲の上を高く飛んだ.", x: ["highly では「非常に飛んだ」になり意味が通らない.", "名詞は動詞を修飾できない.", "", "than の後ろに比較の相手がない(above the clouds は比較の相手ではない)."] },
  { id: "g430", q: "The store is located ____ the station.", c: ["close to", "nearly", "closely", "most"], a: 0, t: "T43", d: 1300, why: "「〜の近くに」は close to.nearly は「ほぼ」,closely は「注意深く」.", ja: "その店は駅の近くにある.", x: ["", "nearly は「ほぼ」の意味で,場所を表せない.", "closely は「注意深く・密接に」で,場所を表せない.", "most は場所を表せない."] },

  // T44
  { id: "g431", q: "The meeting will be held ____ 2:00 and 3:00.", c: ["among", "through", "during", "between"], a: 3, t: "T44", d: 600, why: "between A and B で「A と B の間に」.", ja: "会議は2時から3時の間に開かれる.", x: ["among は3つ以上の中で,and と組まない.", "through は「〜を通して」で,and と組まない.", "during の後ろには期間を表す名詞が1つ来る.", ""] },
  { id: "g432", q: "The award was divided ____ the five team members.", c: ["between", "among", "across", "along"], a: 1, t: "T44", d: 800, why: "5人(3つ以上)の中で分けたので among.", ja: "賞はチームの5人で分けられた.", x: ["between は2つの間.", "", "across は「横切って」.", "along は「〜に沿って」."] },
  { id: "g433", q: "There is a bank ____ the street from our office.", c: ["among", "through", "across", "along with"], a: 2, t: "T44", d: 700, why: "across the street from 〜 で「〜から通りを渡った向かいに」.", ja: "事務所から通りを渡った向かいに銀行がある.", x: ["among は3つ以上の中.", "through は「中を通り抜けて」で,向かいを表せない.", "", "along with は「〜と一緒に」."] },
  { id: "g434", q: "We walked ____ the river for an hour.", c: ["along", "between", "among", "beside of"], a: 0, t: "T44", d: 800, why: "「川に沿って」は along.", ja: "私たちは川に沿って1時間歩いた.", x: ["", "between は2つの間で,and が必要.", "among は3つ以上の中.", "beside of とは言わない(beside は直接名詞をとる)."] },
  { id: "g435", q: "The train passes ____ a long tunnel.", c: ["across", "along", "over", "through"], a: 3, t: "T44", d: 900, why: "トンネルの中を通り抜けるので through.", ja: "電車は長いトンネルを通り抜ける.", x: ["across は表面を横切るとき.トンネルの中は通れない.", "along は沿って進むとき.", "over は上を越えるとき.", ""] },
  { id: "g436", q: "____ English, Ms. Ono speaks Spanish and French.", c: ["Beside", "Besides", "Except", "Between"], a: 1, t: "T44", d: 1000, why: "「英語に加えて」は besides.beside は「〜のそばに」.", ja: "小野さんは英語に加えて,スペイン語とフランス語を話す.", x: ["beside は「〜のそばに」で,場所を表す.", "", "except(〜を除いて)では,英語は話さないことになる.", "between は2つの間."] },
  { id: "g437", q: "Please sign the form ____ a black pen.", c: ["by", "in", "with", "on"], a: 2, t: "T44", d: 900, why: "道具を使うときは with.", ja: "黒いペンで用紙に署名してください.", x: ["by は手段(by mail, by bus)で,道具には使わない.", "in は in ink(インクで)のように材料に使う.a pen とは組まない.", "", "on は「〜の上に」."] },
  { id: "g438", q: "You can send the documents ____ e-mail.", c: ["by", "with", "in", "through the"], a: 0, t: "T44", d: 900, why: "手段(通信・交通)は by.by e-mail, by bus.冠詞は付けない.", ja: "書類はメールで送れる.", x: ["", "with は道具に使う.通信手段には by.", "in e-mail とは言わない.", "through the e-mail だと特定のメールの中を通ることになる."] },
  { id: "g439", q: "The parking lot is located ____ the building.", c: ["during", "among", "between", "behind"], a: 3, t: "T44", d: 1100, why: "「建物の裏に」は behind.", ja: "駐車場は建物の裏にある.", x: ["during は期間を表す.", "among は3つ以上の中.", "between は2つの間で,and が必要.", ""] },
  { id: "g440", q: "All the documents are ready ____ the signed contract.", c: ["besides", "except for", "beside", "among"], a: 1, t: "T44", d: 1200, why: "「署名済みの契約書を除いて」は except for.", ja: "署名済みの契約書以外は,すべての書類の準備ができている.", x: ["besides(〜に加えて)だと,契約書も準備できていることになり,意味がずれる.", "", "beside は「〜のそばに」.", "among は3つ以上の中."] },

  // T45
  { id: "g441", q: "____ arrives first should turn on the lights.", c: ["Who", "Whom", "Whoever", "Anyone"], a: 2, t: "T45", d: 1100, why: "「最初に来る人はだれでも」.先行詞を含む whoever.", ja: "最初に来た人が照明をつけてください.", x: ["Who では疑問文の形になり,文にならない.", "whom は目的格で,arrives の主語になれない.", "", "Anyone だけでは,後ろの arrives とつなぐ関係詞がない(Anyone who なら可)."] },
  { id: "g442", q: "You can order ____ you like from the menu.", c: ["whatever", "whoever", "however", "whenever"], a: 0, t: "T45", d: 1100, why: "「好きなものは何でも」.like の目的語が欠けているので whatever.", ja: "メニューから好きなものを何でも注文できる.", x: ["", "whoever は人を表す.", "however は「どんなに〜でも」で,後ろに形容詞・副詞が来る.", "whenever(いつでも)の後ろは完全な文が必要."] },
  { id: "g443", q: "____ hard the task is, we will finish it on time.", c: ["Whatever", "Whoever", "Whenever", "However"], a: 3, t: "T45", d: 1200, why: "however + 形容詞 で「どんなに〜でも」.", ja: "どんなに大変な作業でも,期限どおりに終える.", x: ["whatever の後ろに形容詞 hard を直接置けない.", "whoever は人を表す.", "whenever の後ろは完全な文が必要で,hard とつながらない.", ""] },
  { id: "g444", q: "Please call me ____ you need help.", c: ["whatever", "whenever", "whoever", "however"], a: 1, t: "T45", d: 1000, why: "「助けが必要なときはいつでも」.後ろは完全な文なので whenever.", ja: "助けが必要なときはいつでも電話してください.", x: ["whatever の後ろは目的語などが欠けた文.you need help は欠けていない.", "", "whoever は人を表す.", "however の後ろには形容詞・副詞が来る."] },
  { id: "g445", q: "You may sit ____ you like.", c: ["however", "whatever", "wherever", "whoever"], a: 2, t: "T45", d: 1100, why: "「好きなところならどこでも」は wherever.", ja: "好きなところに座ってよい.", x: ["however の後ろには形容詞・副詞が来る.", "whatever だと「好きなものは何でも座る」になり,sit の目的語にならない.", "", "whoever は人を表す."] },
  { id: "g446", q: "You can choose ____ of the two rooms you prefer.", c: ["whichever", "whatever", "whoever", "wherever"], a: 0, t: "T45", d: 1200, why: "決まった選択肢(2つの部屋)の中の「どちらでも」は whichever.", ja: "2つの部屋のうち,好きな方を選べる.", x: ["", "whatever は範囲の決まっていない「何でも」.of the two とは組まない.", "whoever は人を表す.", "wherever は場所を表し,of the two と組まない."] },
  { id: "g447", q: "The prize will go to ____ sells the most units.", c: ["whomever", "whichever", "who", "whoever"], a: 3, t: "T45", d: 1300, why: "前置詞 to の後ろでも,関係詞の節の中では sells の主語なので主格の whoever.", ja: "賞は,最も多く売った人に贈られる.", x: ["whomever は目的格.節の中で sells の主語になれない.", "whichever は物や選択肢を表す.", "who だけでは先行詞がなく,「〜する人」の意味にならない.", ""] },
  { id: "g448", q: "____ you decide, we will support you.", c: ["However", "Whatever", "Whoever", "Wherever"], a: 1, t: "T45", d: 1300, why: "「あなたが何を決めても」.decide の目的語が欠けているので whatever.", ja: "あなたが何を決めても,私たちは支えます.", x: ["however の後ろには形容詞・副詞が来る.", "", "whoever は人を表し,「だれが決めても」にはならない(you が主語なので).", "wherever は場所を表し,decide とは合わない."] },
  { id: "g449", q: "____ carefully you check, some errors may remain.", c: ["Whatever", "Whenever", "However", "Whichever"], a: 2, t: "T45", d: 1400, why: "however + 副詞 で「どんなに〜に…しても」.", ja: "どんなに注意して確認しても,誤りが残ることがある.", x: ["whatever の後ろに副詞 carefully は置けない.", "whenever の後ろは完全な文が必要で,carefully とつながらない.", "", "whichever は選択肢を表す."] },
  { id: "g450", q: "Give the tickets to ____ wants them.", c: ["whoever", "whomever", "whichever", "who"], a: 0, t: "T45", d: 1500, why: "wants の主語になるので主格 whoever.前置詞 to があっても,節の中の役割で決める.", ja: "欲しい人にはだれにでも切符をあげてください.", x: ["", "whomever は目的格で,wants の主語になれない.", "whichever は物や選択肢を表す.", "who だけでは先行詞がない."] },

  // ---- 新しい定理 T46〜T50(g451〜) ----
  // T46
  { id: "g451", q: "Ms. Kim is interested ____ joining the sales team.", c: ["at", "for", "on", "in"], a: 3, t: "T46", d: 500, why: "be interested in 〜 で「〜に興味がある」.", ja: "キムさんは営業チームに加わることに興味がある.", x: ["at は場所・時点を表し,interested とは組まない.", "for は interested とは組まない.", "on は interested とは組まない.", ""] },
  { id: "g452", q: "Are you familiar ____ this software?", c: ["with", "of", "to", "by"], a: 0, t: "T46", d: 600, why: "be familiar with 〜 で「〜をよく知っている」.", ja: "このソフトはよくご存じですか.", x: ["", "of は familiar とは組まない.", "be familiar to は「(物が人に)よく知られている」で,人が主語のときは with.", "by は familiar とは組まない."] },
  { id: "g453", q: "The new machine is capable ____ printing 50 pages per minute.", c: ["for", "to", "of", "in"], a: 2, t: "T46", d: 800, why: "be capable of -ing で「〜する能力がある」.", ja: "新しい機械は1分に50ページ印刷できる.", x: ["for は capable とは組まない.", "capable は to do をとらない(be able to do と区別).", "", "in は capable とは組まない."] },
  { id: "g454", q: "The town is heavily dependent ____ tourism.", c: ["of", "on", "from", "to"], a: 1, t: "T46", d: 900, why: "be dependent on 〜 で「〜に頼っている」.depend on と同じ前置詞.", ja: "その町は観光に大きく頼っている.", x: ["of は dependent とは組まない.", "", "from は dependent とは組まない.", "to は dependent とは組まない."] },
  { id: "g455", q: "We are proud ____ our high-quality products.", c: ["about", "with", "for", "of"], a: 3, t: "T46", d: 600, why: "be proud of 〜 で「〜を誇りに思う」.", ja: "当社は高品質の製品を誇りに思っている.", x: ["about は proud とはふつう組まない.", "with は proud とは組まない.", "for は proud とは組まない.", ""] },
  { id: "g456", q: "This room is not suitable ____ large meetings.", c: ["for", "on", "with", "at"], a: 0, t: "T46", d: 700, why: "be suitable for 〜 で「〜に適している」.", ja: "この部屋は大きな会議には向いていない.", x: ["", "on は suitable とは組まない.", "with は suitable とは組まない.", "at は suitable とは組まない."] },
  { id: "g457", q: "The new model is quite different ____ the old one.", c: ["at", "with", "from", "by"], a: 2, t: "T46", d: 700, why: "be different from 〜 で「〜と違う」.", ja: "新しい機種は古い機種とかなり違う.", x: ["at は different とは組まない.", "with は different とは組まない.", "", "by は different とは組まない."] },
  { id: "g458", q: "Mr. Ono is accustomed ____ working late.", c: ["with", "to", "for", "of"], a: 1, t: "T46", d: 1000, why: "be accustomed to -ing で「〜することに慣れている」.to は前置詞なので後ろは -ing.", ja: "小野さんは遅くまで働くことに慣れている.", x: ["with は accustomed とは組まない.", "", "for は accustomed とは組まない.", "of は accustomed とは組まない."] },
  { id: "g459", q: "Employees are responsible ____ keeping their work areas clean.", c: ["to", "with", "of", "for"], a: 3, t: "T46", d: 1100, why: "be responsible for 〜 で「〜に責任がある」.後ろは名詞か -ing.", ja: "従業員は自分の作業場所をきれいに保つ責任がある.", x: ["be responsible to は「(人)に対して責任を負う」で,人の前に使う.", "with は responsible とは組まない.", "of は responsible とは組まない.", ""] },
  { id: "g460", q: "The results were consistent ____ our earlier findings.", c: ["with", "to", "for", "by"], a: 0, t: "T46", d: 1200, why: "be consistent with 〜 で「〜と一致している」.", ja: "結果は以前の調査結果と一致していた.", x: ["", "to は consistent とは組まない.", "for は consistent とは組まない.", "by は consistent とは組まない."] },

  // T47
  { id: "g461", q: "We will hold a ____ conference in Tokyo.", c: ["three days", "three-days", "three-day", "third-day"], a: 2, t: "T47", d: 700, why: "名詞の前で「数詞 + 名詞」をハイフンでつなぐと単数形.a three-day conference.", ja: "東京で3日間の会議を開く.", x: ["ハイフンなしの複数形は名詞の前に置けない.", "ハイフンでつなぐときは単数形(-days にしない).", "", "third-day は「3日目の」で,意味が違う."] },
  { id: "g462", q: "Let's take a ____ break.", c: ["ten-minutes", "ten-minute", "ten minutes", "tenth-minute"], a: 1, t: "T47", d: 700, why: "a ten-minute break(10分の休憩).ハイフンでつないだ単位は単数形.", ja: "10分休憩しましょう.", x: ["ハイフンでつなぐときは単数形.", "", "ハイフンなしの複数形は名詞の前に置けない(a ten minutes break は不可).", "tenth は順番を表し,意味が違う."] },
  { id: "g463", q: "The company signed a ____ contract with the supplier.", c: ["five years", "five-years", "fifth-year", "five-year"], a: 3, t: "T47", d: 800, why: "a five-year contract(5年の契約).", ja: "その会社は仕入先と5年契約を結んだ.", x: ["名詞の前に複数形の単位を置けない.", "ハイフンでつなぐときは単数形.", "fifth-year は「5年目の」で,意味が違う.", ""] },
  { id: "g464", q: "The meeting lasted ____.", c: ["two hours", "two-hour", "two hour", "two-hours"], a: 0, t: "T47", d: 900, why: "名詞の前ではなく,動詞 lasted の後ろなので,ふつうの複数形 two hours.", ja: "会議は2時間続いた.", x: ["", "ハイフンでつないだ形は名詞の前に置く形で,ここには使わない.", "2時間なので複数形 hours が必要.", "ハイフンでつないだ形は名詞の前に置く形.しかも単位は単数形になる."] },
  { id: "g465", q: "Ms. Lee wrote a ____ report on the market.", c: ["20 page", "20-pages", "20-page", "20th-page"], a: 2, t: "T47", d: 900, why: "a 20-page report(20ページの報告書).", ja: "リーさんは市場について20ページの報告書を書いた.", x: ["名詞の前ではハイフンでつなぐ.", "ハイフンでつなぐときは単数形.", "", "20th は順番を表し,意味が違う."] },
  { id: "g466", q: "Sales rose by ____ last year.", c: ["10 percents", "10 percent", "10-percent", "10-percents"], a: 1, t: "T47", d: 1000, why: "by の後ろの名詞の位置.percent は数字の後でも s を付けない.10 percent.", ja: "昨年,売上は10%増えた.", x: ["percent には s を付けない.", "", "ハイフンでつないだ形は名詞の前に置く形.後ろに名詞がない.", "ハイフンの形は名詞の前で使い,s も付けない."] },
  { id: "g467", q: "There was a ____ increase in sales.", c: ["10th-percent", "10 percents", "10-percents", "10-percent"], a: 3, t: "T47", d: 1000, why: "名詞 increase の前なので,ハイフンでつないだ 10-percent.", ja: "売上が10%増えた.", x: ["10th は順番を表し,意味が通らない.", "名詞の前に複数形は置けず,percent に s も付けない.", "ハイフンでつなぐときは単数形.", ""] },
  { id: "g468", q: "The new office is a ____ walk from the station.", c: ["five-minute", "five minutes", "five-minutes", "fifth-minute"], a: 0, t: "T47", d: 1100, why: "a five-minute walk(歩いて5分).名詞 walk の前.", ja: "新しい事務所は駅から歩いて5分だ.", x: ["", "名詞の前に複数形の単位は置けない(five minutes' walk なら可).", "ハイフンでつなぐときは単数形.", "fifth は順番を表し,意味が違う."] },
  { id: "g469", q: "Applicants must have at least ____ of experience.", c: ["three-year", "three-years", "three years", "third year"], a: 2, t: "T47", d: 1200, why: "前置詞 of の前で,名詞としての「3年」なので three years.", ja: "応募者は少なくとも3年の経験が必要だ.", x: ["ハイフンでつないだ形は後ろに名詞が必要.ここは of が続く.", "ハイフンでつなぐときは単数形で,名詞の前に置く.", "", "third year は「3年目」で,意味が違う."] },
  { id: "g470", q: "The hotel offers a ____ discount for stays of three nights or more.", c: ["15-percents", "15-percent", "15 percents", "fifteenth-percent"], a: 1, t: "T47", d: 1300, why: "名詞 discount の前なので 15-percent.", ja: "そのホテルは3泊以上の滞在に15%の割引をする.", x: ["名詞の前でも percent に s は付けない.", "", "percent に s は付けず,名詞の前ではハイフンでつなぐ.", "fifteenth は順番を表し,意味が通らない."] },

  // T48
  { id: "g471", q: "Please fill ____ this form and return it to the desk.", c: ["away", "up", "off", "out"], a: 3, t: "T48", d: 700, why: "fill out で「(用紙に)記入する」.fill in もほぼ同じ意味で使う.", ja: "この用紙に記入して受付に返してください.", x: ["fill away という句動詞はない.", "fill up は「(タンクなどを)いっぱいにする」.", "fill off という句動詞はない.", ""] },
  { id: "g472", q: "The outdoor concert was called ____ because of the storm.", c: ["off", "up", "out", "on"], a: 0, t: "T48", d: 800, why: "call off で「中止する」.", ja: "嵐のため屋外コンサートは中止された.", x: ["", "call up は「電話をかける」.", "call out は「大声で呼ぶ」.", "call on は「訪問する・求める」."] },
  { id: "g473", q: "We have run ____ of printer paper.", c: ["over", "off", "out", "down"], a: 2, t: "T48", d: 800, why: "run out of 〜 で「〜を使い果たす」.", ja: "プリンターの紙を切らしてしまった.", x: ["run over は「(車で)ひく・超過する」.", "run off は「走り去る」.", "", "run down は「(電池が)切れる・けなす」で,of とは組まない."] },
  { id: "g474", q: "The manager will look ____ the customer's complaint.", c: ["after", "into", "up", "over"], a: 1, t: "T48", d: 900, why: "look into で「調べる」.", ja: "部長が客の苦情を調べる.", x: ["look after は「世話をする」.", "", "look up は「(辞書などで)調べる」で,苦情には使わない.", "look over は「ざっと目を通す」で,詳しく調べる意味ではない."] },
  { id: "g475", q: "The meeting has been put ____ until next week.", c: ["out", "up", "on", "off"], a: 3, t: "T48", d: 900, why: "put off で「延期する」(= postpone).", ja: "会議は来週まで延期された.", x: ["put out は「(火を)消す」.", "put up は「掲示する・泊める」.", "put on は「着る」.", ""] },
  { id: "g476", q: "Ms. Diaz will take ____ the project when Mr. Hall retires.", c: ["over", "off", "up", "after"], a: 0, t: "T48", d: 1000, why: "take over で「引き継ぐ」.", ja: "ホールさんが退職したら,ディアスさんがその事業を引き継ぐ.", x: ["", "take off は「離陸する・脱ぐ」.", "take up は「(趣味などを)始める・(場所を)占める」.", "take after は「(親に)似ている」."] },
  { id: "g477", q: "The company turned ____ the offer because the price was too low.", c: ["off", "out", "down", "over"], a: 2, t: "T48", d: 1000, why: "turn down で「断る」(= reject).", ja: "価格が低すぎたので,その会社は申し出を断った.", x: ["turn off は「(電源を)切る」.", "turn out は「〜だと分かる」.", "", "turn over は「ひっくり返す・引き渡す」."] },
  { id: "g478", q: "Technicians will set ____ the equipment before the event.", c: ["off", "up", "out", "in"], a: 1, t: "T48", d: 1100, why: "set up で「設置する・準備する」.", ja: "技術者が催しの前に機材を設置する.", x: ["set off は「出発する」.", "", "set out は「出発する・始める」.", "set in は「(悪いことが)始まる」."] },
  { id: "g479", q: "The research team carried ____ a survey of 500 customers.", c: ["on", "over", "off", "out"], a: 3, t: "T48", d: 1200, why: "carry out で「実行する」(= conduct).", ja: "研究チームは500人の客を対象に調査を行った.", x: ["carry on は「続ける」.", "carry over は「繰り越す」.", "carry off は「持ち去る・うまくやる」.", ""] },
  { id: "g480", q: "It took a while to figure ____ why the system had stopped.", c: ["out", "in", "up", "off"], a: 0, t: "T48", d: 1300, why: "figure out で「理解する・解明する」.", ja: "システムがなぜ止まったのかを突き止めるのに少し時間がかかった.", x: ["", "figure in は「計算に入れる」.", "figure up という句動詞はふつう使わない.", "figure off という句動詞はない."] },

  // T49
  { id: "g481", q: "Please submit your report no ____ than Friday.", c: ["late", "latest", "later", "lately"], a: 2, t: "T49", d: 900, why: "no later than 〜 で「遅くとも〜までに」.", ja: "遅くとも金曜日までに報告書を提出してください.", x: ["than があるので原級は使えない.", "最上級は than と組めない.", "", "lately は「最近」."] },
  { id: "g482", q: "As ____ as 300 people attended the seminar.", c: ["much", "many", "more", "most"], a: 1, t: "T49", d: 900, why: "as many as + 数 で「〜もの(数)」.people は数えられるので many.", ja: "300人もの人がセミナーに出席した.", x: ["much は数えられない量に使う(as much as $500).", "", "as ... as の間は原級.比較級 more は入らない.", "as ... as の間に最上級は入らない."] },
  { id: "g483", q: "The new model costs ____ as much as the old one.", c: ["second", "two", "double of", "twice"], a: 3, t: "T49", d: 1000, why: "twice as ... as 〜 で「〜の2倍…」.", ja: "新しい機種は古い機種の2倍の値段だ.", x: ["second は順番を表し,倍数には使わない.", "two は as much as の前に置けない(two times なら可).", "double of とは言わない.", ""] },
  { id: "g484", q: "Your order is the same ____ last month's.", c: ["as", "than", "with", "to"], a: 0, t: "T49", d: 800, why: "the same as 〜 で「〜と同じ」.", ja: "ご注文は先月のものと同じです.", x: ["", "than は比較級と組む.", "the same with とは言わない.", "the same to とは言わない."] },
  { id: "g485", q: "Many employees prefer working from home ____ commuting to the office.", c: ["than", "rather", "to", "over to"], a: 2, t: "T49", d: 1000, why: "prefer A to B で「B より A を好む」.than は使わない.", ja: "多くの従業員は通勤するより在宅勤務を好む.", x: ["prefer は than と組まない.", "rather だけでは比較の対象をつなげない(rather than なら可).", "", "over to とは言わない."] },
  { id: "g486", q: "We decided to repair the old printer ____ than buy a new one.", c: ["prefer", "rather", "more", "instead"], a: 1, t: "T49", d: 1100, why: "rather than 〜 で「〜よりむしろ」.", ja: "新しいプリンターを買うより,むしろ古いものを修理することにした.", x: ["prefer は動詞で,than と組まない.", "", "more than は「〜より多い」で,意味が合わない.", "instead than とは言わない(instead of なら可)."] },
  { id: "g487", q: "The repair may cost as ____ as $500.", c: ["many", "more", "most", "much"], a: 3, t: "T49", d: 1100, why: "as much as + 金額・量 で「〜もの(量)」.金額は much.", ja: "修理には500ドルもかかるかもしれない.", x: ["many は数えられる名詞の数に使う.金額には much.", "as ... as の間に比較級は入らない.", "as ... as の間に最上級は入らない.", ""] },
  { id: "g488", q: "The more you practice, the ____ you will become.", c: ["more confident", "confident", "most confident", "confidently"], a: 0, t: "T49", d: 1200, why: "the + 比較級, the + 比較級 で「〜すればするほど…」.", ja: "練習すればするほど,自信がつくだろう.", x: ["", "前半が比較級なので,後半も比較級が必要.", "最上級は使わない.", "become の後ろは形容詞(補語).副詞は入らない."] },
  { id: "g489", q: "This year's profit was ____ higher than expected.", c: ["very", "more", "much", "most"], a: 2, t: "T49", d: 1300, why: "比較級 higher を強めるのは much(はるかに).", ja: "今年の利益は予想よりはるかに高かった.", x: ["very は比較級を強められない.", "more higher とは言わない(higher がすでに比較級).", "", "most は最上級をつくる語."] },
  { id: "g490", q: "Of the two candidates, Ms. Park is the ____ qualified.", c: ["most", "more", "much", "many"], a: 1, t: "T49", d: 1400, why: "2人のうちで「より〜な方」は the + 比較級.of the two があるときは最上級ではなく比較級.", ja: "2人の候補者のうち,パークさんの方が適任だ.", x: ["2つのうちの比較なので,最上級ではなく比較級を使う.", "", "much は比較級を強める語で,単独では使わない.", "many は数を表す語."] },

  // T50
  { id: "g491", q: "The city is known ____ its beautiful parks.", c: ["as", "with", "by", "for"], a: 3, t: "T50", d: 700, why: "be known for 〜 で「〜で知られている」(理由・特徴).", ja: "その市は美しい公園で知られている.", x: ["be known as は「〜として知られている」で,呼び名や立場を言うとき.", "with は known とは組まない.", "by は「〜によって知られる」で,特徴を表せない.", ""] },
  { id: "g492", q: "This table is made ____ wood.", c: ["of", "at", "by", "with"], a: 0, t: "T50", d: 800, why: "材料がそのまま見えるときは be made of.", ja: "この机は木でできている.", x: ["", "at は made とは組まない(場所を表す).", "by の後ろには作った人が来る.", "with は made とはふつう組まない."] },
  { id: "g493", q: "Wine is made ____ grapes.", c: ["of", "by", "from", "in"], a: 2, t: "T50", d: 900, why: "原料が変化して元の形が見えないときは be made from.", ja: "ワインはぶどうから作られる.", x: ["of は材料がそのまま見えるとき.", "by の後ろには作った人が来る.", "", "in の後ろには場所が来る."] },
  { id: "g494", q: "The new office is located ____ the city center.", c: ["at", "in", "on", "to"], a: 1, t: "T50", d: 800, why: "広い場所(都市・地区)の中には in.be located in 〜.", ja: "新しい事務所は市の中心部にある.", x: ["at は地点(at the corner)に使う.地区には in.", "", "on は面(on Main Street)に使う.", "to は方向を表し,located とは組まない."] },
  { id: "g495", q: "The ground was covered ____ snow.", c: ["by", "of", "from", "with"], a: 3, t: "T50", d: 900, why: "be covered with 〜 で「〜で覆われている」.", ja: "地面は雪に覆われていた.", x: ["by は動作をする人・もの.状態を表すときは with.", "of は covered とは組まない.", "from は covered とは組まない.", ""] },
  { id: "g496", q: "Ms. Ito is involved ____ the planning of the event.", c: ["in", "to", "on", "at"], a: 0, t: "T50", d: 1000, why: "be involved in 〜 で「〜に関わっている」.", ja: "伊藤さんはその催しの企画に関わっている.", x: ["", "to は involved とは組まない.", "on は involved とは組まない.", "at は involved とは組まない."] },
  { id: "g497", q: "Workers may be exposed ____ loud noise.", c: ["by", "with", "to", "for"], a: 2, t: "T50", d: 1100, why: "be exposed to 〜 で「〜にさらされる」.", ja: "作業員は大きな騒音にさらされることがある.", x: ["by は exposed とは組まない.", "with は exposed とは組まない.", "", "for は exposed とは組まない."] },
  { id: "g498", q: "The movie is based ____ a true story.", c: ["in", "on", "from", "of"], a: 1, t: "T50", d: 1100, why: "be based on 〜 で「〜に基づいている」.場所なら be based in.", ja: "その映画は実話に基づいている.", x: ["be based in は「〜に拠点がある」で,場所に使う.", "", "from は based とは組まない.", "of は based とは組まない."] },
  { id: "g499", q: "The company is engaged ____ the development of new medicines.", c: ["for", "on", "to", "in"], a: 3, t: "T50", d: 1300, why: "be engaged in 〜 で「〜に従事している」.", ja: "その会社は新薬の開発に携わっている.", x: ["for は engaged とは組まない.", "on は engaged とは組まない.", "be engaged to は「〜と婚約している」.", ""] },
  { id: "g500", q: "The conference hall was filled ____ people.", c: ["with", "by", "of", "from"], a: 0, t: "T50", d: 1300, why: "be filled with 〜 で「〜でいっぱいだ」.", ja: "会議場は人でいっぱいだった.", x: ["", "by は動作をする人・もの.状態は with.", "full of と混同しやすいが,filled は with と組む.", "from は filled とは組まない."] },

  // ---- 難しい定理(1500〜2700) ----
  { id: "g511", q: "____ it not for the new software, we would need twice as many staff.", c: ["Was", "Were", "Had", "If"], a: 1, t: "T52", d: 2000, why: "Were it not for 〜 で「(今)〜がなければ」.If it were not for の if を省いた倒置.", ja: "新しいソフトがなければ,2倍の人員が必要だろう.", x: ["倒置の仮定法では主語が it でも were を使う.", "", "Had it not been for なら正しいが,been がない.", "If なら If it were not for で,語順が違う."] },
  { id: "g512", q: "I would rather you ____ the report by e-mail than by fax.", c: ["will send", "send", "sent", "sending"], a: 2, t: "T52", d: 2300, why: "would rather + 主語 + 過去形 で「(人に)〜してほしい」.仮定法と同じく,今のことでも過去形.", ja: "報告書はファクスではなくメールで送ってほしい.", x: ["would rather の後ろの節に will は使わない.", "would rather + 主語 + 動詞 では,今のことでも過去形を使う.", "", "-ing だけでは節の動詞にならない."] },
  { id: "g513", q: "It is high time we ____ our outdated computer system.", c: ["have replaced", "replace", "will replace", "replaced"], a: 3, t: "T52", d: 2000, why: "It is (high) time + 主語 + 過去形 で「もう〜してもいいころだ」.", ja: "そろそろ古いコンピューターシステムを入れ替えるべきだ.", x: ["It is time の後ろに現在完了は使わない.", "It is (high) time の後ろの節は過去形.", "It is time の後ろに未来形は使わない.", ""] },
  { id: "g514", q: "He talks about the project as if he ____ in charge of it, but he is not.", c: ["were", "is", "will be", "has been"], a: 0, t: "T52", d: 1700, why: "as if + 過去形(be は were)で「まるで〜であるかのように」(事実と違う).", ja: "彼はまるで自分が担当者であるかのようにその計画について話すが,そうではない.", x: ["", "事実と違うことなので現在形は使わない.", "事実と違う仮定に未来形は使わない.", "事実と違う仮定に現在完了は使わない."] },
  { id: "g515", q: "Please double-check the figures lest any errors ____ in the final report.", c: ["will appear", "appears", "appear", "appeared"], a: 2, t: "T52", d: 2600, why: "lest + 主語 + (should) 原形 で「〜しないように」.", ja: "最終報告に誤りが入らないよう,数字を再確認してください.", x: ["lest の後ろに will は使わない.", "lest の後ろは原形(または should + 原形).それに主語 errors は複数.", "", "lest の後ろに過去形は使わない."] },
  { id: "g516", q: "Submit the form by Friday; ____, your application will not be processed.", c: ["therefore", "unless", "however", "otherwise"], a: 3, t: "T52", d: 1700, why: "otherwise は「さもなければ」.前の命令に従わなかった場合の結果を続ける.", ja: "金曜日までに用紙を出してください.さもないと申請は処理されません.", x: ["therefore は「したがって」で意味が合わない.", "unless は接続詞で,後ろに節が必要.カンマの後に置く語ではない.", "however は「しかし」で意味が合わない.", ""] },
  { id: "g517", q: "If the firm ____ the offer last year, it would be much larger today.", c: ["had accepted", "accepts", "accepted", "would accept"], a: 0, t: "T52", d: 2300, why: "if 節は過去(last year)の事実と違う仮定で had accepted,主節は今のこと(today)で would be.時がずれる仮定法.", ja: "もし昨年その申し出を受けていたら,会社は今ごろずっと大きくなっているだろう.", x: ["", "過去の事実と違う仮定なので現在形は使わない.", "accepted は「今〜なら」の仮定になり,last year と合わない.", "if 節の中で would は使わない."] },
  { id: "g518", q: "But ____ the bank loan, the company would have gone out of business.", c: ["to", "for", "of", "with"], a: 1, t: "T52", d: 2400, why: "But for 〜 で「〜がなければ・なかったら」(= Without / If it had not been for).", ja: "銀行の融資がなかったら,その会社は倒産していただろう.", x: ["But for で「〜がなければ」.to とは組まない.", "", "of は But と組まない.", "With the loan なら「融資があったので」で,But とは組まない."] },
  { id: "g519", q: "I wish I ____ the seminar yesterday; it sounded very useful.", c: ["would attend", "attend", "attended", "had attended"], a: 3, t: "T52", d: 1900, why: "過去(yesterday)のことへの後悔は I wish + 過去完了.", ja: "昨日のセミナーに出ればよかった.とても役に立ちそうだった.", x: ["過去のことに would は使わない.", "I wish の後ろで原形は使わない.", "attended だと今の願望になり,yesterday と合わない.", ""] },
  { id: "g520", q: "If only we ____ more staff, we could open on Sundays.", c: ["had", "have", "will have", "having"], a: 0, t: "T52", d: 2100, why: "If only + 過去形 で「(今)〜でさえあればなあ」.今の事実と違う願いなので仮定法の過去形.", ja: "人手さえあれば,日曜日も営業できるのだが.", x: ["", "If only は「〜でさえあれば」で,今の事実と違う願いなので過去形.", "If only の後ろに will は使わない.", "-ing だけでは節の動詞にならない."] },
  { id: "g521", q: "The ____ we prepare, the fewer problems we will have.", c: ["most", "much", "more", "many"], a: 2, t: "T53", d: 1600, why: "the + 比較級 〜, the + 比較級 … で「〜すればするほど…」.後半が the fewer なので前半も比較級 more.", ja: "準備すればするほど,問題は少なくなる.", x: ["the + 比較級, the + 比較級 の形なので最上級は使わない.", "much は比較級ではない.", "", "many は比較級ではない."] },
  { id: "g522", q: "The new warehouse is three times ____ the old one.", c: ["so large as", "larger as", "as larger than", "as large as"], a: 3, t: "T53", d: 1700, why: "倍数 + as + 原級 + as で「〜の…倍の」.", ja: "新しい倉庫は古い倉庫の3倍の広さだ.", x: ["倍数表現は as 〜 as を使う.", "larger と as は組まない(larger than なら正しい).", "as と than は組まない.", ""] },
  { id: "g523", q: "This year's results are ____ better than last year's.", c: ["far", "very", "more", "so"], a: 0, t: "T53", d: 1500, why: "比較級を強めるのは much / far / even / a lot.very は使えない.", ja: "今年の結果は昨年よりはるかに良い.", x: ["", "very は比較級を強められない.", "better はすでに比較級なので more は重ねない.", "so は比較級を強められない."] },
  { id: "g524", q: "The new model is superior ____ its competitors in fuel efficiency.", c: ["than", "to", "from", "over"], a: 1, t: "T53", d: 1700, why: "superior / inferior / senior / junior / prior はラテン語由来の比較の語で,than ではなく to をとる.", ja: "新型は燃費で競合製品より優れている.", x: ["superior は than ではなく to をとる.", "", "from は superior とは組まない.", "superior は over ではなく to と組む."] },
  { id: "g525", q: "Her success is due not so much to luck ____ to hard work.", c: ["and", "but", "than", "as"], a: 3, t: "T53", d: 2400, why: "not so much A as B で「A というよりむしろ B」.", ja: "彼女の成功は運というよりむしろ努力によるものだ.", x: ["and は not so much と組まない.", "not A but B なら「A ではなく B」だが,so much と組むのは as.", "than は not so much と組まない.", ""] },
  { id: "g526", q: "The repairs cost no ____ than $5,000, which was more than we expected.", c: ["less", "fewer", "little", "lesser"], a: 0, t: "T53", d: 2200, why: "no less than 〜 で「〜も(多くの)」.金額の多さを強調する.", ja: "修理には5,000ドルもかかり,予想を上回った.", x: ["", "fewer は数えられる名詞に使う.金額全体には less.", "little は比較級ではない.", "lesser は名詞の前に置く形容詞で,than と組まない."] },
  { id: "g527", q: "The new process is ____ complicated than the old one, so training takes less time.", c: ["fewer", "less", "little", "least"], a: 1, t: "T53", d: 1800, why: "less + 原級 + than で「〜ほど…でない」.訓練の時間が短くなる,という後半とも合う.", ja: "新しい手順は前ほど複雑ではないので,研修の時間が短くて済む.", x: ["fewer は数えられる名詞の前に置く.形容詞の前は less.", "", "little は比較級ではないので than と組まない.", "least は最上級で,than と組まない."] },
  { id: "g528", q: "All forms must be submitted prior ____ the meeting.", c: ["before", "than", "to", "from"], a: 2, t: "T53", d: 1800, why: "prior to 〜 で「〜より前に」.superior / inferior と同じく to をとる.", ja: "用紙はすべて会議の前に提出しなければならない.", x: ["prior と before を重ねることはできない(before the meeting だけなら可).", "prior はラテン語由来の比較の語で,than ではなく to をとる.", "", "prior は from と組まない."] },
  { id: "g529", q: "Online sales were twice ____ in-store sales last quarter.", c: ["as high as", "higher than twice", "as higher as", "so high than"], a: 0, t: "T53", d: 2000, why: "倍数 + as + 原級 + as.twice as high as で「〜の2倍の高さ」.", ja: "前四半期,ネットの売上は店頭の売上の2倍だった.", x: ["", "倍数は比較の前に置く(twice as high as).", "as と as の間は原級.", "so と than は組まない."] },
  { id: "g530", q: "This option is ____ expensive of all the plans we considered.", c: ["the less", "the least", "less", "lesser"], a: 1, t: "T53", d: 1800, why: "of all 〜 は最上級の範囲.「最も〜でない」は the least + 原級.", ja: "この案は検討したすべての案の中で最も安い.", x: ["of all 〜(すべての中で)なので最上級.", "", "the がなく比較級なので,of all と合わない.", "lesser は形容詞の前に置けない."] },
  { id: "g531", q: "Neither the manager nor the employees ____ aware of the change.", c: ["has been", "was", "is", "were"], a: 3, t: "T54", d: 1700, why: "neither A nor B は動詞に近い B に一致する.the employees は複数なので were.", ja: "部長も社員も,その変更に気づいていなかった.", x: ["has は単数.B(the employees)は複数.", "neither A nor B は近い方の B(the employees)に一致する.was は単数.", "is は単数.B(the employees)は複数.", ""] },
  { id: "g532", q: "Some of the furniture ____ damaged during the move.", c: ["was", "were", "are", "have"], a: 0, t: "T54", d: 2000, why: "some of / half of / most of の数は of の後ろの名詞で決める.furniture は数えられない名詞なので単数扱い.", ja: "家具の一部が引っ越しの間に傷ついた.", x: ["", "furniture は数えられない名詞なので,some of the furniture は単数扱い.", "単数扱いで,during the move(過去)なので過去形.", "単数扱いで,have damaged だと「傷つけた」になり意味も合わない."] },
  { id: "g533", q: "The majority of the staff members ____ in favor of the new schedule.", c: ["is", "are", "was", "has"], a: 1, t: "T54", d: 1900, why: "the majority of / most of / half of / some of は of の後ろの名詞で数を決める.staff members は複数.", ja: "職員の大多数が新しい日程に賛成している.", x: ["the majority of + 複数名詞 は複数扱い.", "", "was は単数.", "has は単数で,後ろに in favor も続かない."] },
  { id: "g534", q: "Half of the budget ____ already been spent.", c: ["are", "have", "has", "were"], a: 2, t: "T54", d: 1800, why: "half of の後ろの名詞で数を決める.the budget は数えられない名詞なので単数扱い.has been spent.", ja: "予算の半分はすでに使われた.", x: ["are の後ろに been は続かない.", "half of の後ろの the budget は単数(数えられない)なので単数扱い.", "", "were の後ろに been は続かない."] },
  { id: "g535", q: "A total of 50 people ____ attended the seminar.", c: ["have", "has", "is", "was"], a: 0, t: "T54", d: 2100, why: "a total of + 複数名詞(合計〜の)は複数扱い.the total(合計そのもの)なら単数扱い.", ja: "合計50人がセミナーに出席した.", x: ["", "a total of + 複数名詞 は複数扱い(a number of と同じ).", "is の後ろに attended は続かない.", "was attended だと受け身になり,目的語 the seminar と合わない."] },
  { id: "g536", q: "Either the director or her assistants ____ going to present the report.", c: ["is", "are", "has", "was"], a: 1, t: "T54", d: 2000, why: "either A or B は動詞に近い B に一致する.her assistants は複数なので are.", ja: "部長か,その助手たちが報告を発表する予定だ.", x: ["either A or B は近い B(her assistants)に一致するので複数.", "", "has の後ろに going は続かない.", "was は単数.B(her assistants)は複数."] },
  { id: "g537", q: "Mathematics ____ one of the subjects covered in the training.", c: ["were", "are", "is", "have"], a: 2, t: "T54", d: 2200, why: "mathematics / economics / news などは -s で終わるが単数扱い.", ja: "数学は研修で扱う科目の1つだ.", x: ["単数扱いなので were は使わない.", "mathematics は -s で終わるが単数扱い.", "", "単数扱いで,have one of the subjects では意味も合わない."] },
  { id: "g538", q: "The number of applicants who ____ passed the exam is small.", c: ["was", "has", "is", "have"], a: 3, t: "T54", d: 2500, why: "関係代名詞 who の動詞は先行詞 applicants(複数)に一致する.文全体の動詞 is は The number に一致.", ja: "試験に合格した応募者の数は少ない.", x: ["was passed だと「合格させられた」になり意味が合わない.", "who の先行詞は applicants(複数).the number(単数)につられない.", "is の後ろに passed は続かない.", ""] },
  { id: "g539", q: "Every manager and every employee ____ required to attend the briefing.", c: ["are", "is", "were", "have"], a: 1, t: "T54", d: 2600, why: "every A and every B,each A and each B は単数扱い.", ja: "全管理職と全社員が説明会への出席を求められている.", x: ["every A and every B は単数扱い.", "", "単数扱いで,時制も文脈に合わない.", "単数扱いで,have required だと「求めた」となり意味も合わない."] },
  { id: "g540", q: "The news about the merger ____ surprised many employees.", c: ["are", "have", "has", "were"], a: 2, t: "T54", d: 2100, why: "news は単数扱い.has surprised(驚かせた)で,後ろに目的語 many employees が続く.", ja: "合併の知らせは多くの社員を驚かせた.", x: ["are surprised だと受け身になり,目的語 many employees と合わない.", "news は -s で終わるが単数扱い.", "", "were surprised だと受け身になり,目的語と合わない.数も合わない."] },

  // ---- 易しい定理(灰・茶.中学の範囲) ----
  { id: "g541", q: "Ms. Chen ____ to work by bus every day.", c: ["goes", "go", "going", "to go"], a: 0, t: "T55", d: 150, why: "主語 Ms. Chen は3人称単数で,毎日のこと(今の習慣).go に -es を付けて goes.", ja: "チェンさんは毎日バスで通勤している.", x: ["", "主語 Ms. Chen は3人称単数なので,-es が必要.", "-ing だけでは動詞にならない(is going なら可).", "to go だけでは動詞にならない."] },
  { id: "g542", q: "The store ____ at 10 A.M. on weekdays.", c: ["open", "opens", "opening", "are open"], a: 1, t: "T55", d: 150, why: "主語 The store は単数.いつものことなので opens.", ja: "その店は平日は午前10時に開く.", x: ["The store は単数なので -s が必要.", "", "-ing だけでは動詞にならない.", "are は複数の主語に使う."] },
  { id: "g543", q: "My manager ____ coffee in the morning.", c: ["drinking", "drink", "drinks", "drunk"], a: 2, t: "T55", d: 200, why: "主語 My manager は3人称単数.drinks.", ja: "私の上司は朝にコーヒーを飲む.", x: ["-ing だけでは動詞にならない.", "主語は3人称単数なので,-s / -es が必要.", "", "drunk は過去分詞で,1語では動詞にならない."] },
  { id: "g544", q: "He ____ not work on Sundays.", c: ["are", "do", "is", "does"], a: 3, t: "T55", d: 300, why: "一般動詞の否定は do not / does not + 原形.主語 He は3人称単数なので does.", ja: "彼は日曜日は働かない.", x: ["are は複数の主語に使う.", "主語 He は3人称単数.do は I / you / 複数の主語に使う.", "work は一般動詞なので,is not work とはいわない.", ""] },
  { id: "g545", q: "Does the hotel ____ a pool?", c: ["has", "have", "having", "to have"], a: 1, t: "T55", d: 300, why: "Does の文では,-s は does に付いているので,動詞は原形 have.", ja: "そのホテルにはプールがありますか.", x: ["Does の後ろは原形.has は形が変わっている.", "", "Does の後ろに -ing は使わない.", "Does の後ろに to は付けない."] },
  { id: "g546", q: "Each room ____ a view of the sea.", c: ["are", "have", "having", "has"], a: 3, t: "T55", d: 300, why: "each room は単数扱い.have は3人称単数で has になる.", ja: "どの部屋からも海が見える.", x: ["are は複数の主語に使い,後ろに a view も続かない.", "each + 単数名詞 は単数扱いなので has.", "-ing だけでは動詞にならない.", ""] },
  { id: "g547", q: "Our team ____ every Monday morning.", c: ["meets", "meet", "meeting", "are meet"], a: 0, t: "T55", d: 200, why: "主語 Our team は単数.いつものことなので meets.", ja: "私たちのチームは毎週月曜の朝に集まる.", x: ["", "Our team は1つのチーム(単数)なので -s が必要.", "-ing だけでは動詞にならない.", "are と meet を並べることはできない."] },
  { id: "g548", q: "The bus ____ every 15 minutes.", c: ["coming", "come", "comes", "to come"], a: 2, t: "T55", d: 150, why: "主語 The bus は単数.comes.", ja: "バスは15分ごとに来る.", x: ["-ing だけでは動詞にならない.", "The bus は単数なので -s が必要.", "", "to come だけでは動詞にならない."] },
  { id: "g549", q: "Mr. Sato and his assistant ____ in the same office.", c: ["is working", "works", "working", "work"], a: 3, t: "T55", d: 400, why: "A and B は複数.主語が複数なら動詞に -s は付けない.work.", ja: "佐藤さんと助手は同じ事務所で働いている.", x: ["is は単数の主語に使う(are working なら可).", "主語は Mr. Sato と his assistant の2人(複数)なので -s は付けない.", "-ing だけでは動詞にならない.", ""] },
  { id: "g550", q: "This printer ____ 30 pages a minute.", c: ["printing", "print", "prints", "to print"], a: 2, t: "T55", d: 200, why: "主語 This printer は単数.prints.", ja: "このプリンターは1分に30枚印刷する.", x: ["-ing だけでは動詞にならない.", "This printer は単数なので -s が必要.", "", "to print だけでは動詞にならない."] },
  { id: "g551", q: "I ____ a new employee here.", c: ["is", "am", "are", "be"], a: 1, t: "T56", d: 100, why: "主語が I なら am.", ja: "私はここの新入社員です.", x: ["I には am を使う.", "", "are は you や複数の主語に使う.", "be は原形で,I の後ろにそのまま置けない."] },
  { id: "g552", q: "The documents ____ on your desk.", c: ["am", "is", "are", "be"], a: 2, t: "T56", d: 200, why: "主語 The documents は複数なので are.", ja: "書類はあなたの机の上にあります.", x: ["am は I にだけ使う.", "The documents は複数なので are.", "", "be は原形で,主語の後ろにそのまま置けない."] },
  { id: "g553", q: "The weather ____ very cold yesterday.", c: ["are", "were", "is", "was"], a: 3, t: "T56", d: 200, why: "yesterday(過去)で,主語 The weather は単数なので was.", ja: "昨日はとても寒かった.", x: ["yesterday なので過去形で,主語も単数.", "The weather は単数なので was.", "yesterday なので過去形.", ""] },
  { id: "g554", q: "We ____ at the airport two hours ago.", c: ["were", "was", "are", "is"], a: 0, t: "T56", d: 300, why: "two hours ago は過去.主語 We は複数なので were.", ja: "私たちは2時間前に空港にいた.", x: ["", "We は複数なので were.", "two hours ago(過去)なので過去形.", "過去のことで,主語も複数."] },
  { id: "g555", q: "There ____ a problem with the printer.", c: ["am", "are", "is", "be"], a: 2, t: "T56", d: 200, why: "There is / are の文では,後ろの名詞が主語.a problem は単数なので is.", ja: "プリンターに問題がある.", x: ["am は I にだけ使う.", "後ろの a problem は単数なので is.", "", "be は原形で,There の後ろにそのまま置けない."] },
  { id: "g556", q: "The meeting room ____ not available now.", c: ["is", "are", "am", "be"], a: 0, t: "T56", d: 200, why: "主語 The meeting room は単数.now なので現在形 is.", ja: "会議室は今使えない.", x: ["", "The meeting room は単数なので is.", "am は I にだけ使う.", "be は原形で,主語の後ろにそのまま置けない."] },
  { id: "g557", q: "____ you busy tomorrow afternoon?", c: ["Is", "Are", "Am", "Do"], a: 1, t: "T56", d: 200, why: "busy(形容詞)の文なので be 動詞.主語が you なので Are.", ja: "明日の午後はお忙しいですか.", x: ["you には are を使う.", "", "am は I にだけ使う.", "busy は形容詞なので,一般動詞の Do ではなく be 動詞."] },
  { id: "g558", q: "My colleagues ____ in Tokyo last week.", c: ["is", "was", "are", "were"], a: 3, t: "T56", d: 300, why: "last week は過去.主語 My colleagues は複数なので were.", ja: "同僚たちは先週東京にいた.", x: ["過去のことで,主語も複数.", "My colleagues は複数なので were.", "last week(過去)なので過去形.", ""] },
  { id: "g559", q: "Everyone ____ welcome to join the party.", c: ["is", "are", "were", "be"], a: 0, t: "T56", d: 500, why: "everyone / everybody は単数扱いなので is.", ja: "どなたでもパーティーに参加できます.", x: ["", "everyone は「全員」だが単数扱い.", "単数扱いで,今のこと.", "be は原形で,主語の後ろにそのまま置けない."] },
  { id: "g560", q: "The new chairs ____ very comfortable.", c: ["be", "is", "was", "are"], a: 3, t: "T56", d: 200, why: "主語 The new chairs は複数なので are.", ja: "新しい椅子はとても座り心地がよい.", x: ["be は原形で,主語の後ろにそのまま置けない.", "The new chairs は複数なので are.", "was は単数の主語に使う.", ""] },
  { id: "g561", q: "I have ____ appointment at three.", c: ["the", "a", "an", "some"], a: 2, t: "T57", d: 200, why: "appointment は母音の音(ア)で始まり,数えられる名詞の単数なので an.", ja: "3時に約束がある.", x: ["初めて話題にする予約なので,the ではなく a / an.", "appointment は母音の音で始まるので an.", "", "some は数えられる名詞の単数とは使わない."] },
  { id: "g562", q: "She works as ____ engineer.", c: ["many", "a", "much", "an"], a: 3, t: "T57", d: 200, why: "engineer は母音の音(エ)で始まるので an.", ja: "彼女は技師として働いている.", x: ["many は複数の名詞に使う.", "engineer は母音の音で始まるので an.", "much は数えられない名詞に使う.", ""] },
  { id: "g563", q: "He is ____ university student.", c: ["a", "an", "much", "many"], a: 0, t: "T57", d: 400, why: "a / an はつづりではなく音で決める.university は「ユ」の音で始まるので a.", ja: "彼は大学生だ.", x: ["", "university は u で始まるが「ユ」の音(子音)で始まるので a.", "much は数えられない名詞に使う.", "many は複数の名詞に使う."] },
  { id: "g564", q: "____ sun rises in the east.", c: ["A", "The", "An", "Some"], a: 1, t: "T57", d: 300, why: "太陽のように1つしかないものには the.", ja: "太陽は東から昇る.", x: ["太陽は1つしかないので the.", "", "sun は子音で始まるうえ,1つしかないものには the.", "some は1つしかないものには使わない."] },
  { id: "g565", q: "I bought ____ umbrella at the station.", c: ["many", "a", "much", "an"], a: 3, t: "T57", d: 200, why: "umbrella は母音の音(ア)で始まるので an.", ja: "駅で傘を買った.", x: ["many は複数の名詞に使う.", "umbrella は母音の音で始まるので an.", "much は数えられない名詞に使う.", ""] },
  { id: "g566", q: "This is ____ best hotel in the city.", c: ["a", "the", "an", "much"], a: 1, t: "T57", d: 400, why: "best は最上級.最上級には the.", ja: "ここは市内で一番よいホテルだ.", x: ["最上級(best)には the を付ける.", "", "最上級(best)には the を付ける.", "much は名詞の前に置けない(数えられる名詞の単数には使わない)."] },
  { id: "g567", q: "We need ____ new printer for the office.", c: ["much", "an", "a", "many"], a: 2, t: "T57", d: 200, why: "数えられる名詞 printer の単数.直後の new が子音で始まるので a.", ja: "事務所に新しいプリンターが必要だ.", x: ["much は数えられない名詞に使う.", "new は子音で始まるので a.", "", "many は複数の名詞に使う(printer は単数)."] },
  { id: "g568", q: "Ms. Lee is ____ honest person.", c: ["an", "a", "much", "many"], a: 0, t: "T57", d: 500, why: "honest の h は発音しない.母音の音(オ)で始まるので an.", ja: "リーさんは正直な人だ.", x: ["", "honest の h は発音せず,母音の音で始まるので an.", "much は数えられない名詞に使う.", "many は複数の名詞に使う."] },
  { id: "g569", q: "Please turn off ____ lights when you leave the room.", c: ["a", "the", "an", "much"], a: 1, t: "T57", d: 400, why: "話し手と聞き手が分かっている,その部屋の明かり.複数でも the.", ja: "部屋を出るときは明かりを消してください.", x: ["lights は複数なので a は付けない.", "", "lights は複数なので an は付けない.", "much は数えられない名詞に使う."] },
  { id: "g570", q: "Our office is on ____ third floor.", c: ["the", "a", "an", "much"], a: 0, t: "T57", d: 400, why: "first, second, third など順番を表す語には the.", ja: "私たちの事務所は3階にある.", x: ["", "third(3番目)のような順番の語には the を付ける.", "third は子音で始まり,順番の語には the.", "much は名詞の前に置けない."] },
  { id: "g571", q: "____ is the meeting? — It's in Room 3.", c: ["Why", "When", "Who", "Where"], a: 3, t: "T58", d: 100, why: "答えが場所(in Room 3)なので,場所を尋ねる Where.", ja: "会議はどこですか.— 3号室です.", x: ["答えは理由ではなく場所.", "答えは場所(in Room 3)なので Where.When は時を尋ねる.", "答えは人ではなく場所.", ""] },
  { id: "g572", q: "____ does the store open? — At 9 A.M.", c: ["When", "Where", "Who", "How much"], a: 0, t: "T58", d: 200, why: "答えが時刻なので,時を尋ねる When.", ja: "その店はいつ開きますか.— 午前9時です.", x: ["", "答えは時刻(At 9 A.M.)なので,場所の Where ではない.", "答えは人ではなく時刻.", "How much は量・値段を尋ねる."] },
  { id: "g573", q: "____ will lead the training? — Ms. Kato will.", c: ["What", "Who", "Where", "How"], a: 1, t: "T58", d: 200, why: "答えが人なので,人を尋ねる Who.", ja: "誰が研修を担当しますか.— 加藤さんです.", x: ["答えは人(Ms. Kato)なので Who.", "", "答えは場所ではなく人.", "答えは方法ではなく人."] },
  { id: "g574", q: "____ did you get to the office? — By train.", c: ["Where", "Why", "How", "What"], a: 2, t: "T58", d: 200, why: "答えが手段(電車で)なので,方法を尋ねる How.", ja: "事務所へはどうやって来ましたか.— 電車です.", x: ["答えは場所ではなく手段.", "答えは手段(By train)で,理由ではない.", "", "答えは物ではなく手段."] },
  { id: "g575", q: "____ is this jacket? — It's $50.", c: ["How much", "How many", "How long", "How often"], a: 0, t: "T58", d: 300, why: "答えが値段なので How much.", ja: "この上着はいくらですか.— 50ドルです.", x: ["", "How many は数を尋ねる.値段は How much.", "How long は期間・長さを尋ねる.", "How often は回数・頻度を尋ねる."] },
  { id: "g576", q: "____ people will attend? — About 30.", c: ["How long", "How much", "How many", "What"], a: 2, t: "T58", d: 300, why: "答えが人数なので,数を尋ねる How many.", ja: "何人出席しますか.— 30人ほどです.", x: ["How long は期間・長さを尋ねる.", "How much は数えられないものの量や値段.人数は How many.", "", "What people だと「どんな人」になり,答え(About 30)と合わない."] },
  { id: "g577", q: "____ was the flight canceled? — Because of the snow.", c: ["Where", "When", "How", "Why"], a: 3, t: "T58", d: 300, why: "答えが Because of 〜(理由)なので Why.", ja: "なぜその便は欠航になったのですか.— 雪のためです.", x: ["答えは場所ではなく理由.", "答えは理由(Because of 〜)なので Why.", "答えは方法ではなく理由.", ""] },
  { id: "g578", q: "____ does the workshop last? — Two hours.", c: ["How many", "How long", "How much", "When"], a: 1, t: "T58", d: 400, why: "last は「続く」.答えが時間の長さなので How long.", ja: "研修はどれくらい続きますか.— 2時間です.", x: ["How many は数を尋ね,後ろに名詞が要る.", "", "How much は量・値段を尋ねる.", "When does the workshop last とはいわない.時刻を聞くなら When does it start."] },
  { id: "g579", q: "____ color do you prefer, blue or green? — Blue.", c: ["Where", "Who", "Which", "How"], a: 2, t: "T58", d: 400, why: "blue or green の2つから選ぶので Which(どちらの).", ja: "青と緑,どちらの色がいいですか.— 青です.", x: ["Where は場所を尋ねる.", "Who は人を尋ねる.", "", "How は方法・様子を尋ね,後ろに名詞 color は続かない."] },
  { id: "g580", q: "____ do you check your e-mail? — Every morning.", c: ["How long", "How often", "How many", "Which"], a: 1, t: "T58", d: 500, why: "答えが Every morning(毎朝)という頻度なので How often.", ja: "どれくらいの頻度でメールを確認しますか.— 毎朝です.", x: ["How long は期間・長さを尋ねる.Every morning は頻度.", "", "How many は数を尋ね,後ろに名詞が要る.", "Which は選択肢から選ぶときに使う."] },
  { id: "g581", q: "You can ____ the tickets online.", c: ["buy", "buys", "buying", "to buy"], a: 0, t: "T59", d: 200, why: "助動詞 can の後ろは原形 buy.", ja: "チケットはネットで買える.", x: ["", "can の後ろは原形.", "can の後ろに -ing は使わない.", "can の後ろに to は付けない."] },
  { id: "g582", q: "She will ____ the report tomorrow.", c: ["sends", "send", "sent", "sending"], a: 1, t: "T59", d: 200, why: "助動詞 will の後ろは原形 send.", ja: "彼女は明日報告書を送る.", x: ["will の後ろは原形.主語が単数でも -s は付けない.", "", "will の後ろに過去形は使わない.", "will の後ろに -ing だけでは使わない(will be sending なら可)."] },
  { id: "g583", q: "All visitors must ____ a badge.", c: ["wearing", "wears", "wear", "to wear"], a: 2, t: "T59", d: 300, why: "助動詞 must の後ろは原形 wear.", ja: "来訪者は全員バッジを着けなければならない.", x: ["must の後ろに -ing は使わない.", "must の後ろは原形.", "", "must の後ろに to は付けない(have to wear なら可)."] },
  { id: "g584", q: "The train may ____ late because of the snow.", c: ["being", "is", "are", "be"], a: 3, t: "T59", d: 400, why: "助動詞の後ろの be 動詞は原形 be.", ja: "雪のため電車は遅れるかもしれない.", x: ["may の後ろに -ing は使わない.", "may の後ろは原形.is の原形は be.", "may の後ろは原形 be.", ""] },
  { id: "g585", q: "Could you ____ me the file?", c: ["sending", "send", "sent", "to send"], a: 1, t: "T59", d: 200, why: "Could you + 原形 で「〜していただけますか」.", ja: "そのファイルを送っていただけますか.", x: ["Could you の後ろは原形.", "", "Could の後ろに過去形は使わない(Could 自体が丁寧な形).", "Could の後ろに to は付けない."] },
  { id: "g586", q: "You should ____ an umbrella today.", c: ["to take", "takes", "taking", "take"], a: 3, t: "T59", d: 200, why: "助動詞 should の後ろは原形 take.", ja: "今日は傘を持っていった方がいい.", x: ["should の後ろに to は付けない.", "should の後ろは原形.", "should の後ろに -ing は使わない.", ""] },
  { id: "g587", q: "The new system will ____ costs.", c: ["reduce", "reduces", "reducing", "reduced"], a: 0, t: "T59", d: 300, why: "助動詞 will の後ろは原形 reduce.", ja: "新しいシステムで費用が減るだろう.", x: ["", "will の後ろは原形.主語が単数でも -s は付けない.", "will の後ろに -ing だけでは使わない.", "will の後ろに過去形・過去分詞は使わない."] },
  { id: "g588", q: "He can't ____ to the party tonight.", c: ["coming", "comes", "come", "came"], a: 2, t: "T59", d: 300, why: "can't(cannot)も助動詞.後ろは原形 come.", ja: "彼は今夜のパーティーに来られない.", x: ["can't の後ろに -ing は使わない.", "can't の後ろは原形.", "", "can't の後ろに過去形は使わない."] },
  { id: "g589", q: "Customers must ____ their receipts for returns.", c: ["keeping", "keeps", "kept", "keep"], a: 3, t: "T59", d: 300, why: "助動詞 must の後ろは原形 keep.", ja: "返品には領収書が必要なので,客は保管しておかなければならない.", x: ["must の後ろに -ing は使わない.", "must の後ろは原形.", "must の後ろに過去形は使わない.", ""] },
  { id: "g590", q: "The package might ____ tomorrow.", c: ["arriving", "arrives", "arrive", "arrived"], a: 2, t: "T59", d: 300, why: "might(〜かもしれない)も助動詞.後ろは原形 arrive.", ja: "荷物は明日届くかもしれない.", x: ["might の後ろに -ing は使わない.", "might の後ろは原形.", "", "might の後ろに過去形は使わない."] },
  { id: "g591", q: "The room is large ____ bright.", c: ["but", "and", "or", "so"], a: 1, t: "T60", d: 200, why: "似た内容(よい点)を足すので and.", ja: "その部屋は広くて明るい.", x: ["large(広い)と bright(明るい)はどちらもよい点で,反対の内容ではない.", "", "「広いか明るいか」のどちらかを選ぶ意味ではない.", "「広いので明るい」という理由と結果の関係ではない."] },
  { id: "g592", q: "The printer is new, ____ it is already broken.", c: ["or", "and", "but", "so"], a: 2, t: "T60", d: 300, why: "「新しい」と「もう壊れた」は反対の内容.but.", ja: "そのプリンターは新しいのに,もう壊れている.", x: ["どちらかを選ぶ意味ではない.", "and では「新しいのにもう壊れた」という意外さを表せない.", "", "「新しいので壊れた」は理由と結果にならない."] },
  { id: "g593", q: "You can pay by cash ____ credit card.", c: ["because", "but", "so", "or"], a: 3, t: "T60", d: 200, why: "現金かカードのどちらかを選ぶので or.", ja: "現金かクレジットカードで払える.", x: ["because の後ろには理由の文(主語 + 動詞)が来る.", "反対の内容をつなぐのではなく,支払い方法を選ぶ.", "理由と結果の関係ではない.", ""] },
  { id: "g594", q: "It was raining, ____ we stayed inside.", c: ["so", "but", "or", "because"], a: 0, t: "T60", d: 200, why: "前が理由(雨だった),後ろが結果(中にいた)なので so.", ja: "雨が降っていたので,私たちは中にいた.", x: ["", "雨だったことは中にいた理由なので,反対の but ではない.", "どちらかを選ぶ意味ではない.", "because だと「中にいたので雨が降った」になり逆."] },
  { id: "g595", q: "I called the office, ____ no one answered.", c: ["or", "so", "but", "because"], a: 2, t: "T60", d: 300, why: "電話した(期待)のに誰も出なかった(反対の結果)ので but.", ja: "事務所に電話したが,誰も出なかった.", x: ["どちらかを選ぶ意味ではない.", "電話したことは誰も出なかった理由にならない.", "", "「誰も出なかったので電話した」になり意味が合わない."] },
  { id: "g596", q: "The train was late, ____ I missed the meeting.", c: ["so", "but", "or", "because"], a: 0, t: "T60", d: 300, why: "前が理由(電車が遅れた),後ろが結果(会議に出られなかった)なので so.", ja: "電車が遅れたので,会議に出られなかった.", x: ["", "電車が遅れたことは会議に遅れた理由なので,反対の but ではない.", "どちらかを選ぶ意味ではない.", "because だと「会議に出られなかったので電車が遅れた」になり逆."] },
  { id: "g597", q: "Please call ____ e-mail me if you have questions.", c: ["but", "or", "so", "because"], a: 1, t: "T60", d: 200, why: "電話かメールのどちらかなので or.", ja: "質問があれば,電話かメールでご連絡ください.", x: ["反対の内容ではなく,連絡の方法を選ぶ.", "", "理由と結果の関係ではない.", "because の後ろには理由の文が来る."] },
  { id: "g598", q: "She speaks English ____ Spanish.", c: ["because", "but", "so", "and"], a: 3, t: "T60", d: 200, why: "話せる言語を足していくので and.", ja: "彼女は英語とスペイン語を話す.", x: ["because の後ろには理由の文が来る.", "英語とスペイン語は反対の内容ではない.", "理由と結果の関係ではない.", ""] },
  { id: "g599", q: "The tickets were expensive, ____ we bought them anyway.", c: ["but", "so", "or", "because"], a: 0, t: "T60", d: 400, why: "高かった(買わない理由)のに買った.反対の内容なので but.anyway(それでも)が手がかり.", ja: "チケットは高かったが,それでも買った.", x: ["", "高かったことは買った理由ではない.anyway(それでも)とも合わない.", "どちらかを選ぶ意味ではない.", "「買ったので高かった」になり意味が合わない."] },
  { id: "g600", q: "Hurry up, ____ you will miss the bus.", c: ["so", "and", "but", "or"], a: 3, t: "T60", d: 600, why: "命令文 + or で「〜しなさい,さもないと…」.", ja: "急ぎなさい,さもないとバスに乗り遅れますよ.", x: ["so だと「急ぐので乗り遅れる」になり意味が合わない.", "命令文 + and は「そうすれば〜」.急げばバスに乗り遅れる,では意味が逆.", "but は命令文の後ろで「さもないと」の意味にならない.", ""] },

  // ---- 難しい定理(不定詞・動名詞の完了形と受け身,強調構文,助動詞 + have + 過去分詞) ----
  { id: "g601", q: "The package is expected ____ by Friday.", c: ["to be delivered", "to deliver", "delivering", "to have delivered"], a: 0, t: "T61", d: 1600, why: "package は届けられる側.be expected to の後ろを受け身にして to be delivered.", ja: "荷物は金曜日までに届く見込みだ.", x: ["", "荷物は「届けられる」側なので受け身にする.", "be expected の後ろに -ing は使わない.", "能動の形で,荷物が届ける側になってしまう."] },
  { id: "g602", q: "The documents seem ____ lost during the move.", c: ["to be", "to have been", "being", "having"], a: 1, t: "T61", d: 2200, why: "seem(今)より前の引っ越しのときに失われた.前のことで受け身なので to have been + 過去分詞.", ja: "書類は引っ越しの間に紛失したようだ.", x: ["引っ越しの間(過去)に失われたので,今より前のことは to have been.", "", "seem の後ろに -ing は使わない.", "seem の後ろには to が要る."] },
  { id: "g603", q: "He denied ____ the confidential files.", c: ["to take", "to have taken", "having taken", "take"], a: 2, t: "T61", d: 2100, why: "deny は -ing をとる.持ち出したのは否定したより前なので having taken.", ja: "彼は機密書類を持ち出したことを否定した.", x: ["deny は to do をとらない.", "deny は to do をとらない(-ing をとる).", "", "原形は deny の目的語にならない."] },
  { id: "g604", q: "Ms. Chen is excited about ____ to manager.", c: ["promoted", "promoting", "to be promoted", "being promoted"], a: 3, t: "T61", d: 2000, why: "前置詞 about の後ろは動名詞.昇進させられる側なので being promoted.", ja: "チェンさんは部長に昇進することを楽しみにしている.", x: ["前置詞の後ろに過去分詞だけは置けない.", "昇進するのは「させられる」側なので受け身.promoting だと誰かを昇進させる意味になる.", "about は前置詞なので,後ろは to do ではなく -ing.", ""] },
  { id: "g605", q: "The report is said ____ by a famous economist.", c: ["to have written", "to have been written", "to be writing", "having been written"], a: 1, t: "T61", d: 2600, why: "報告書は書かれる側で,書かれたのは今より前.to have been + 過去分詞.", ja: "その報告書は有名な経済学者が書いたと言われている.", x: ["報告書は「書かれる」側なので受け身.", "", "進行形の能動で,報告書が書いている意味になる.", "be said の後ろには to が要る."] },
  { id: "g606", q: "I regret not ____ the contract more carefully.", c: ["to read", "to have read", "read", "having read"], a: 3, t: "T61", d: 2300, why: "regret + -ing で過去のことへの後悔.読まなかったのは前のことなので not having read.", ja: "契約書をもっと注意深く読まなかったことを後悔している.", x: ["regret to do は「残念ながら〜する(これから)」の意味になる.", "regret to do は「残念ながら〜する」で,過去の後悔には -ing を使う.", "not の後ろに原形を置くと文の形にならない.", ""] },
  { id: "g607", q: "The building needs ____ before the inspection.", c: ["painting", "to paint", "to have painted", "painted"], a: 0, t: "T61", d: 2400, why: "need + -ing で「〜される必要がある」.建物は塗られる側.", ja: "点検の前に建物のペンキを塗り直す必要がある.", x: ["", "need to paint だと建物がペンキを塗る側になる(受け身なら to be painted).", "建物が塗る側になり,意味が合わない.", "need の後ろに過去分詞だけは置けない."] },
  { id: "g608", q: "She appears ____ the company before I joined.", c: ["leaving", "to leave", "to have left", "having left"], a: 2, t: "T61", d: 2300, why: "appears(今)より前,私が入社する前に辞めた.前のことなので to have + 過去分詞.", ja: "彼女は私が入社する前に会社を辞めたらしい.", x: ["appear の後ろに -ing は使わない.", "辞めたのは私が入社する前(過去)なので,to have left.", "", "appear の後ろには to が要る."] },
  { id: "g609", q: "Thank you for ____ me to the meeting.", c: ["to invite", "to have invited", "invite", "having invited"], a: 3, t: "T61", d: 1900, why: "前置詞 for の後ろは動名詞.招いたのはお礼より前なので having invited(inviting でもよい).", ja: "会議に招いていただきありがとうございました.", x: ["for は前置詞なので,後ろは -ing.", "for は前置詞なので,後ろは to do ではなく -ing.", "前置詞の後ろに原形は置けない.", ""] },
  { id: "g610", q: "The results are believed ____ by an error in the data.", c: ["to affect", "to have affected", "to have been affected", "affecting"], a: 2, t: "T61", d: 2900, why: "結果は影響を受けた側で,それは今より前.to have been + 過去分詞.", ja: "その結果はデータの誤りの影響を受けたと考えられている.", x: ["能動で,結果が何かに影響する意味になる.", "結果は「影響を受ける」側なので受け身.", "", "be believed の後ろに -ing は使わない."] },
  { id: "g611", q: "It was Ms. Tanaka ____ designed the new logo.", c: ["which", "who", "what", "whom"], a: 1, t: "T62", d: 1800, why: "It was + 人 + who(that)〜 で「〜したのは…だった」.", ja: "新しいロゴをデザインしたのは田中さんだった.", x: ["強調しているのは人(Ms. Tanaka)なので which は使わない.", "", "what は先行詞がないときの語で,強調構文には使わない.", "designed の主語になるので,目的格の whom は使わない."] },
  { id: "g612", q: "It was not until the end of the meeting ____ we reached an agreement.", c: ["then", "when", "that", "before"], a: 2, t: "T62", d: 2400, why: "It was not until 〜 that … で「〜して初めて…した」.", ja: "会議の終わりになって,ようやく合意に達した.", x: ["then は副詞で,節をつなげない.", "It was not until 〜 that … は決まった形.", "", "「〜の前に」では意味が合わない."] },
  { id: "g613", q: "It is customer feedback ____ helps us improve our products.", c: ["where", "what", "who", "that"], a: 3, t: "T62", d: 2200, why: "It is + 強調する語句 + that 〜.物を強調するときは that.", ja: "製品の改善に役立つのは顧客の声だ.", x: ["場所ではない.", "what は先行詞のないときの語.強調構文は It is 〜 that.", "強調しているのは物(customer feedback)なので who は使わない.", ""] },
  { id: "g614", q: "It was in 2015 ____ the company opened its first overseas office.", c: ["that", "which", "what", "who"], a: 0, t: "T62", d: 2600, why: "It と that を取ると The company opened ... in 2015 という文になる.強調構文なので that.", ja: "その会社が初めて海外事務所を開いたのは2015年だった.", x: ["", "in 2015 のような語句を強調するときは that.which は使わない.", "what は強調構文には使わない.", "人ではない."] },
  { id: "g615", q: "It is not the price but the quality ____ matters most.", c: ["it", "what", "that", "they"], a: 2, t: "T62", d: 2700, why: "not A but B を強調している.It is not A but B that 〜.", ja: "最も大切なのは価格ではなく品質だ.", x: ["it では節をつなげない.", "強調構文は It is 〜 that.what は使わない.", "", "they では節をつなげない."] },
  { id: "g616", q: "It was ____ the manager returned that the problem was solved.", c: ["not until", "until", "since", "by"], a: 0, t: "T62", d: 2800, why: "It was not until 〜 that … で「〜して初めて…」.部長が戻って初めて問題が解決した.", ja: "部長が戻って初めて,その問題は解決した.", x: ["", "until だけでは「戻るまで解決した」になり,意味が合わない.", "since(〜以来)では意味が合わない.", "by の後ろに節(主語 + 動詞)は置けない."] },
  { id: "g617", q: "It is because the store is close to the station ____ it is so popular.", c: ["so", "that", "why", "which"], a: 1, t: "T62", d: 2900, why: "because 節を強調している.It is because 〜 that … で「…なのは〜だからだ」.", ja: "その店がとても人気なのは,駅に近いからだ.", x: ["so では強調構文にならない.", "", "It is because 〜 that … の形.why は使わない.", "which は強調構文には使わない."] },
  { id: "g618", q: "It was Mr. Lopez, not his assistant, ____ answered the phone.", c: ["whose", "which", "whom", "who"], a: 3, t: "T62", d: 2000, why: "人(Mr. Lopez)を強調している.主語になるので who(that).", ja: "電話に出たのは助手ではなくロペスさんだった.", x: ["whose の後ろには名詞が要る.", "強調しているのは人なので which は使わない.", "answered の主語になるので,目的格の whom は使わない.", ""] },
  { id: "g619", q: "Was it you ____ left this umbrella in the meeting room?", c: ["who", "which", "what", "whom"], a: 0, t: "T62", d: 2300, why: "強調構文の疑問文.Was it + 人 + who 〜?", ja: "会議室にこの傘を忘れたのはあなたですか.", x: ["", "人(you)を強調しているので which は使わない.", "what は強調構文には使わない.", "left の主語になるので,目的格の whom は使わない."] },
  { id: "g620", q: "It is only when you try ____ you realize how difficult the task is.", c: ["which", "then", "so", "that"], a: 3, t: "T62", d: 3000, why: "only when you try を強調している.It is only when 〜 that … で「〜して初めて…」.", ja: "やってみて初めて,その仕事がどれほど難しいか分かる.", x: ["which は強調構文には使わない.", "then は副詞で節をつなげない.", "so では強調構文にならない.", ""] },
  { id: "g621", q: "The lights are off, so everyone ____ gone home.", c: ["can't have", "should have", "must have", "need not have"], a: 2, t: "T63", d: 1400, why: "明かりが消えているという根拠から「帰ったに違いない」.must have + 過去分詞.", ja: "明かりが消えているので,全員帰ったに違いない.", x: ["明かりが消えているのに「帰ったはずがない」では意味が逆.", "「帰るべきだったのに」では,明かりが消えている根拠と合わない.", "", "「帰る必要はなかったのに」では意味が合わない."] },
  { id: "g622", q: "You ____ told me about the delay; I could have changed my plans.", c: ["may have", "must have", "can't have", "should have"], a: 3, t: "T63", d: 1500, why: "教えてくれなかったことへの不満.should have + 過去分詞 で「〜すべきだったのに」.", ja: "遅れのことを教えてくれればよかったのに.予定を変えられたのに.", x: ["「話したかもしれない」では意味が合わない.", "「話したに違いない」では,後半(予定を変えられたのに)と合わない.", "「話したはずがない」では意味が合わない.", ""] },
  { id: "g623", q: "She ____ finished the report already; she only started an hour ago.", c: ["can't have", "must have", "should have", "need not have"], a: 0, t: "T63", d: 1800, why: "1時間前に始めたばかり → もう終えたはずがない.can't have + 過去分詞.", ja: "彼女がもう報告書を終えたはずがない.1時間前に始めたばかりだ.", x: ["", "1時間前に始めたばかりなので「終えたに違いない」は合わない.", "「終えるべきだったのに」では意味が合わない.", "「終える必要はなかったのに」では意味が合わない."] },
  { id: "g624", q: "I ____ left my phone in the taxi, but I'm not sure.", c: ["must have", "may have", "should have", "can't have"], a: 1, t: "T63", d: 1500, why: "確かではない推量なので may have + 過去分詞(〜したかもしれない).", ja: "タクシーに電話を置いてきたかもしれないが,確かではない.", x: ["I'm not sure(確かではない)と合わない.", "", "「置いておくべきだったのに」では意味が合わない.", "「置いたはずがない」では,but 以下とつながらない."] },
  { id: "g625", q: "We ____ hurried; the meeting started 30 minutes late.", c: ["should not", "must have", "can't have", "need not have"], a: 3, t: "T63", d: 2200, why: "会議は遅れて始まった → 急ぐ必要はなかったのに.need not have + 過去分詞.", ja: "急ぐ必要はなかった.会議は30分遅れて始まった.", x: ["should not の後ろは原形で,hurried(過去形)は続かない.", "会議が遅れて始まったことと,「急いだに違いない」はつながらない.", "「急いだはずがない」では意味が合わない.", ""] },
  { id: "g626", q: "Mr. Lee ____ received my e-mail, because he replied right away.", c: ["can't have", "must have", "need not have", "should have"], a: 1, t: "T63", d: 1600, why: "すぐ返事が来たという根拠から「受け取ったに違いない」.must have.", ja: "すぐに返事が来たので,リーさんは私のメールを受け取ったに違いない.", x: ["すぐ返事が来たのに「受け取ったはずがない」は逆.", "", "「受け取る必要はなかったのに」では意味が合わない.", "「受け取るべきだったのに」では,返事が来たことと合わない."] },
  { id: "g627", q: "The package ____ arrived yesterday, but it is still not here.", c: ["can't have", "must have", "should have", "may have"], a: 2, t: "T63", d: 1900, why: "昨日届くはずだったのに,まだ来ない.should have + 過去分詞 で「〜したはずなのに」.", ja: "小包は昨日届くはずだったのに,まだ来ていない.", x: ["「届いたはずがない」では but 以下とつながらない.", "まだ届いていないので「届いたに違いない」は合わない.", "", "まだ届いていないので「届いたかもしれない」は合わない."] },
  { id: "g628", q: "You ____ bought a new printer; we already had a spare one.", c: ["needn't have", "must have", "can't have", "may have"], a: 0, t: "T63", d: 2300, why: "予備があったので,買う必要はなかったのに.needn't(need not)have + 過去分詞.", ja: "新しいプリンターを買う必要はなかった.予備が1台あったのだから.", x: ["", "「買ったに違いない」では,予備があったことと合わない.", "「買ったはずがない」では意味が合わない.", "「買ったかもしれない」では意味が合わない."] },
  { id: "g629", q: "He looks tired. He ____ worked late last night.", c: ["should have", "must have", "need not have", "can't have"], a: 1, t: "T63", d: 1300, why: "疲れて見えるという根拠から「〜したに違いない」.must have + 過去分詞.", ja: "彼は疲れて見える.昨夜遅くまで働いたに違いない.", x: ["「遅くまで働くべきだったのに」では,疲れて見えることと合わない.", "", "「働く必要はなかったのに」では,根拠からの推量にならない.", "疲れて見えるのに「働いたはずがない」では逆."] },
  { id: "g630", q: "The error ____ been caused by the update, but we are still checking.", c: ["might have", "must have", "should have", "can't have"], a: 0, t: "T63", d: 2000, why: "まだ確かではないので might have + 過去分詞(〜したかもしれない).", ja: "その誤りは更新が原因かもしれないが,まだ調べている.", x: ["", "まだ調べている最中なので「〜に違いない」は強すぎる.", "「〜されるべきだったのに」では意味が合わない.", "「〜のはずがない」では but 以下とつながらない."] }
];
